# ---- PuTTY sessions ----------------------------------------------------------
function Test-RegistryPutty {
    param(
        [Parameter(Mandatory=$true)]$HiveRootKey,
        [Parameter(Mandatory=$true)][string]$HiveLabel,
        [Parameter(Mandatory=$true)][string]$View,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$SidPrefix,
        [Parameter(Mandatory=$true)][string]$DedupePrefix
    )
    $sessionsPath = $SidPrefix + 'Software\SimonTatham\PuTTY\Sessions'
    $sessionsKeyRec = Open-RegistrySubKey -BaseKey $HiveRootKey -SubKeyPath $sessionsPath
    if (-not (Test-RegOpenSuccess -Record $sessionsKeyRec -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionsPath))) { return }
    $sessionsKey = $sessionsKeyRec.Key
    try {
        $subRec = Get-RegistrySubKeyNames -Key $sessionsKey
        if (Test-RegistryEnumerationSuccess -Record $subRec -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionsPath) -Operation 'EnumerateSubKeys') {
            foreach ($sessionName in $subRec.Names) {
                $sessionPath = $sessionsPath + '\' + $sessionName
                $sessionKeyRec = Open-RegistrySubKey -BaseKey $sessionsKey -SubKeyPath $sessionName
                if (-not (Test-RegOpenSuccess -Record $sessionKeyRec -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath))) { continue }
                $sessionKey = $sessionKeyRec.Key
                try {
                    $hostName = ''; $userName = ''
                    $rh = Read-RegistryValue -Key $sessionKey -Name 'HostName'
                    if ((Test-RegistryReadSuccess -Record $rh -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath + '|HostName')) -and
                        $rh.Found -and $rh.Data -is [string]) { $hostName = $rh.Data }
                    $ru = Read-RegistryValue -Key $sessionKey -Name 'UserName'
                    if ((Test-RegistryReadSuccess -Record $ru -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath + '|UserName')) -and
                        $ru.Found -and $ru.Data -is [string]) { $userName = $ru.Data }
                    foreach ($valueName in @('ProxyPassword', 'Password')) {
                        $rv = Read-RegistryValue -Key $sessionKey -Name $valueName
                        if ((Test-RegistryReadSuccess -Record $rv -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath + '|' + $valueName)) -and
                            $rv.Found) {
                            $notes = ('PuTTY session "{0}"; Host={1}; User={2} (non-secret context)' -f $sessionName, $hostName, $userName)
                            foreach ($passwordText in @(Get-RegistryStringElements -Data $rv.Data)) {
                                if ([string]::IsNullOrEmpty($passwordText)) { continue }
                                Add-RegistryFinding -HiveLabel $HiveLabel -ViewLabel $View `
                                    -SubKeyPath $sessionPath -ValueName $valueName -RawText $passwordText `
                                    -Category 'StoredSessionCredential' -Severity 'High' -Confidence 'High' `
                                    -Notes $notes -DedupeSubKeyPath ($DedupePrefix + 'Software\SimonTatham\PuTTY\Sessions\' + $sessionName + '\' + $valueName) `
                                    -App 'PuTTY' -Account $userName -Endpoint $hostName -FindingKind 'RecoveredSecret'
                            }
                        }
                    }
                } finally {
                    Complete-RegistryKey -Key $sessionKey -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath)
                }
            }
        }
    } finally {
        Complete-RegistryKey -Key $sessionsKey -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionsPath)
    }
}

# ---- WinSCP sessions ---------------------------------------------------------
function Test-RegistryWinScp {
    param(
        [Parameter(Mandatory=$true)]$HiveRootKey,
        [Parameter(Mandatory=$true)][string]$HiveLabel,
        [Parameter(Mandatory=$true)][string]$View,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$SidPrefix,
        [Parameter(Mandatory=$true)][string]$DedupePrefix
    )
    $sessionsPath = $SidPrefix + 'Software\Martin Prikryl\WinSCP 2\Sessions'
    $sessionsKeyRec = Open-RegistrySubKey -BaseKey $HiveRootKey -SubKeyPath $sessionsPath
    if (-not (Test-RegOpenSuccess -Record $sessionsKeyRec -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionsPath))) { return }
    $sessionsKey = $sessionsKeyRec.Key
    try {
        $subRec = Get-RegistrySubKeyNames -Key $sessionsKey
        if (Test-RegistryEnumerationSuccess -Record $subRec -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionsPath) -Operation 'EnumerateSubKeys') {
            foreach ($sessionName in $subRec.Names) {
                $sessionPath = $sessionsPath + '\' + $sessionName
                $sessionKeyRec = Open-RegistrySubKey -BaseKey $sessionsKey -SubKeyPath $sessionName
                if (-not (Test-RegOpenSuccess -Record $sessionKeyRec -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath))) { continue }
                $sessionKey = $sessionKeyRec.Key
                try {
                    $hostName = ''; $userName = ''; $protocol = ''
                    $rh = Read-RegistryValue -Key $sessionKey -Name 'HostName'
                    if ((Test-RegistryReadSuccess -Record $rh -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath + '|HostName')) -and
                        $rh.Found -and $rh.Data -is [string]) { $hostName = $rh.Data }
                    $ru = Read-RegistryValue -Key $sessionKey -Name 'UserName'
                    if ((Test-RegistryReadSuccess -Record $ru -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath + '|UserName')) -and
                        $ru.Found -and $ru.Data -is [string]) { $userName = $ru.Data }
                    $rp = Read-RegistryValue -Key $sessionKey -Name 'FSProtocol'
                    if ((Test-RegistryReadSuccess -Record $rp -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath + '|FSProtocol')) -and
                        $rp.Found -and $null -ne $rp.Data) { $protocol = [string]$rp.Data }
                    foreach ($valueName in @('Password', 'TunnelPassword')) {
                        $rv = Read-RegistryValue -Key $sessionKey -Name $valueName
                        if ((Test-RegistryReadSuccess -Record $rv -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath + '|' + $valueName)) -and
                            $rv.Found) {
                            $notes = ('WinSCP session "{0}"; Host={1}; User={2}; stored value is obfuscated/encrypted, not decoded' -f $sessionName, $hostName, $userName)
                            if ($protocol.Length -gt 0) { $notes += '; FSProtocol=' + $protocol }
                            foreach ($passwordText in @(Get-RegistryStringElements -Data $rv.Data)) {
                                if ([string]::IsNullOrEmpty($passwordText)) { continue }
                                Add-RegistryFinding -HiveLabel $HiveLabel -ViewLabel $View `
                                    -SubKeyPath $sessionPath -ValueName $valueName -RawText $passwordText `
                                    -Category 'StoredSessionCredential' -Severity 'High' -Confidence 'Medium' `
                                    -Notes $notes -DedupeSubKeyPath ($DedupePrefix + 'Software\Martin Prikryl\WinSCP 2\Sessions\' + $sessionName + '\' + $valueName) `
                                    -App 'WinSCP' -Account $userName -Endpoint $hostName -FindingKind 'ProtectedCredentialArtifact'
                            }
                        }
                    }
                } finally {
                    Complete-RegistryKey -Key $sessionKey -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionPath)
                }
            }
        }
    } finally {
        Complete-RegistryKey -Key $sessionsKey -ErrKey ($HiveLabel + '|' + $View + '|' + $sessionsPath)
    }
}

# ---- VNC variants -------------------------------------------------------------
function Test-RegistryVnc {
    param(
        [Parameter(Mandatory=$true)]$HiveRootKey,
        [Parameter(Mandatory=$true)][string]$HiveLabel,
        [Parameter(Mandatory=$true)][string]$View,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$SidPrefix,
        [Parameter(Mandatory=$true)][string]$DedupePrefix
    )
    $vncKeys = @(
        'SOFTWARE\ORL\WinVNC3',
        'SOFTWARE\RealVNC\WinVNC4',
        'SOFTWARE\TightVNC\Server',
        'SOFTWARE\TigerVNC\WinVNC4'
    )
    foreach ($relative in $vncKeys) {
        $subPath = $SidPrefix + $relative
        $keyRec = Open-RegistrySubKey -BaseKey $HiveRootKey -SubKeyPath $subPath
        if (-not (Test-RegOpenSuccess -Record $keyRec -ErrKey ($HiveLabel + '|' + $View + '|' + $subPath))) { continue }
        $key = $keyRec.Key
        try {
            foreach ($valueName in @('Password', 'PasswordViewOnly', 'PasswordFile', 'passwd')) {
                $rv = Read-RegistryValue -Key $key -Name $valueName
                if (-not (Test-RegistryReadSuccess -Record $rv -ErrKey ($HiveLabel + '|' + $View + '|' + $subPath + '|' + $valueName))) { continue }
                if (-not $rv.Found -or $null -eq $rv.Data) { continue }
                if ($rv.Data -is [byte[]] -and $rv.Data.Length -gt 0) {
                    Add-RegistryBinaryArtifact -HiveLabel $HiveLabel -ViewLabel $View `
                        -SubKeyPath $subPath -ValueName $valueName -Data $rv.Data `
                        -Category 'VncPassword' -Severity 'High' `
                        -Notes 'VNC obfuscated password blob (DES-obfuscated); not decoded' `
                        -DedupeSubKeyPath ($DedupePrefix + $relative)
                } elseif ($rv.Data -is [string] -or $rv.Data -is [string[]]) {
                    foreach ($valueText in @(Get-RegistryStringElements -Data $rv.Data)) {
                        if ([string]::IsNullOrEmpty($valueText)) { continue }
                        if ($valueName -eq 'PasswordFile') {
                            $record = New-FindingRecord
                            $record.Type = 'Registry'
                            $record.Category = 'VncPassword'
                            $record.Severity = 'Low'
                            $record.Confidence = 'Medium'
                            $record.Source = 'REG:' + $DedupePrefix + $relative + '\' + $valueName
                            $record.DisplaySource = $record.Source
                            $record.RegistryPath = '{0}[{1}]\{2}' -f $HiveLabel, $View, $subPath
                            $record.ValueName = $valueName
                            $record.RawValue = ''
                            $record.DisplayValueOverride = ConvertTo-SafeText -Text $valueText
                            $record.Notes = 'VNC password file path reference (path, not a stored secret)'
                            $record.PatternId = 'REGISTRY_VNCPASSWORDFILE'
                            $record.FindingKind = 'SensitiveNamedArtifact'
                            $record.App = 'VNC'
                            $record.SourceKind = 'Registry'
                            $record.KeyPath = $record.RegistryPath + '\' + $valueName
                            $record.ConfidenceEvidence = 'RegistryConfigurationReference'
                            [void](Add-Finding -Finding $record)
                        } else {
                            Add-RegistryFinding -HiveLabel $HiveLabel -ViewLabel $View `
                                -SubKeyPath $subPath -ValueName $valueName -RawText $valueText `
                                -Category 'VncPassword' -Severity 'High' -Confidence 'Medium' `
                                -Notes 'VNC password material (possibly obfuscated); not decoded' `
                                -DedupeSubKeyPath ($DedupePrefix + $relative + '\' + $valueName) `
                                -App 'VNC' -FindingKind 'ProtectedCredentialArtifact'
                        }
                    }
                }
            }
        } finally {
            Complete-RegistryKey -Key $key -ErrKey ($HiveLabel + '|' + $View + '|' + $subPath)
        }
    }
}

# ---- Deep-mode bounded heuristic ----------------------------------------------
function Search-RegistryDeep {
    param(
        [Parameter(Mandatory=$true)]$Key,
        [Parameter(Mandatory=$true)][string]$DisplayPath,
        [Parameter(Mandatory=$true)][string]$HiveLabel,
        [Parameter(Mandatory=$true)][string]$View,
        [Parameter(Mandatory=$true)][string]$DedupePath,
        [Parameter(Mandatory=$true)][int]$Depth
    )
    if ($script:MaxRunDeadlineTicks -gt 0) { Assert-CooperativeRunLimit }
    if ($Depth -gt 5) { return }
    $secretNameRx = '(?i)(password|passwd|pwd|passphrase|secret|client_?secret|api_?key|apikey|token|community|credential)'
    # Broad system exclusions stay at the intended hierarchy; a vendor
    # 'CurrentVersion' subkey is NOT globally skipped (Vendor\Product\
    # CurrentVersion credentials remain reachable).
    $skipNameRx = '(?i)^(Microsoft|Classes|Installer|Servicing|Windows|WOW6432Node|Policies)$'

    $vnRec = Get-RegistryValueNames -Key $Key
    if (Test-RegistryEnumerationSuccess -Record $vnRec -ErrKey ($HiveLabel + '|' + $View + '|' + $DisplayPath) -Operation 'EnumerateValues') {
        foreach ($valueName in $vnRec.Names) {
            if ([string]::IsNullOrWhiteSpace($valueName)) { continue }
            if ($valueName -notmatch $secretNameRx) { continue }
            $rv = Read-RegistryValue -Key $Key -Name $valueName
            if (-not (Test-RegistryReadSuccess -Record $rv -ErrKey ($HiveLabel + '|' + $View + '|' + $DisplayPath + '|' + $valueName))) { continue }
            if (-not $rv.Found -or $null -eq $rv.Data) { continue }
            try {
                $stringValues = New-Object System.Collections.Generic.List[string]
                if ($rv.Data -is [string]) { $stringValues.Add($rv.Data) }
                elseif ($rv.Data -is [string[]]) {
                    foreach ($multiElement in $rv.Data) {
                        if ($null -ne $multiElement) { $stringValues.Add([string]$multiElement) }
                    }
                }
                foreach ($stringValue in $stringValues) {
                    if ([string]::IsNullOrEmpty($stringValue)) { continue }
                    $confidence = 'Medium'
                    $notes = 'Deep registry heuristic: secret-like value name'
                    if (Test-IsPlaceholder -Value $stringValue) {
                        $confidence = 'Low'
                        $notes = 'Deep registry heuristic: secret-like value name; PlaceholderOrReference'
                    }
                    Add-RegistryFinding -HiveLabel $HiveLabel -ViewLabel $View `
                        -SubKeyPath $DisplayPath -ValueName $valueName -RawText $stringValue `
                        -Category 'RegistryHeuristic' -Severity 'Medium' -Confidence $confidence `
                        -Notes $notes -DedupeSubKeyPath ($DedupePath + '\' + $valueName)
                }
                if ($rv.Data -is [byte[]] -and $rv.Data.Length -gt 0) {
                    Add-RegistryBinaryArtifact -HiveLabel $HiveLabel -ViewLabel $View `
                        -SubKeyPath $DisplayPath -ValueName $valueName -Data $rv.Data `
                        -Category 'RegistryHeuristic' -Severity 'Low' `
                        -Notes 'Deep registry heuristic: binary data beneath secret-like value name' `
                        -DedupeSubKeyPath ($DedupePath + '\' + $valueName)
                }
            } catch {
                if (Test-StopError -Err $_) { throw }
                $deepValueCategory = Get-ItemErrorCategory -ErrorInfo $_
                Register-ItemError -Key ('REG:' + $HiveLabel + '|' + $View + '|' + $DisplayPath + '|' + (ConvertTo-SafeText -Text $valueName)) -Category $deepValueCategory -CountNow $true
                if ($deepValueCategory -ne 'AccessDenied') { $script:CoverageIncomplete = $true }
            }
        }
    }

    $snRec = Get-RegistrySubKeyNames -Key $Key
    if (-not (Test-RegistryEnumerationSuccess -Record $snRec -ErrKey ($HiveLabel + '|' + $View + '|' + $DisplayPath) -Operation 'EnumerateSubKeys')) { return }
    foreach ($subName in $snRec.Names) {
        if ($subName -match $skipNameRx) { continue }
        if ($subName -match '(?i)servicing') { continue }
        $childRec = Open-RegistrySubKey -BaseKey $Key -SubKeyPath $subName
        if (-not (Test-RegOpenSuccess -Record $childRec -ErrKey ($HiveLabel + '|' + $View + '|' + $DisplayPath + '\' + $subName))) { continue }
        $child = $childRec.Key
        try {
            Search-RegistryDeep -Key $child -DisplayPath ($DisplayPath + '\' + $subName) `
                -HiveLabel $HiveLabel -View $View -DedupePath ($DedupePath + '\' + $subName) -Depth ($Depth + 1)
        } finally {
            Complete-RegistryKey -Key $child -ErrKey ($HiveLabel + '|' + $View + '|' + $DisplayPath + '\' + $subName)
        }
    }
}

# ---- Registry phase driver ----------------------------------------------------
# One registry target family under its own boundary: a denied key or an
# enumeration failure skips only that family; later families, SIDs and views
# still run. Every opened RegistryKey is disposed in finally on both paths.
function Invoke-RegistryFamily {
    param(
        [Parameter(Mandatory=$true)][string]$FamilyId,
        [Parameter(Mandatory=$true)][scriptblock]$Body
    )
    try {
        & $Body
    } catch {
        if (Test-StopError -Err $_) { throw }
        $familyCategory = Get-ItemErrorCategory -ErrorInfo $_.Exception
        Register-ItemError -Key ('REG:' + $FamilyId) -Category $familyCategory -CountNow $true
        if ($familyCategory -ne 'AccessDenied') { $script:CoverageIncomplete = $true }
    }
}

# ---------------------------------------------------------------------------
# Bounded read-only inspection of registry string content through the same
# safe matcher/redaction pipeline. REG_SZ and unexpanded REG_EXPAND_SZ are
# inspected; REG_MULTI_SZ is handled element-by-element. Nothing is executed,
# expanded or validated.
# ---------------------------------------------------------------------------
function Add-RegistryValueContent {
    param(
        [Parameter(Mandatory=$true)][string]$HiveLabel,
        [Parameter(Mandatory=$true)][string]$View,
        [Parameter(Mandatory=$true)][string]$SubKeyPath,
        [Parameter(Mandatory=$true)][string]$ValueName,
        [AllowNull()]$Data,
        [Parameter(Mandatory=$true)][string]$DedupePath
    )
    $texts = New-Object System.Collections.Generic.List[string]
    if ($null -ne $Data -and $Data -is [string]) { $texts.Add($Data) }
    elseif ($null -ne $Data -and $Data -is [string[]]) { foreach ($el in $Data) { if ($null -ne $el) { $texts.Add([string]$el) } } }
    foreach ($regText in $texts) {
        if ([string]::IsNullOrEmpty($regText)) { continue }
        # Registry APIs already materialize the value, but matching remains
        # bounded: scan the COMPLETE string in overlapping units instead of
        # silently truncating at 8 KiB. Match indices stay unit-local and the
        # normal finding dedupe suppresses overlap duplicates.
        Reset-RegexFileBudgetState
        $regOffset = 0
        while ($regOffset -lt $regText.Length) {
            if ($script:MaxRunDeadlineTicks -gt 0) { Assert-CooperativeRunLimit }
            $remaining = $regText.Length - $regOffset
            $take = [Math]::Min($script:MaxUnitChars, $remaining)
            $unit = $regText.Substring($regOffset, $take)
            $isPartial = (($regOffset + $take) -lt $regText.Length)
            Reset-RegexUnitBudgetState
            $regContract = Find-SecretMatches -Text $unit -FilePath '' -PartialLine $isPartial
            foreach ($rm in $regContract.Matches) {
                Add-RegistryFinding -HiveLabel $HiveLabel -ViewLabel $View `
                    -SubKeyPath $SubKeyPath -ValueName $ValueName -RawText ([string]$rm.Value) `
                    -Category $rm.Category -Severity $rm.Severity -Confidence $rm.Confidence `
                    -Notes ('Registry command/content match ' + $rm.PatternId) `
                    -DedupeSubKeyPath ($DedupePath + '\' + $ValueName)
            }
            if (-not $regContract.SpanSetComplete) {
                $script:ContentCoverageIncomplete = $true
                if ($script:RxFileBudgetExhausted -or
                    $script:RxUnitTimeoutEvents -ge $script:MaxRegexTimeoutEventsPerUnit -or
                    $script:RxUnitElapsedTicks -ge $script:MaxRegexElapsedTicksPerUnit) {
                    Register-RegexBudgetGap
                }
            }
            if ($script:RxFileBudgetExhausted) { break }
            if (-not $isPartial) { break }
            $nextOffset = $regOffset + $take - $script:UnitOverlapChars
            if ($nextOffset -le $regOffset) {
                $script:Stats.GapUnexpectedAssessment++
                $script:ContentCoverageIncomplete = $true
                break
            }
            $regOffset = $nextOffset
        }
    }
}

# ---- HKLM Services: ImagePath and Parameters string content ------------------
function Test-RegistryServices {
    param(
        [Parameter(Mandatory=$true)]$Hklm,
        [Parameter(Mandatory=$true)][string]$View
    )
    $svcRoot = 'SYSTEM\CurrentControlSet\Services'
    $rootRec = Open-RegistrySubKey -BaseKey $Hklm -SubKeyPath $svcRoot
    if (-not (Test-RegOpenSuccess -Record $rootRec -ErrKey ('HKLM|' + $View + '|' + $svcRoot))) { return }
    $rootKey = $rootRec.Key
    try {
        $snRec = Get-RegistrySubKeyNames -Key $rootKey
        if (Test-RegistryEnumerationSuccess -Record $snRec -ErrKey ('HKLM|' + $View + '|' + $svcRoot) -Operation 'EnumerateSubKeys') {
            foreach ($svcName in $snRec.Names) {
                $svcPath = $svcRoot + '\' + $svcName
                $svcRec = Open-RegistrySubKey -BaseKey $rootKey -SubKeyPath $svcName
                if (-not (Test-RegOpenSuccess -Record $svcRec -ErrKey ('HKLM|' + $View + '|' + $svcPath))) { continue }
                $svcKey = $svcRec.Key
                try {
                    $rvImg = Read-RegistryValue -Key $svcKey -Name 'ImagePath'
                    if ((Test-RegistryReadSuccess -Record $rvImg -ErrKey ('HKLM|' + $View + '|' + $svcPath + '|ImagePath')) -and $rvImg.Found) {
                        Add-RegistryValueContent -HiveLabel 'HKLM' -View $View -SubKeyPath $svcPath `
                            -ValueName 'ImagePath' -Data $rvImg.Data -DedupePath ('HKLM\' + $svcPath)
                    }
                    $parametersPath = $svcPath + '\Parameters'
                    $parRec = Open-RegistrySubKey -BaseKey $svcKey -SubKeyPath 'Parameters'
                    if (Test-RegOpenSuccess -Record $parRec -ErrKey ('HKLM|' + $View + '|' + $parametersPath)) {
                        $parKey = $parRec.Key
                        try {
                            $pvn = Get-RegistryValueNames -Key $parKey
                            if (Test-RegistryEnumerationSuccess -Record $pvn -ErrKey ('HKLM|' + $View + '|' + $parametersPath) -Operation 'EnumerateValues') {
                                foreach ($pvnName in $pvn.Names) {
                                    if ([string]::IsNullOrWhiteSpace($pvnName)) { continue }
                                    $rpv = Read-RegistryValue -Key $parKey -Name $pvnName
                                    if ((Test-RegistryReadSuccess -Record $rpv -ErrKey ('HKLM|' + $View + '|' + $parametersPath + '|' + $pvnName)) -and $rpv.Found) {
                                        # REG_SZ and unexpanded REG_EXPAND_SZ are
                                        # strings; REG_MULTI_SZ is a string[] and
                                        # Add-RegistryValueContent processes each
                                        # element independently.
                                        Add-RegistryValueContent -HiveLabel 'HKLM' -View $View -SubKeyPath $parametersPath `
                                            -ValueName $pvnName -Data $rpv.Data -DedupePath ('HKLM\' + $parametersPath)
                                    }
                                }
                            }
                        } finally {
                            Complete-RegistryKey -Key $parKey -ErrKey ('HKLM|' + $View + '|' + $parametersPath)
                        }
                    }
                } finally {
                    Complete-RegistryKey -Key $svcKey -ErrKey ('HKLM|' + $View + '|' + $svcPath)
                }
            }
        }
    } finally {
        Complete-RegistryKey -Key $rootKey -ErrKey ('HKLM|' + $View + '|' + $svcRoot)
    }
}

# ---- Run / RunOnce locations (HKLM and HKCU) ---------------------------------
function Test-RegistryRunKeys {
    param(
        [Parameter(Mandatory=$true)]$HiveRootKey,
        [Parameter(Mandatory=$true)][string]$HiveLabel,
        [Parameter(Mandatory=$true)][string]$View,
        [Parameter(Mandatory=$true)][string]$DedupePrefix
    )
    foreach ($runLeaf in @('Run', 'RunOnce')) {
        $runPath = 'Software\Microsoft\Windows\CurrentVersion\' + $runLeaf
        $runRec = Open-RegistrySubKey -BaseKey $HiveRootKey -SubKeyPath $runPath
        if (-not (Test-RegOpenSuccess -Record $runRec -ErrKey ($HiveLabel + '|' + $View + '|' + $runPath))) { continue }
        $runKey = $runRec.Key
        try {
            $rvn = Get-RegistryValueNames -Key $runKey
            if (Test-RegistryEnumerationSuccess -Record $rvn -ErrKey ($HiveLabel + '|' + $View + '|' + $runPath) -Operation 'EnumerateValues') {
                foreach ($runValue in $rvn.Names) {
                    if ([string]::IsNullOrWhiteSpace($runValue)) { continue }
                    $rrv = Read-RegistryValue -Key $runKey -Name $runValue
                    if ((Test-RegistryReadSuccess -Record $rrv -ErrKey ($HiveLabel + '|' + $View + '|' + $runPath + '|' + $runValue)) -and $rrv.Found) {
                        Add-RegistryValueContent -HiveLabel $HiveLabel -View $View -SubKeyPath $runPath `
                            -ValueName $runValue -Data $rrv.Data -DedupePath ($DedupePrefix + $runPath)
                    }
                }
            }
        } finally {
            Complete-RegistryKey -Key $runKey -ErrKey ($HiveLabel + '|' + $View + '|' + $runPath)
        }
    }
}

# ---- Registry phase driver ----------------------------------------------------
# One registry target family under its own boundary: a denied key or an
# enumeration failure skips only that family; later families, SIDs and views
# still run. Every opened RegistryKey is disposed via Close-RegistryKey.
function Invoke-RegistryChecks {
    Write-ColorLine -Text '[*] Phase: Targeted registry checks' -Color Cyan
    Test-FaultOperation -OperationId 'Phase.Registry'
    $views = Get-RegistryViews
    foreach ($view in $views) {
        # ---- HKLM checks (one boundary per target family) --------------------
        $hklmRec = Open-RegistryBase -Hive ([Microsoft.Win32.RegistryHive]::LocalMachine) -View $view
        if (Test-RegOpenSuccess -Record $hklmRec -ErrKey ('HKLM|' + $view)) {
            $hklm = $hklmRec.Key
            try {
                Invoke-RegistryFamily -FamilyId ('HKLM|' + $view + '|Winlogon') -Body { Test-RegistryWinlogon -Hklm $hklm -View $view }
                Invoke-RegistryFamily -FamilyId ('HKLM|' + $view + '|Snmp') -Body { Test-RegistrySnmp -Hklm $hklm -View $view }
                Invoke-RegistryFamily -FamilyId ('HKLM|' + $view + '|Vnc') -Body { Test-RegistryVnc -HiveRootKey $hklm -HiveLabel 'HKLM' -View $view -SidPrefix '' -DedupePrefix 'HKLM\' }
                Invoke-RegistryFamily -FamilyId ('HKLM|' + $view + '|Services') -Body { Test-RegistryServices -Hklm $hklm -View $view }
                Invoke-RegistryFamily -FamilyId ('HKLM|' + $view + '|RunKeys') -Body { Test-RegistryRunKeys -HiveRootKey $hklm -HiveLabel 'HKLM' -View $view -DedupePrefix 'HKLM\' }
                if ($script:IsDeepMode) {
                    Invoke-RegistryFamily -FamilyId ('HKLM|' + $view + '|DeepHeuristic') -Body {
                        $softwareRec = Open-RegistrySubKey -BaseKey $hklm -SubKeyPath 'SOFTWARE'
                        if (Test-RegOpenSuccess -Record $softwareRec -ErrKey ('HKLM|' + $view + '|SOFTWARE')) {
                            $softwareKey = $softwareRec.Key
                            try {
                                $hklmAppRec = Get-RegistrySubKeyNames -Key $softwareKey
                                if (Test-RegistryEnumerationSuccess -Record $hklmAppRec -ErrKey ('HKLM|' + $view + '|SOFTWARE') -Operation 'EnumerateSubKeys') {
                                    foreach ($appName in $hklmAppRec.Names) {
                                        if ($appName -match '(?i)^(Microsoft|Classes|Installer|Servicing|Windows|WOW6432Node|Policies)$') { continue }
                                        $appPath = 'SOFTWARE\' + $appName
                                        $appKeyRec = Open-RegistrySubKey -BaseKey $softwareKey -SubKeyPath $appName
                                        if (-not (Test-RegOpenSuccess -Record $appKeyRec -ErrKey ('HKLM|' + $view + '|' + $appPath))) { continue }
                                        $appKey = $appKeyRec.Key
                                        try {
                                            Search-RegistryDeep -Key $appKey -DisplayPath $appPath `
                                                -HiveLabel 'HKLM' -View $view -DedupePath ('HKLM\' + $appPath) -Depth 1
                                        } finally {
                                            Complete-RegistryKey -Key $appKey -ErrKey ('HKLM|' + $view + '|' + $appPath)
                                        }
                                    }
                                }
                            } finally {
                                Complete-RegistryKey -Key $softwareKey -ErrKey ('HKLM|' + $view + '|SOFTWARE')
                            }
                        }
                    }
                }
            } finally {
                Complete-RegistryKey -Key $hklm -ErrKey ('HKLM|' + $view)
            }
        }

        # ---- HKCU checks -------------------------------------------------------
        $hkcuRec = Open-RegistryBase -Hive ([Microsoft.Win32.RegistryHive]::CurrentUser) -View $view
        if (Test-RegOpenSuccess -Record $hkcuRec -ErrKey ('HKCU|' + $view)) {
            $hkcu = $hkcuRec.Key
            try {
                $cuPrefix = ''
                $cuDedupe = ''
                if ($script:CurrentUserSid.Length -gt 0) {
                    $cuDedupe = $script:CurrentUserSid + '\'
                }
                Invoke-RegistryFamily -FamilyId ('HKCU|' + $view + '|Putty') -Body { Test-RegistryPutty -HiveRootKey $hkcu -HiveLabel 'HKCU' -View $view -SidPrefix $cuPrefix -DedupePrefix ('HKU\' + $cuDedupe) }
                Invoke-RegistryFamily -FamilyId ('HKCU|' + $view + '|WinScp') -Body { Test-RegistryWinScp -HiveRootKey $hkcu -HiveLabel 'HKCU' -View $view -SidPrefix $cuPrefix -DedupePrefix ('HKU\' + $cuDedupe) }
                Invoke-RegistryFamily -FamilyId ('HKCU|' + $view + '|Vnc') -Body { Test-RegistryVnc -HiveRootKey $hkcu -HiveLabel 'HKCU' -View $view -SidPrefix $cuPrefix -DedupePrefix ('HKU\' + $cuDedupe) }
                Invoke-RegistryFamily -FamilyId ('HKCU|' + $view + '|RunKeys') -Body { Test-RegistryRunKeys -HiveRootKey $hkcu -HiveLabel 'HKCU' -View $view -DedupePrefix ('HKU\' + $cuDedupe) }
                if ($script:IsDeepMode) {
                    Invoke-RegistryFamily -FamilyId ('HKCU|' + $view + '|DeepHeuristic') -Body {
                        $userSoftRec = Open-RegistrySubKey -BaseKey $hkcu -SubKeyPath 'Software'
                        if (Test-RegOpenSuccess -Record $userSoftRec -ErrKey ('HKCU|' + $view + '|Software')) {
                            $userSoftware = $userSoftRec.Key
                            try {
                                $hkcuAppRec = Get-RegistrySubKeyNames -Key $userSoftware
                                if (Test-RegistryEnumerationSuccess -Record $hkcuAppRec -ErrKey ('HKCU|' + $view + '|Software') -Operation 'EnumerateSubKeys') {
                                    foreach ($appName in $hkcuAppRec.Names) {
                                        if ($appName -match '(?i)^(Microsoft|Classes|Installer|Servicing|Windows|WOW6432Node|Policies)$') { continue }
                                        $appPath = 'Software\' + $appName
                                        $appKeyRec = Open-RegistrySubKey -BaseKey $userSoftware -SubKeyPath $appName
                                        if (-not (Test-RegOpenSuccess -Record $appKeyRec -ErrKey ('HKCU|' + $view + '|' + $appPath))) { continue }
                                        $appKey = $appKeyRec.Key
                                        try {
                                            Search-RegistryDeep -Key $appKey -DisplayPath $appPath `
                                                -HiveLabel 'HKCU' -View $view -DedupePath ('HKU\' + $cuDedupe + $appPath) -Depth 1
                                        } finally {
                                            Complete-RegistryKey -Key $appKey -ErrKey ('HKCU|' + $view + '|' + $appPath)
                                        }
                                    }
                                }
                            } finally {
                                Complete-RegistryKey -Key $userSoftware -ErrKey ('HKCU|' + $view + '|Software')
                            }
                        }
                    }
                }
            } finally {
                Complete-RegistryKey -Key $hkcu -ErrKey ('HKCU|' + $view)
            }
        }

        # ---- Loaded HKEY_USERS SID hives (skip *_Classes) -----------------------
        $hkuRec = Open-RegistryBase -Hive ([Microsoft.Win32.RegistryHive]::Users) -View $view
        if (Test-RegOpenSuccess -Record $hkuRec -ErrKey ('HKU|' + $view)) {
            $hku = $hkuRec.Key
            try {
                $sidRec = Get-RegistrySubKeyNames -Key $hku
                if (Test-RegistryEnumerationSuccess -Record $sidRec -ErrKey ('HKU|' + $view) -Operation 'EnumerateSubKeys') {
                    foreach ($sid in $sidRec.Names) {
                        if ($sid -notmatch '^S-1-') { continue }
                        if ($sid -match '_Classes$') { continue }
                        $sidKeyRec = Open-RegistrySubKey -BaseKey $hku -SubKeyPath $sid
                        if (-not (Test-RegOpenSuccess -Record $sidKeyRec -ErrKey ('HKU|' + $view + '|' + $sid))) { continue }
                        $sidKey = $sidKeyRec.Key
                        try {
                            $hiveLabel = 'HKU\' + $sid
                            Invoke-RegistryFamily -FamilyId ('HKU|' + $view + '|' + $sid + '|Putty') -Body { Test-RegistryPutty -HiveRootKey $sidKey -HiveLabel $hiveLabel -View $view -SidPrefix '' -DedupePrefix ('HKU\' + $sid + '\') }
                            Invoke-RegistryFamily -FamilyId ('HKU|' + $view + '|' + $sid + '|WinScp') -Body { Test-RegistryWinScp -HiveRootKey $sidKey -HiveLabel $hiveLabel -View $view -SidPrefix '' -DedupePrefix ('HKU\' + $sid + '\') }
                            Invoke-RegistryFamily -FamilyId ('HKU|' + $view + '|' + $sid + '|Vnc') -Body { Test-RegistryVnc -HiveRootKey $sidKey -HiveLabel $hiveLabel -View $view -SidPrefix '' -DedupePrefix ('HKU\' + $sid + '\') }
                            if ($script:IsDeepMode) {
                                Invoke-RegistryFamily -FamilyId ('HKU|' + $view + '|' + $sid + '|DeepHeuristic') -Body {
                                    $sidSoftRec = Open-RegistrySubKey -BaseKey $sidKey -SubKeyPath 'Software'
                                    if (Test-RegOpenSuccess -Record $sidSoftRec -ErrKey ('HKU|' + $view + '|' + $sid + '|Software')) {
                                        $sidSoftware = $sidSoftRec.Key
                                        try {
                                            $sidAppRec = Get-RegistrySubKeyNames -Key $sidSoftware
                                            if (Test-RegistryEnumerationSuccess -Record $sidAppRec -ErrKey ('HKU|' + $view + '|' + $sid + '|Software') -Operation 'EnumerateSubKeys') {
                                                foreach ($appName in $sidAppRec.Names) {
                                                    if ($appName -match '(?i)^(Microsoft|Classes|Installer|Servicing|Windows|WOW6432Node|Policies)$') { continue }
                                                    $appPath = 'Software\' + $appName
                                                    $appKeyRec = Open-RegistrySubKey -BaseKey $sidSoftware -SubKeyPath $appName
                                                    if (-not (Test-RegOpenSuccess -Record $appKeyRec -ErrKey ('HKU|' + $view + '|' + $sid + '|' + $appPath))) { continue }
                                                    $appKey = $appKeyRec.Key
                                                    try {
                                                        Search-RegistryDeep -Key $appKey -DisplayPath $appPath `
                                                            -HiveLabel $hiveLabel -View $view -DedupePath ('HKU\' + $sid + '\' + $appPath) -Depth 1
                                                    } finally {
                                                        Complete-RegistryKey -Key $appKey -ErrKey ('HKU|' + $view + '|' + $sid + '|' + $appPath)
                                                    }
                                                }
                                            }
                                        } finally {
                                            Complete-RegistryKey -Key $sidSoftware -ErrKey ('HKU|' + $view + '|' + $sid + '|Software')
                                        }
                                    }
                                }
                            }
                        } finally {
                            Complete-RegistryKey -Key $sidKey -ErrKey ('HKU|' + $view + '|' + $sid)
                        }
                    }
                }
            } finally {
                Complete-RegistryKey -Key $hku -ErrKey ('HKU|' + $view)
            }
        }
    }
}

# ---------------------------------------------------------------------------
# Scan-root resolution for the full-scan phase.
# -Path supplied: only those items are scanned (UNC requires
# -IncludeNetworkDrives; non-filesystem provider paths are rejected).
# Otherwise: ready local fixed/removable drive roots from Get-PSDrive.
# ---------------------------------------------------------------------------
function Resolve-SuppliedPath {
    param([Parameter(Mandatory=$true)][string]$RawPath)
    if ([string]::IsNullOrWhiteSpace($RawPath)) { return $null }
    if ($RawPath -match '^[A-Za-z][A-Za-z0-9+.-]*::') {
        Write-ColorLine -Text ('[!] Rejected non-filesystem provider path: {0}' -f (ConvertTo-SafeText -Text $RawPath)) -Color Yellow
        return $null
    }
    $norm = ConvertTo-CanonicalRoot -PathValue $RawPath -WarnOnReject $true
    if ($null -eq $norm) {
        # Drive-relative and UNC rejections already printed their one warning
        # inside ConvertTo-CanonicalRoot; warn for everything else here.
        if ($RawPath.Trim() -notmatch '^[A-Za-z]:(?![\\/])' -and -not $RawPath.Trim().StartsWith('\\')) {
            Write-ColorLine -Text ('[!] Rejected invalid or non-filesystem path: {0}' -f (ConvertTo-SafeText -Text $RawPath)) -Color Yellow
        }
        return $null
    }
    if (-not (Test-TargetedPathPolicy -PathValue $norm -ErrorKey ('FS:supplied-policy|' + $norm) -CountErrors $true)) {
        Write-ColorLine -Text ('[!] Supplied path violates the local/reparse policy and was skipped: {0}' -f (ConvertTo-SafeText -Text $norm)) -Color Yellow
        return $null
    }
    try {
        Get-Item -LiteralPath $norm -Force -ErrorAction Stop | Out-Null
    } catch {
        $resolveCategory = Get-ItemErrorCategory -ErrorInfo $_
        Register-ItemError -Key ('FS:supplied|' + $norm + '|' + $resolveCategory) -Category $resolveCategory -CountNow $true
        Write-ColorLine -Text ('[!] Supplied path is absent or inaccessible and was skipped: {0}' -f (ConvertTo-SafeText -Text $norm)) -Color Yellow
        return $null
    }
    return $norm
}

# Safe property accessor for WMI/CIM objects and deterministic SelfTest seam
# records. Missing properties return $null under StrictMode.
function Get-OptionalObjectValue {
    param(
        [AllowNull()]$Object,
        [Parameter(Mandatory=$true)][string]$Name
    )
    if ($null -eq $Object) { return $null }
    if ($Object -is [System.Collections.IDictionary]) {
        if ($Object.Contains($Name)) { return $Object[$Name] }
        return $null
    }
    try {
        $prop = $Object.PSObject.Properties[$Name]
        if ($null -ne $prop) { return $prop.Value }
    } catch { }
    return $null
}

function Get-CimReferenceValue {
    param(
        [AllowNull()]$Reference,
        [Parameter(Mandatory=$true)][string]$PropertyName
    )
    if ($null -eq $Reference) { return '' }
    $direct = Get-OptionalObjectValue -Object $Reference -Name $PropertyName
    if ($null -ne $direct -and -not [string]::IsNullOrEmpty([string]$direct)) { return [string]$direct }
    try {
        $cimProp = $Reference.CimInstanceProperties[$PropertyName]
        if ($null -ne $cimProp -and $null -ne $cimProp.Value) { return [string]$cimProp.Value }
    } catch { }
    $text = [string]$Reference
    $match = [regex]::Match($text, ('(?i)(?:^|[.,:\s])' + [regex]::Escape($PropertyName) + '\s*=\s*"(?<v>(?:\\.|[^"])*)"'))
    if ($match.Success) { return $match.Groups['v'].Value.Replace('\\', '\') }
    return ''
}

# Enumerates fixed/removable local volumes and their folder mount points using
# inbox WMI/CIM classes. No elevation or external executable is required.
function Get-LocalVolumeInventory {
    $records = New-Object System.Collections.Generic.List[object]
    $unavailable = New-Object System.Collections.Generic.List[string]
    $volumes = $null
    $mounts = $null
    try {
        if ($script:FaultSeam.Enabled -and $null -ne $script:FaultSeam.VolumeList) {
            $volumes = @($script:FaultSeam.VolumeList)
            if ($null -ne $script:FaultSeam.MountPointList) { $mounts = @($script:FaultSeam.MountPointList) }
            else { $mounts = @() }
        } elseif ($null -ne (Get-Command -Name Get-CimInstance -ErrorAction SilentlyContinue)) {
            $volumes = @(Get-CimInstance -ClassName Win32_Volume -ErrorAction Stop)
            $mounts = @(Get-CimInstance -ClassName Win32_MountPoint -ErrorAction Stop)
        } else {
            $volumes = @(Get-WmiObject -Class Win32_Volume -ErrorAction Stop)
            $mounts = @(Get-WmiObject -Class Win32_MountPoint -ErrorAction Stop)
        }
    } catch {
        $inventoryCategory = Get-ItemErrorCategory -ErrorInfo $_
        Register-ItemError -Key ('FS:volume-inventory|' + $inventoryCategory) -Category $inventoryCategory -CountNow $true
        return @{ Succeeded = $false; Records = $records.ToArray(); Unavailable = $unavailable.ToArray() }
    }
    if ($null -eq $volumes -or $volumes.Count -eq 0) {
        return @{ Succeeded = $false; Records = $records.ToArray(); Unavailable = $unavailable.ToArray() }
    }

    $mountMap = @{}
    foreach ($mount in $mounts) {
        try {
        $volumeId = [string](Get-OptionalObjectValue -Object $mount -Name 'VolumeId')
        if ([string]::IsNullOrEmpty($volumeId)) {
            $volumeRef = Get-OptionalObjectValue -Object $mount -Name 'Volume'
            $volumeId = Get-CimReferenceValue -Reference $volumeRef -PropertyName 'DeviceID'
        }
        $directoryPath = [string](Get-OptionalObjectValue -Object $mount -Name 'DirectoryPath')
        if ([string]::IsNullOrEmpty($directoryPath)) {
            $directoryRef = Get-OptionalObjectValue -Object $mount -Name 'Directory'
            $directoryPath = Get-CimReferenceValue -Reference $directoryRef -PropertyName 'Name'
        }
        if ([string]::IsNullOrEmpty($volumeId) -or [string]::IsNullOrEmpty($directoryPath)) { continue }
        if (-not $mountMap.ContainsKey($volumeId)) {
            $mountMap[$volumeId] = New-Object System.Collections.Generic.List[string]
        }
        if (-not $mountMap[$volumeId].Contains($directoryPath)) { $mountMap[$volumeId].Add($directoryPath) }
        } catch {
            $mountCategory = Get-ItemErrorCategory -ErrorInfo $_
            Register-ItemError -Key ('FS:volume-mount-record|' + $mountCategory) -Category $mountCategory -CountNow $true
            $script:Stats.VolumeDiscoveryFailures++
            $script:CoverageIncomplete = $true
            $script:ContentCoverageIncomplete = $true
        }
    }

    $seenVolumeIds = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($volume in $volumes) {
        try {
        $driveTypeValue = Get-OptionalObjectValue -Object $volume -Name 'DriveType'
        if ($null -eq $driveTypeValue) { continue }
        $driveType = [int]$driveTypeValue
        if ($driveType -ne 2 -and $driveType -ne 3) { continue }
        $volumeId = [string](Get-OptionalObjectValue -Object $volume -Name 'DeviceID')
        if ([string]::IsNullOrEmpty($volumeId)) { $volumeId = [string](Get-OptionalObjectValue -Object $volume -Name 'VolumeId') }
        if ([string]::IsNullOrEmpty($volumeId)) { $volumeId = [string](Get-OptionalObjectValue -Object $volume -Name 'Name') }
        if ([string]::IsNullOrEmpty($volumeId) -or -not $seenVolumeIds.Add($volumeId)) { continue }
        $script:Stats.VolumesDiscovered++

        $accessPaths = New-Object System.Collections.Generic.List[string]
        $driveLetter = [string](Get-OptionalObjectValue -Object $volume -Name 'DriveLetter')
        if ($driveLetter -match '^[A-Za-z]:$') { $accessPaths.Add($driveLetter + '\') }
        if ($mountMap.ContainsKey($volumeId)) {
            foreach ($mountPath in $mountMap[$volumeId]) { if (-not $accessPaths.Contains($mountPath)) { $accessPaths.Add($mountPath) } }
        }

        $chosenRoot = ''
        $chosenIsMount = $false
        $accessibleOverride = Get-OptionalObjectValue -Object $volume -Name 'Accessible'
        foreach ($accessPath in $accessPaths) {
            $canonical = ConvertTo-CanonicalRoot -PathValue $accessPath
            if ($null -eq $canonical) { continue }
            $accessible = $false
            if ($null -ne $accessibleOverride) { $accessible = [bool]$accessibleOverride }
            else {
                $pathErrors = $null
                $accessible = Test-Path -LiteralPath $canonical -PathType Container -ErrorAction SilentlyContinue -ErrorVariable pathErrors
                if ($null -ne $pathErrors) {
                    foreach ($pathError in $pathErrors) {
                        $pathCategory = Get-ItemErrorCategory -ErrorInfo $pathError
                        Register-ItemError -Key ('FS:volume|' + $canonical + '|' + $pathCategory) -Category $pathCategory -CountNow $true
                    }
                }
            }
            if (-not $accessible) { continue }
            $isDriveRoot = ($canonical -match '^[A-Za-z]:\\$')
            if (-not $isDriveRoot) { [void]$script:VolumeMountRoots.Add($canonical) }
            if ([string]::IsNullOrEmpty($chosenRoot) -or $isDriveRoot -or $canonical.Length -lt $chosenRoot.Length) {
                $chosenRoot = $canonical
                $chosenIsMount = (-not $isDriveRoot)
                if ($isDriveRoot) { break }
            }
        }
        if ([string]::IsNullOrEmpty($chosenRoot)) {
            $label = $volumeId
            if ($accessPaths.Count -gt 0) { $label = [string]$accessPaths[0] }
            $unavailable.Add($label)
            $script:UnavailableVolumeLabels.Add($label)
            $script:Stats.VolumesUnavailable++
            $script:CoverageIncomplete = $true
            $script:ContentCoverageIncomplete = $true
            continue
        }
        $records.Add(@{ Root = $chosenRoot; VolumeId = $volumeId; IsMountPoint = $chosenIsMount })
        } catch {
            $volumeCategory = Get-ItemErrorCategory -ErrorInfo $_
            Register-ItemError -Key ('FS:volume-record|' + $volumeCategory) -Category $volumeCategory -CountNow $true
            $script:Stats.VolumeDiscoveryFailures++
            $script:CoverageIncomplete = $true
            $script:ContentCoverageIncomplete = $true
        }
    }
    if ($records.Count -eq 0 -and $unavailable.Count -eq 0) {
        return @{ Succeeded = $false; Records = $records.ToArray(); Unavailable = $unavailable.ToArray() }
    }
    return @{ Succeeded = $true; Records = $records.ToArray(); Unavailable = $unavailable.ToArray() }
}

# Boundary-aware root coverage: $candidate is covered by $other only when it
# starts with the other's trimmed form plus a directory boundary. Pure string
# logic shared by supplied and automatic root planning.
function Test-RootCovered {
    param(
        [Parameter(Mandatory=$true)][string]$Candidate,
        [Parameter(Mandatory=$true)][string]$Other
    )
    if ($Other.Equals($Candidate, [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
    $candidateKnown = $script:VolumeRootIds.ContainsKey($Candidate)
    $otherKnown = $script:VolumeRootIds.ContainsKey($Other)
    if ($candidateKnown -or $otherKnown) {
        if (-not ($candidateKnown -and $otherKnown)) { return $false }
        if (-not ([string]$script:VolumeRootIds[$Candidate]).Equals([string]$script:VolumeRootIds[$Other], [System.StringComparison]::OrdinalIgnoreCase)) { return $false }
    }
    return ($Candidate.Length -gt $Other.Length -and
            $Candidate.StartsWith($Other.TrimEnd('\') + '\', [System.StringComparison]::OrdinalIgnoreCase))
}

function Get-ScanPlan {
    # Returns @{ Roots; Files; Rejected; RejectedRoots }. Rejected is reserved
    # for operator-supplied items; RejectedRoots records ready auto-discovered
    # roots that could not be safely planned so they become explicit Failed
    # root states rather than disappearing behind a warning.
    # Terminal states are derived later from structured outcomes; this function
    # only plans. A not-ready auto-discovered drive is warned once and never
    # planned. A drive-discovery escape makes the full-scan plan unsafe: the
    # Full filesystem phase is marked Failed and no traversal happens.
    $roots = New-Object System.Collections.Generic.List[string]
    $files = New-Object System.Collections.Generic.List[string]
    $rejected = New-Object System.Collections.Generic.List[string]
    $rejectedRoots = New-Object System.Collections.Generic.List[string]
    $rootSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $fileSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $script:VolumeMountRoots.Clear()
    $script:VolumeRootIds.Clear()
    $script:UnavailableVolumeLabels.Clear()

    if ($Path.Count -gt 0) {
        foreach ($raw in $Path) {
            $norm = Resolve-SuppliedPath -RawPath $raw
            if ($null -eq $norm) {
                # A supplied item that cannot be used is a planned, failed item.
                $rejected.Add([string]$raw)
                $script:CoverageIncomplete = $true
                continue
            }
            $plannedItem = $null
            try { $plannedItem = Get-Item -LiteralPath $norm -Force -ErrorAction Stop }
            catch {
                $plannedCategory = Get-ItemErrorCategory -ErrorInfo $_
                Register-ItemError -Key ('FS:supplied-plan|' + $norm + '|' + $plannedCategory) -Category $plannedCategory -CountNow $true
            }
            if ($null -eq $plannedItem) {
                $rejected.Add($norm)
                $script:CoverageIncomplete = $true
                continue
            }
            if (-not $plannedItem.PSIsContainer) {
                $fileIdentity = Get-PathIdentity -PathValue $norm -Item $plannedItem
                if ($null -eq $fileIdentity) {
                    $rejected.Add($norm)
                    $script:CoverageIncomplete = $true
                    continue
                }
                if ($fileSet.Add($fileIdentity)) { $files.Add($fileIdentity) }   # provider aliases de-duplicated
            } else {
                # Do not follow or traverse a supplied root that is itself a
                # reparse point. Fail CLOSED: if the attributes cannot be read,
                # the root is failed rather than traversed on an assumption.
                $rootItem = $plannedItem
                $rootAttrUnknown = $false
                $rootIsReparse = $false
                if (-not $rootAttrUnknown) {
                    try { $rootIsReparse = (($rootItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0) } catch { $rootAttrUnknown = $true }
                }
                if ($rootAttrUnknown) {
                    Write-ColorLine -Text ('[!] Supplied root attributes unreadable (fail-closed), not traversed: {0}' -f (ConvertTo-SafeText -Text $norm)) -Color Yellow
                    $rejected.Add($norm)
                    $script:CoverageIncomplete = $true
                    continue
                }
                if ($rootIsReparse) {
                    Write-ColorLine -Text ('[!] Supplied root is a reparse point and will not be traversed: {0}' -f (ConvertTo-SafeText -Text $norm)) -Color Yellow
                    $rejected.Add($norm)
                    $script:CoverageIncomplete = $true
                    continue
                }
                $rootIdentity = Get-PathIdentity -PathValue $norm -Item $rootItem
                if ($null -eq $rootIdentity) {
                    $rejected.Add($norm)
                    $script:CoverageIncomplete = $true
                    continue
                }
                [void]$rootSet.Add($rootIdentity)
            }
        }
        foreach ($candidate in $rootSet) {
            $covered = $false
            foreach ($other in $rootSet) {
                if (Test-RootCovered -Candidate $candidate -Other $other) {
                    $covered = $true
                    break
                }
            }
            if (-not $covered) { $roots.Add($candidate) }
        }
        return @{ Roots = $roots.ToArray(); Files = $files.ToArray(); Rejected = $rejected.ToArray(); RejectedRoots = $rejectedRoots.ToArray() }
    }

    $drives = @()
    $useLegacyDriveInventory = ($script:FaultSeam.Enabled -and $null -ne $script:FaultSeam.DriveList -and
                                $null -eq $script:FaultSeam.VolumeList)
    if ($useLegacyDriveInventory) {
        $drives = @($script:FaultSeam.DriveList)
    } else {
        $volumeInventory = Get-LocalVolumeInventory
        if ($volumeInventory.Succeeded) {
            foreach ($volumeRecord in $volumeInventory.Records) {
                $volumeRoot = [string](Get-OptionalObjectValue -Object $volumeRecord -Name 'Root')
                if ([string]::IsNullOrEmpty($volumeRoot)) { continue }
                if ($rootSet.Add($volumeRoot)) {
                    $script:VolumeRootIds[$volumeRoot] = [string](Get-OptionalObjectValue -Object $volumeRecord -Name 'VolumeId')
                    if ([bool](Get-OptionalObjectValue -Object $volumeRecord -Name 'IsMountPoint')) {
                        [void]$script:VolumeMountRoots.Add($volumeRoot)
                        $script:Stats.VolumeMountRootsPlanned++
                    }
                }
            }
            # Local volumes without a usable access path (locked, hidden or
            # unmounted) are disclosed as Coverage=Partial, not fabricated as
            # executable roots whose inevitable failure would mislabel the
            # engine itself as failed.
            # WMI volume inventory is local-only. Explicitly enabled network
            # PSDrives are added as a separate, opt-in universe.
            if ($script:NetworkDrivesAllowed) {
                try {
                    $networkDrives = @(Get-PSDrive -PSProvider FileSystem)
                    $networkList = New-Object System.Collections.Generic.List[object]
                    foreach ($networkDrive in $networkDrives) {
                        $networkRoot = [string](Get-OptionalObjectValue -Object $networkDrive -Name 'Root')
                        $networkDisplay = [string](Get-OptionalObjectValue -Object $networkDrive -Name 'DisplayRoot')
                        if ($networkRoot.StartsWith('\\') -or $networkDisplay.StartsWith('\\')) { $networkList.Add($networkDrive) }
                    }
                    $drives = $networkList.ToArray()
                } catch {
                    $script:Stats.VolumeDiscoveryFailures++
                    $script:CoverageIncomplete = $true
                }
            }
        } else {
            # Compatibility fallback: keep scanning discoverable PSDrives, but
            # disclose that folder-mounted volumes could not be inventoried.
            $script:Stats.VolumeDiscoveryFailures++
            $script:CoverageIncomplete = $true
            $script:ContentCoverageIncomplete = $true
            try { $drives = @(Get-PSDrive -PSProvider FileSystem) }
            catch {
                $drives = @()
                $script:FullScanPlanSafe = $false
            }
        }
    }
    foreach ($drive in $drives) {
        try {
            $root = [string](Get-OptionalObjectValue -Object $drive -Name 'Root')
            if ([string]::IsNullOrEmpty($root)) { continue }
            if ($root.StartsWith('\\') -and -not $script:NetworkDrivesAllowed) { continue }
            $displayRoot = [string](Get-OptionalObjectValue -Object $drive -Name 'DisplayRoot')
            if ($displayRoot.StartsWith('\\') -and -not $script:NetworkDrivesAllowed) { continue }

            $driveInfo = $null
            $driveName = [string](Get-OptionalObjectValue -Object $drive -Name 'Name')
            try { $driveInfo = New-Object System.IO.DriveInfo ($driveName) } catch { $driveInfo = $null }
            if ($null -ne $driveInfo) {
                if (-not $driveInfo.IsReady) {
                    Write-ColorLine -Text ('[!] Drive root not ready, skipped: {0}' -f (ConvertTo-SafeText -Text $root)) -Color Yellow
                    continue
                }
                $driveType = $driveInfo.DriveType
                if ($driveType -eq [System.IO.DriveType]::Network -and -not $script:NetworkDrivesAllowed) { continue }
                if ($driveType -ne [System.IO.DriveType]::Fixed -and
                    $driveType -ne [System.IO.DriveType]::Removable -and
                    $driveType -ne [System.IO.DriveType]::Network) { continue }
            }
            # Resolve the root through a terminating provider probe. In the
            # PSDrive compatibility fallback, a custom local root must not be
            # a junction/reparse point; only WMI-inventoried folder mounts are
            # allowed as independent reparse roots.
            $driveRootItem = Get-Item -LiteralPath $root -Force -ErrorAction Stop
            if ($driveRootItem.PSIsContainer -ne $true) { continue }
            $isSimpleDriveRoot = ($root -match '^[A-Za-z]:\\$')
            if ($null -eq $driveInfo -and -not $root.StartsWith('\\') -and -not $isSimpleDriveRoot) {
                $fallbackRootReparse = (($driveRootItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0)
                if ($fallbackRootReparse) {
                    Write-ColorLine -Text ('[!] Custom PSDrive reparse root rejected without authoritative volume inventory: {0}' -f (ConvertTo-SafeText -Text $root)) -Color Yellow
                    $script:CoverageIncomplete = $true
                    $script:ContentCoverageIncomplete = $true
                    if (-not $rejectedRoots.Contains($root)) { $rejectedRoots.Add($root) }
                    continue
                }
            }
            $canonicalRoot = ConvertTo-CanonicalRoot -PathValue $root
            if ($null -eq $canonicalRoot) {
                # A ready drive in the enabled scan universe that fails
                # canonicalization is disclosed as skipped/incomplete — it is
                # never silently dropped and never becomes a fake planned root.
                $script:CoverageIncomplete = $true
                Write-ColorLine -Text ('[!] Drive root failed canonicalization and was skipped: {0}' -f (ConvertTo-SafeText -Text $root)) -Color Yellow
                if (-not [string]::IsNullOrEmpty($root) -and -not $rejectedRoots.Contains($root)) { $rejectedRoots.Add($root) }
                continue
            }
            [void]$rootSet.Add($canonicalRoot)
        } catch {
            $driveCategory = Get-ItemErrorCategory -ErrorInfo $_.Exception
            $failedDriveName = ''
            try { $failedDriveName = [string]$drive.Name } catch { $failedDriveName = 'unknown' }
            Register-ItemError -Key ('FS:drive|' + $failedDriveName) -Category $driveCategory -CountNow $true
            # A discovered drive that throws during readiness/type/root
            # inspection is omitted coverage, not a harmless absent drive.
            $script:CoverageIncomplete = $true
            $failedDriveLabel = ''
            try { $failedDriveLabel = [string]$drive.Root } catch { $failedDriveLabel = '' }
            if ([string]::IsNullOrEmpty($failedDriveLabel)) { $failedDriveLabel = ($failedDriveName + ':\') }
            if (-not $rejectedRoots.Contains($failedDriveLabel)) { $rejectedRoots.Add($failedDriveLabel) }
        }
    }
    # Boundary-aware parent/child overlap elimination for auto-discovered roots
    # as well: if C:\ and a custom PSDrive rooted at C:\Users are both present,
    # only C:\ is planned. Distinct volume roots and distinct UNC shares stay
    # distinct; UNC gating was applied above.
    foreach ($candidate in $rootSet) {
        $covered = $false
        foreach ($other in $rootSet) {
            if (Test-RootCovered -Candidate $candidate -Other $other) {
                $covered = $true
                break
            }
        }
        if (-not $covered) { $roots.Add($candidate) }
    }
    return @{ Roots = $roots.ToArray(); Files = $files.ToArray(); Rejected = $rejected.ToArray(); RejectedRoots = $rejectedRoots.ToArray() }
}

# ---------------------------------------------------------------------------
# Progress helpers: Write-Progress throttled to at most five updates per
# second, plus the every-500-files cyan status line.
# ---------------------------------------------------------------------------
function Update-ScanProgress {
    param(
        [Parameter(Mandatory=$true)][string]$Root,
        [Parameter(Mandatory=$true)][string]$CurrentPath,
        [Parameter(Mandatory=$true)][long]$Scanned,
        [Parameter(Mandatory=$true)][long]$Eligible
    )
    if ($script:NoProgressActive) { return }
    $now = Get-Date
    if (($now - $script:LastProgressTime).TotalMilliseconds -lt 200) { return }
    $script:LastProgressTime = $now

    $status = ConvertTo-SafeText -Text $CurrentPath
    if ($status.Length -gt 60) { $status = $status.Substring($status.Length - 60) }
    $percent = 0
    if ($Eligible -gt 0) {
        $percent = [int](($Scanned * 100) / $Eligible)
        if ($percent -gt 100) { $percent = 100 }
    }
    $elapsed = $script:SwTotal.Elapsed
    $leaf = ''
    try { $leaf = [System.IO.Path]::GetFileName($CurrentPath) } catch { $leaf = $CurrentPath }
    $operation = 'Found: {0} | Elapsed: {1:00}:{2:00} | Scanning: {3}' -f $script:Stats.TotalFindings, [int]$elapsed.TotalMinutes, $elapsed.Seconds, $leaf
    $activity = '{0} - Scanning {1}' -f $script:ToolName, $Root
    $script:CurrentActivity = $activity
    try {
        Write-Progress -Activity $activity -Status $status -PercentComplete $percent -CurrentOperation $operation
    } catch { }
}

function Complete-ScanProgress {
    if ($script:NoProgressActive) { return }
    try { Write-Progress -Activity $script:CurrentActivity -Completed } catch { }
}

function Write-ScanStatusLine {
    param([Parameter(Mandatory=$true)][string]$CurrentPath)
    Write-ColorLine -Text ('[>>] Scanned: {0} files | Findings: {1} | Current: {2}' -f
        $script:Stats.CandidatesScanned, $script:Stats.TotalFindings, (ConvertTo-SafeText -Text $CurrentPath)) -Color Cyan
}

# ---------------------------------------------------------------------------
# Shared streaming enumeration wrapper used by Quick Win trees, profile
# discovery, pre-count and Scan traversal. Items are dispatched synchronously
# to OnItem as the provider yields them; no directory-wide item array is built.
# Accessible items and captured errors are handled INDEPENDENTLY: every yielded
# item is isolated from later items, even when ErrorVariable also contains
# non-terminating provider errors. A denied descendant skips only itself; a
# top-level root fails only when it produced no usable item and at least one
# enumeration error. State is caller-owned and mutated in place by callbacks.
# ---------------------------------------------------------------------------
function Invoke-DirectoryEnumeration {
    param(
        [Parameter(Mandatory=$true)][string]$Directory,
        [Parameter(Mandatory=$true)][scriptblock]$OnItem,
        [AllowNull()]$State = $null,
        [bool]$IsTopLevel = $false,
        [bool]$CountErrors = $true
    )
    $result = @{
        Errors               = New-Object System.Collections.Generic.List[object]
        ErrorCount           = [long]0
        ItemCount            = [long]0
        ItemErrorCount       = [long]0
        EnumerationStarted   = $false
        EnumerationCompleted = $false
        TopLevelFatal        = $false
    }

    # Per-item boundary shared by real provider output and injected output.
    # Stop-class exceptions propagate immediately; all other item failures are
    # accounted once and never prevent the next yielded sibling from running.
    $dispatchItem = {
        param([AllowNull()]$Item)
        $result.ItemCount++
        try {
            & $OnItem $Item $State | Out-Null
        } catch {
            $itemError = $_
            if (Test-StopError -Err $itemError) { throw }
            $result.ItemErrorCount++
            if ($CountErrors) {
                $itemKey = $Directory
                try {
                    if ($null -ne $Item -and -not [string]::IsNullOrEmpty([string]$Item.FullName)) {
                        $itemKey = [string]$Item.FullName
                    }
                } catch { $itemKey = $Directory }
                if ($itemError.Exception -is [System.IO.PathTooLongException]) {
                    $script:Stats.LongPathsSkipped++
                    $script:Stats.GapUnexpectedAssessment++
                    $script:ContentCoverageIncomplete = $true
                } else {
                    $itemCategory = Get-ItemErrorCategory -ErrorInfo $itemError.Exception
                    Register-ItemError -Key ('FS:' + $itemKey + '|item|' + $itemCategory) -Category $itemCategory -CountNow $true
                    if ($itemCategory -ne 'AccessDenied') {
                        $script:Stats.GapUnexpectedAssessment++
                        $script:ContentCoverageIncomplete = $true
                    }
                }
            }
        }
    }

    # Enumeration errors are intentionally retained (normally a very small
    # list) while items themselves remain streaming. Every non-AccessDenied
    # enumeration error (including LongPath) is a truthful coverage gap;
    # AccessDenied alone remains documented best-effort.
    $consumeErrors = {
        param([AllowNull()]$Errors)
        if ($null -eq $Errors) { return }
        foreach ($enumError in $Errors) {
            $result.ErrorCount++
            # Only a small diagnostic sample is retained; counters and
            # coverage accounting still process every ErrorRecord.
            if ($result.Errors.Count -lt 64) { $result.Errors.Add($enumError) }
            if ($CountErrors) {
                $cat = Get-ItemErrorCategory -ErrorInfo $enumError
                Register-ItemError -Key ('FS:' + $Directory + '|' + $cat) -Category $cat -CountNow $true
                # Register-ItemError accounts LongPath exactly once through
                # LongPathsSkipped. All non-denied categories also mean that
                # the provider inventory was incomplete, so disclose one
                # enumeration coverage gap without re-counting the item error.
                if ($cat -ne 'AccessDenied') {
                    $script:Stats.GapEnumOtherIo++
                    $script:ContentCoverageIncomplete = $true
                }
            }
        }
    }

    if ($script:FaultSeam.Enabled -and $null -ne $script:FaultSeam.EnumHandler) {
        try {
            # New seams emit one item at a time through $dispatchItem. Legacy
            # test seams may still return an Items property; those items are
            # dispatched one-by-one without copying the returned collection.
            $injected = & $script:FaultSeam.EnumHandler $Directory $dispatchItem $State
            if ($null -ne $injected) {
                $result.EnumerationStarted = $true
                if ($null -ne $injected.EnumerationStarted) {
                    $result.EnumerationStarted = [bool]$injected.EnumerationStarted
                }
                if ($null -ne $injected.EnumerationCompleted) {
                    $result.EnumerationCompleted = [bool]$injected.EnumerationCompleted
                }
                if ($null -ne $injected.Items) {
                    foreach ($injectedItem in $injected.Items) {
                        & $dispatchItem $injectedItem | Out-Null
                    }
                }
                & $consumeErrors $injected.Errors | Out-Null
                if ($null -ne $injected.TopLevelFatal -and [bool]$injected.TopLevelFatal) {
                    $result.TopLevelFatal = $true
                }
                if ($IsTopLevel -and $result.ErrorCount -gt 0 -and $result.ItemCount -eq 0) {
                    $result.TopLevelFatal = $true
                }
                return $result
            }
        } catch {
            if (Test-StopError -Err $_) { throw }
            $result.EnumerationStarted = $true
            & $consumeErrors @($_) | Out-Null
            if ($IsTopLevel -and $result.ItemCount -eq 0) { $result.TopLevelFatal = $true }
            return $result
        }
    }

    $dirErrors = $null
    $caughtDirectoryError = $null
    $result.EnumerationStarted = $true
    try {
        # SilentlyContinue suppresses non-terminating provider errors WITHOUT
        # entering catch; -ErrorVariable captures them explicitly so unreadable
        # directories are still accounted for alongside returned items.
        Get-ChildItem -LiteralPath $Directory -Force -ErrorAction SilentlyContinue -ErrorVariable dirErrors |
            ForEach-Object { & $dispatchItem $_ | Out-Null }
        $result.EnumerationCompleted = $true
    } catch {
        if (Test-StopError -Err $_) { throw }
        # A terminating provider error is commonly present in both the catch
        # ErrorRecord and -ErrorVariable. Defer it until after inspecting the
        # latter so one provider failure (especially LongPath, which is an
        # attempt counter) is never accounted twice.
        $caughtDirectoryError = $_
    }
    & $consumeErrors $dirErrors | Out-Null
    if ($null -ne $caughtDirectoryError) {
        $caughtAlreadyCaptured = $false
        foreach ($capturedDirectoryError in $dirErrors) {
            $capturedException = $null
            if ($capturedDirectoryError -is [System.Management.Automation.ErrorRecord]) {
                $capturedException = $capturedDirectoryError.Exception
            } elseif ($capturedDirectoryError -is [System.Exception]) {
                $capturedException = $capturedDirectoryError
            }
            if ([object]::ReferenceEquals($capturedDirectoryError, $caughtDirectoryError) -or
                [object]::ReferenceEquals($capturedException, $caughtDirectoryError.Exception)) {
                $caughtAlreadyCaptured = $true
                break
            }
        }
        if (-not $caughtAlreadyCaptured) {
            & $consumeErrors @($caughtDirectoryError) | Out-Null
        }
    }
    if ($IsTopLevel -and $result.ErrorCount -gt 0 -and $result.ItemCount -eq 0) {
        # The root itself could not be enumerated in a usable way.
        $result.TopLevelFatal = $true
    }
    return $result
}

# ---------------------------------------------------------------------------
# Candidate-universe split shared by pre-count and Scan so both passes use the
# exact same combined content-plus-metadata universe:
#   'Content'  : ordinary content-eligible file at or below MaxFileSizeMB
#   'Metadata' : high-value container/key artifact (any size)
#   'Oversize' : ordinary file above the limit (observed, never a candidate)
#   'None'     : not eligible
# ---------------------------------------------------------------------------
function Get-CandidateKind {
    param([Parameter(Mandatory=$true)][hashtable]$Classification)
    if (-not $Classification.Process) { return 'None' }
    if ($Classification.IsContainerArtifact) { return 'Metadata' }
    if ($Classification.IsKeyFile) { return 'Content' }
    if ($Classification.ScanContent) { return 'Content' }
    return 'None'
}

# ---------------------------------------------------------------------------
# Phase state helpers: every planned phase reaches exactly one terminal state
# (Completed, Failed or Cancelled) and PhasesPlanned always equals the sum of
# the terminal counters.
# ---------------------------------------------------------------------------
function Add-PhaseState {
    param([Parameter(Mandatory=$true)][string]$Name)
    $script:PhaseStates.Add(@{ Name = $Name; State = 'Pending' })
    $script:Stats.PhasesPlanned = [long]$script:PhaseStates.Count
}

function Sync-PhaseCounters {
    [long]$c = 0; [long]$f = 0; [long]$x = 0
    foreach ($p in $script:PhaseStates) {
        if ($p.State -eq 'Completed') { $c++ }
        elseif ($p.State -eq 'Failed') { $f++ }
        elseif ($p.State -eq 'Cancelled') { $x++ }
    }
    $script:Stats.PhasesCompleted = $c
    $script:Stats.PhasesFailed = $f
    $script:Stats.PhasesCancelled = $x
}

function Complete-Phase {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][ValidateSet('Completed','Failed','Cancelled')][string]$State
    )
    foreach ($p in $script:PhaseStates) {
        if ($p.Name -eq $Name -and ($p.State -eq 'Pending' -or $p.State -eq 'Running')) {
            $p.State = $State
            break
        }
    }
    Sync-PhaseCounters
}

# Cancels the current and every not-yet-attempted planned phase exactly once
# (interruption or fatal output failure). Recoverable failures use Failed.
function Stop-RemainingPhases {
    foreach ($p in $script:PhaseStates) {
        if ($p.State -eq 'Pending' -or $p.State -eq 'Running') { $p.State = 'Cancelled' }
    }
    Sync-PhaseCounters
}

# Runs one planned phase inside its own exception boundary. An unexpected
# driver escape marks only this phase Failed (sanitized record), never reveals
# credential values, and never prevents later phases from being attempted.
function Invoke-Phase {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][scriptblock]$Body
    )
    foreach ($p in $script:PhaseStates) { if ($p.Name -eq $Name) { $p.State = 'Running'; break } }
    try {
        & $Body
        Complete-Phase -Name $Name -State 'Completed'
    } catch {
        # Preserve every successfully written finding before classifying a
        # cooperative cancellation or fatal boundary.
        [void](Flush-OutputCheckpoint)
        if (Test-StopError -Err $_) {
            Complete-Phase -Name $Name -State 'Cancelled'
            throw
        }
        if ($script:OutputFailed) {
            # Fatal streaming output failure: stop scanning immediately.
            Complete-Phase -Name $Name -State 'Cancelled'
            throw (New-Object System.OperationCanceledException)
        }
        Complete-Phase -Name $Name -State 'Failed'
        $script:CoverageIncomplete = $true
        Write-ColorLine -Text ('[!] Phase failed ({0}): {1}; continuing with later phases.' -f $Name, $_.Exception.GetType().Name) -Color Yellow
        Write-TxtLogLine ('[!] Phase failed ({0}): {1}' -f $Name, $_.Exception.GetType().Name)
    } finally {
        # A phase boundary is a durability checkpoint, independent of the
        # 512-finding periodic cadence. Final commit semantics remain unchanged.
        [void](Flush-OutputCheckpoint)
    }
}

# ---------------------------------------------------------------------------
# Root state helpers: RootsPlanned = RootsCompleted + RootsFailed +
# RootsCancelled at all times once the plan is frozen.
# ---------------------------------------------------------------------------
function Add-RootState {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][ValidateSet('Root','File')][string]$Kind,
        [Parameter(Mandatory=$true)][ValidateSet('Pending','Failed')][string]$State
    )
    $script:RootStates.Add(@{ Name = $Name; Kind = $Kind; State = $State })
    $script:Stats.RootsPlanned = [long]$script:RootStates.Count
    Sync-RootCounters
}

function Set-RootState {
    param(
        [Parameter(Mandatory=$true)]$Entry,
        [Parameter(Mandatory=$true)][ValidateSet('Running','Completed','Failed','Cancelled')][string]$State
    )
    $Entry.State = $State
    Sync-RootCounters
}

function Sync-RootCounters {
    [long]$c = 0; [long]$f = 0; [long]$x = 0
    foreach ($r in $script:RootStates) {
        if ($r.State -eq 'Completed') { $c++ }
        elseif ($r.State -eq 'Failed') { $f++ }
        elseif ($r.State -eq 'Cancelled') { $x++ }
    }
    $script:Stats.RootsCompleted = $c
    $script:Stats.RootsFailed = $f
    $script:Stats.RootsCancelled = $x
}

function Stop-RemainingRoots {
    foreach ($r in $script:RootStates) {
        if ($r.State -eq 'Pending' -or $r.State -eq 'Running') { $r.State = 'Cancelled' }
    }
    Sync-RootCounters
}

# ---------------------------------------------------------------------------
# Manual depth-first traversal. Each directory is consumed as a provider stream
# through the shared wrapper; reparse points and unknown-attribute items
# fail closed; excluded directories are pruned before enqueueing. Purpose
# 'Count' performs the eligibility pre-count (never incrementing item skip
# counters); 'Scan' performs the actual scan. Both use identical eligibility.
# ---------------------------------------------------------------------------
function Invoke-DirectoryTraversal {
    param(
        [Parameter(Mandatory=$true)][string]$Root,
        [Parameter(Mandatory=$true)][ValidateSet('Count','Scan')][string]$Purpose,
        [Parameter(Mandatory=$true)][long]$EligibleTotal
    )
    $stack = New-Object 'System.Collections.Generic.Stack[string]'
    $stack.Push($Root)
    $isScan = ($Purpose -eq 'Scan')
    Test-FaultOperation -OperationId ('Traversal.' + $Purpose)

    $traversalState = @{
        Stack            = $stack
        LocalCount       = [long]0
        IsScan           = $isScan
        Purpose          = $Purpose
        Root             = $Root
        EligibleTotal    = $EligibleTotal
        CurrentDirectory = ''
        DeadlineCounter   = [long]0
        DispatchTicks     = [long]0
    }
    $traversalItem = {
        param($item, $state)
        [long]$dispatchStartTick = $(if ($script:PerfEnabled) { [System.Diagnostics.Stopwatch]::GetTimestamp() } else { [long]0 })
        try {
            $state.DeadlineCounter++
            if (($state.DeadlineCounter -band 255) -eq 0) { Assert-CooperativeRunLimit }
            if ($item.PSIsContainer) {
                # Fail closed: reparse or unknown-attribute directories are
                # never descended into.
                if (Test-ReparseOrUnknown -Item $item -ErrorKey ('FS:' + [string]$item.FullName) -CountErrors $state.IsScan) { return }
                if (Test-ExcludedDirectory -FullPath $item.FullName -Name $item.Name) { return }
                $state.Stack.Push($item.FullName)
                return
            }

            $fullName = [string]$item.FullName
            $identity = Get-PathIdentity -PathValue $fullName -Item $item
            if ($null -eq $identity) { return }
            if (Test-IsSelfOrOutput -FullPath $identity) { return }
            # Only exact files with a TERMINAL Quick Win / supplied outcome
            # are suppressed here; nothing else (never parents/siblings).
            if ($script:TerminalAssessedPaths.Contains($identity)) { return }
            # Fail-closed reparse check before the file is ever opened.
            if (Test-ReparseOrUnknown -Item $item -ErrorKey ('FS:' + $fullName) -CountErrors $state.IsScan) { return }
            # ADS are assessed for every in-scope accessible non-reparse file
            # carrier during Scan, independently of the main stream outcome.
            if ($state.IsScan) {
                Invoke-CarrierAdsOnce -FullPath $identity -Item $item -TrackAcrossPhases $false
            }

            $parentName = ''
            try { $parentName = [System.IO.Path]::GetFileName($item.DirectoryName) } catch { $parentName = '' }
            $classification = Get-FileClassification -FullPath $fullName -Name $item.Name -Extension $item.Extension -ParentName $parentName -Length ([long]$item.Length) -ForceEligible $false
            $kind = Get-CandidateKind -Classification $classification
            if ($kind -eq 'None') { return }

            if ($state.Purpose -eq 'Count') {
                # Pre-count never increments item-level skip counters.
                if ($kind -eq 'Content') { $script:Stats.ContentCandidatesPreCounted++; $state.LocalCount++ }
                elseif ($kind -eq 'Metadata') { $script:Stats.MetadataArtifactCandidatesPreCounted++; $state.LocalCount++ }
                return
            }

            if ($kind -eq 'Oversize') {
                # Observed during Scan and counted; not an invocation.
                $script:Stats.OversizeSkipped++
                return
            }
            $state.LocalCount++
            $script:Stats.CandidatesScanned++
            $script:Stats.FullScanAssessed++   # FullScanAssessmentInvocations
            try {
                $outcome = Invoke-FileAssessment -FullPath $fullName -Classification $classification -FromQuickWin $false
            } catch {
                if (Test-StopError -Err $_) { $script:Stats.FullScanCancelledInFlight++; throw }
                Set-LastAssessmentFailure -PrimaryCause 'Unexpected' -FailureType 'UnexpectedException' -FailureHResult 0
                $outcome = 'UnexpectedFailure'
            }
            Register-AssessmentOutcome -Outcome $outcome -FromQuickWin $false
            # Ordinary full-traversal descendants are NEVER added to
            # TerminalAssessedPaths or any other drive-wide path set.
            if (-not (Test-TerminalOutcome -Outcome $outcome)) {
                Register-AssessmentCoverageGap -Outcome $outcome
            }
            # Record the assessment's one primary cause before a simultaneous
            # output failure transitions the in-flight phase to cancellation.
            if ($script:OutputFailed) { throw (New-Object System.OperationCanceledException) }
            Update-ScanProgress -Root $state.Root -CurrentPath $fullName -Scanned $state.LocalCount -Eligible $state.EligibleTotal
            if (($script:Stats.CandidatesScanned % 500) -eq 0) {
                Write-ScanStatusLine -CurrentPath $fullName
            }
        } catch {
            if (Test-StopError -Err $_) { throw }
            if (-not $state.IsScan) { return }
            if ($_.Exception -is [System.IO.PathTooLongException]) {
                $script:Stats.LongPathsSkipped++
                $script:Stats.GapUnexpectedAssessment++
                $script:ContentCoverageIncomplete = $true
            } else {
                $cat = Get-ItemErrorCategory -ErrorInfo $_.Exception
                Register-ItemError -Key ('FS:' + $state.CurrentDirectory + '|item|' + $cat) -Category $cat -CountNow $true
                if ($cat -ne 'AccessDenied') {
                    $script:Stats.GapUnexpectedAssessment++
                    $script:ContentCoverageIncomplete = $true
                }
            }
        } finally {
            if ($script:PerfEnabled) {
                $state.DispatchTicks += ([System.Diagnostics.Stopwatch]::GetTimestamp() - $dispatchStartTick)
            }
        }
    }

    while ($stack.Count -gt 0) {
        Assert-CooperativeRunLimit
        if ($script:OutputFailed) { throw (New-Object System.OperationCanceledException) }
        $currentDir = $stack.Pop()
        $isTop = ($currentDir -eq $Root)
        $traversalState.CurrentDirectory = $currentDir
        [long]$dispatchBefore = [long]$traversalState.DispatchTicks
        [long]$enumerationStartTick = $(if ($script:PerfEnabled) { [System.Diagnostics.Stopwatch]::GetTimestamp() } else { [long]0 })
        $enum = Invoke-DirectoryEnumeration -Directory $currentDir -IsTopLevel $isTop -CountErrors $isScan -State $traversalState -OnItem $traversalItem
        if ($script:PerfEnabled) {
            [long]$enumerationTicks = [System.Diagnostics.Stopwatch]::GetTimestamp() - $enumerationStartTick
            [long]$callbackTicks = [long]$traversalState.DispatchTicks - $dispatchBefore
            [long]$exclusiveTraversalTicks = $enumerationTicks - $callbackTicks
            if ($exclusiveTraversalTicks -gt 0) { Add-PerfStageTicks -Stage 'Traversal' -Ticks $exclusiveTraversalTicks }
        }
        if ($enum.TopLevelFatal -and $isTop) { $script:LastTraversalRootFailed = $true; continue }
        # Directory ADS are assessed per current directory (root included),
        # during the Scan pass only and only in Deep + IncludeAlternateDataStreams.
        if ($isScan) { Invoke-CarrierAdsOnce -FullPath $currentDir -IsDirectory $true -TrackAcrossPhases $false }
    }
    return ([long]$traversalState.LocalCount)
}

# ---------------------------------------------------------------------------
# Directly supplied -Path files. Every planned supplied file is a planned item
# and reaches exactly one terminal state derived from the STRUCTURED assessment
# outcome — never from an attempted call: Completed only after a terminal
# completed/policy/artifact outcome; missing, inaccessible, self/output,
# invalid or unexpected outcomes increment RootsFailed and coverage becomes
# incomplete. Findings never influence these states. Ordinary canonicalization
# (case / dot-segments) de-duplicates spellings; no 8.3 alias equivalence is
# claimed without a genuine Windows short-name test.
# ---------------------------------------------------------------------------
function Invoke-SuppliedFiles {
    param([Parameter(Mandatory=$true)]$Files)
    if ($Files.Count -eq 0) { return }

    $eligibleFiles = New-Object System.Collections.Generic.List[string]
    $fileClassifications = @{}
    $fileEntries = @{}
    $seenSuppliedIdentities = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    # Accounting lookup only: resolve each planned file entry once. This map
    # never suppresses assessment; it avoids O(N^2) provider calls for large
    # operator-supplied -Path arrays.
    $pendingFileEntries = @{}
    foreach ($plannedEntry in $script:RootStates) {
        if ($plannedEntry.Kind -ne 'File' -or $plannedEntry.State -ne 'Pending') { continue }
        $plannedIdentity = Get-PathIdentity -PathValue ([string]$plannedEntry.Name)
        if ($null -ne $plannedIdentity -and -not $pendingFileEntries.ContainsKey($plannedIdentity)) {
            $pendingFileEntries[$plannedIdentity] = $plannedEntry
        }
    }
    foreach ($suppliedFile in $Files) {
        Assert-CooperativeRunLimit
        # Resolve through the same provider-identity helper used by Quick Wins
        # and traversal. No universal 8.3 alias-equivalence claim is made.
        $normalizedSupplied = Get-PathIdentity -PathValue $suppliedFile
        if ($null -ne $normalizedSupplied) { $suppliedFile = $normalizedSupplied }
        if (-not $seenSuppliedIdentities.Add($suppliedFile)) { continue }   # every duplicate spelling is accounted once
        $entry = $null
        if ($pendingFileEntries.ContainsKey($suppliedFile)) { $entry = $pendingFileEntries[$suppliedFile] }
        if ($null -eq $entry) {
            # Direct invocation (or an unplanned path): plan it now so every
            # supplied file still reaches exactly one accounted terminal state.
            Add-RootState -Name $suppliedFile -Kind 'File' -State 'Pending'
            $entry = $script:RootStates[$script:RootStates.Count - 1]
            $pendingFileEntries[$suppliedFile] = $entry
        }
        if (Test-IsSelfOrOutput -FullPath $suppliedFile) {
            if ($null -ne $entry) { Set-RootState -Entry $entry -State 'Failed' }
            $script:CoverageIncomplete = $true
            continue
        }
        if ($script:TerminalAssessedPaths.Contains($suppliedFile)) {
            # Terminally assessed during Quick Wins: completed, no rescan.
            if ($null -ne $entry) { Set-RootState -Entry $entry -State 'Completed' }
            continue
        }
        $item = $null
        try { $item = Get-Item -LiteralPath $suppliedFile -Force -ErrorAction Stop } catch { $item = $null }
        if ($null -eq $item) {
            $cat = 'Other'
            try { Get-Item -LiteralPath $suppliedFile -Force -ErrorAction Stop | Out-Null } catch { $cat = Get-ItemErrorCategory -ErrorInfo $_.Exception }
            Register-ItemError -Key ('FS:' + $suppliedFile + '|' + $cat) -Category $cat -CountNow $true
            if ($null -ne $entry) { Set-RootState -Entry $entry -State 'Failed' }
            $script:CoverageIncomplete = $true
            continue
        }
        # Fail-closed reparse check on the supplied file itself.
        if (Test-ReparseOrUnknown -Item $item -ErrorKey ('FS:' + $suppliedFile) -CountErrors $true) {
            if ($null -ne $entry) { Set-RootState -Entry $entry -State 'Failed' }
            $script:CoverageIncomplete = $true
            continue
        }
        $suppliedIdentity = Get-PathIdentity -PathValue $suppliedFile -Item $item
        if ($null -eq $suppliedIdentity) {
            if ($null -ne $entry) { Set-RootState -Entry $entry -State 'Failed' }
            $script:CoverageIncomplete = $true
            continue
        }
        $suppliedFile = $suppliedIdentity
        # Supplied carriers can be suppressed from traversal after a terminal
        # main-stream result. Assess their ADS first, regardless of the later
        # main classification/read outcome, and record the provider identity.
        Invoke-CarrierAdsOnce -FullPath $suppliedIdentity -Item $item -TrackAcrossPhases $true
        $parentName = ''
        try { $parentName = [System.IO.Path]::GetFileName($item.DirectoryName) } catch { $parentName = '' }
        $cls = Get-FileClassification -FullPath $suppliedFile -Name $item.Name -Extension $item.Extension -ParentName $parentName -Length ([long]$item.Length) -ForceEligible $true
        if (-not $cls.Process) {
            # Reached only for empty files with ForceEligible: deterministic
            # policy decision — completed-but-skipped, not a false read success.
            $script:Stats.FullScanAssessed++
            Register-AssessmentOutcome -Outcome 'PolicySkippedTerminal' -FromQuickWin $false
            [void]$script:TerminalAssessedPaths.Add($suppliedIdentity)
            if ($null -ne $entry) { Set-RootState -Entry $entry -State 'Completed' }
            continue
        }
        $kind = Get-CandidateKind -Classification $cls
        if ($kind -eq 'Content') { $script:Stats.ContentCandidatesPreCounted++ }
        elseif ($kind -eq 'Metadata') { $script:Stats.MetadataArtifactCandidatesPreCounted++ }
        elseif ($kind -eq 'Oversize') { $kind = 'Metadata' }  # unreachable with ForceEligible; defensive
        $eligibleFiles.Add($suppliedFile)
        $fileClassifications[$suppliedFile] = $cls
        if ($null -ne $entry) { $fileEntries[$suppliedFile] = $entry }
    }

    Write-ColorLine -Text ('[*] Pre-counting eligible files on (directly supplied files) ... {0} candidates found' -f $eligibleFiles.Count.ToString('N0')) -Color Cyan
    $script:Stats.RootsScanned++
    foreach ($suppliedFile in $eligibleFiles) {
        Assert-CooperativeRunLimit
        if ($script:OutputFailed) { throw (New-Object System.OperationCanceledException) }
        $script:Stats.CandidatesScanned++
        $script:Stats.FullScanAssessed++
        $outcome = 'UnexpectedFailure'
        try {
            $outcome = Invoke-FileAssessment -FullPath $suppliedFile -Classification $fileClassifications[$suppliedFile] -FromQuickWin $false
        } catch {
            if (Test-StopError -Err $_) { $script:Stats.FullScanCancelledInFlight++; throw }
            Set-LastAssessmentFailure -PrimaryCause 'Unexpected' -FailureType 'UnexpectedException' -FailureHResult 0
            $outcome = 'UnexpectedFailure'
        }
        Register-AssessmentOutcome -Outcome $outcome -FromQuickWin $false
        $entry = $null
        if ($fileEntries.ContainsKey($suppliedFile)) { $entry = $fileEntries[$suppliedFile] }
        if (Test-TerminalOutcome -Outcome $outcome) {
            [void]$script:TerminalAssessedPaths.Add($suppliedFile)
            if ($null -ne $entry) { Set-RootState -Entry $entry -State 'Completed' }
        } else {
            Register-AssessmentCoverageGap -Outcome $outcome
            if ($null -ne $entry) { Set-RootState -Entry $entry -State 'Failed' }
            $script:CoverageIncomplete = $true
        }
        if (($script:Stats.CandidatesScanned % 500) -eq 0) {
            Write-ScanStatusLine -CurrentPath $suppliedFile
        }
    }
}

# ---------------------------------------------------------------------------
# Full filesystem phase body: supplied files, then every planned root with a
# Count pass and an ALWAYS-executed Scan pass (even at zero pre-count) for
# every valid planned root. An unexpected Count/Scan escape forces the root to
# Failed — never Completed; a still-valid root receives a recovery Scan under
# a fresh exception boundary. Remaining roots always continue.
# ---------------------------------------------------------------------------
function Invoke-FullScanPhase {
    param([Parameter(Mandatory=$true)]$Plan)
    Write-ColorLine -Text '[*] Phase: Full scan of eligible candidate files' -Color Cyan
    Test-FaultOperation -OperationId 'Phase.FullScan'

    if (-not $script:FullScanPlanSafe) {
        # Scan-plan / drive-discovery / safety-exclusion failure: no traversal
        # with an unsafe or unknown policy. The phase fails; targeted phases
        # already ran.
        throw (New-Object System.InvalidOperationException ('scan plan or safety exclusions unsafe'))
    }

    # Directly supplied files: each planned file reaches exactly one terminal
    # state derived from its structured assessment outcome.
    if ($Plan.Files.Count -gt 0) {
        Invoke-SuppliedFiles -Files $Plan.Files
    }

    foreach ($root in $Plan.Roots) {
        Assert-CooperativeRunLimit
        if ($script:OutputFailed) { throw (New-Object System.OperationCanceledException) }
        $rootEntry = $null
        foreach ($r in $script:RootStates) {
            if ($r.Kind -eq 'Root' -and $r.Name.Equals($root, [System.StringComparison]::OrdinalIgnoreCase) -and $r.State -eq 'Pending') { $rootEntry = $r; break }
        }
        if (Test-RootExplicitlyExcluded -Root $root) {
            if ($null -ne $rootEntry) { Set-RootState -Entry $rootEntry -State 'Completed' }
            Write-ColorLine -Text ('[*] Root skipped by operator -ExcludePath policy: {0}' -f (ConvertTo-SafeText -Text $root)) -Color Cyan
            continue
        }
        if ($null -ne $rootEntry) { Set-RootState -Entry $rootEntry -State 'Running' }

        # Defensive re-validation immediately before traversal: malformed,
        # drive-relative, missing or inaccessible roots fail here.
        if (-not (Test-RootValidForTraversal -Root $root -CountErrors $true)) {
            if ($null -ne $rootEntry) { Set-RootState -Entry $rootEntry -State 'Failed' }
            $script:CoverageIncomplete = $true
            Write-ColorLine -Text ('[!] Root failed validation and will not be scanned: {0}' -f (ConvertTo-SafeText -Text $root)) -Color Yellow
            continue
        }
        $script:Stats.RootsScanned++
        $script:LastTraversalRootFailed = $false

        # ---- Purpose Count --------------------------------------------------
        [long]$eligible = 0
        $countFailed = $false
        try {
            $eligible = Invoke-DirectoryTraversal -Root $root -Purpose Count -EligibleTotal 0
        } catch {
            if (Test-StopError -Err $_) { throw }
            $countFailed = $true
        }
        if ($script:LastTraversalRootFailed) { $countFailed = $true }

        if ($countFailed) {
            # The root can never become Completed. If it still passes defensive
            # validation, attempt a recovery Scan under a fresh exception
            # boundary so accessible findings are not discarded; the root
            # remains Failed even when the recovery Scan finds data.
            if ($null -ne $rootEntry) { Set-RootState -Entry $rootEntry -State 'Failed' }
            $script:CoverageIncomplete = $true
            Write-ColorLine -Text ('[!] Root pre-count failed; attempting recovery scan: {0}' -f (ConvertTo-SafeText -Text $root)) -Color Yellow
            if (Test-RootValidForTraversal -Root $root -CountErrors $true) {
                $script:LastTraversalRootFailed = $false
                try {
                    [void](Invoke-DirectoryTraversal -Root $root -Purpose Scan -EligibleTotal 0)
                } catch {
                    if (Test-StopError -Err $_) { throw }
                }
            }
            Complete-ScanProgress
            continue
        }

        Write-ColorLine -Text ('[*] Pre-counting eligible files on {0} ... {1} candidates found' -f (ConvertTo-SafeText -Text $root), $eligible.ToString('N0')) -Color Cyan
        [long]$assessedBefore = $script:Stats.FullScanAssessed

        # ---- Purpose Scan: ALWAYS runs for a valid planned root, including
        # when the pre-count denominator is zero. -----------------------------
        $scanFailed = $false
        try {
            [void](Invoke-DirectoryTraversal -Root $root -Purpose Scan -EligibleTotal $eligible)
        } catch {
            if (Test-StopError -Err $_) { throw }
            $scanFailed = $true
        }
        if ($script:LastTraversalRootFailed) { $scanFailed = $true }

        if ($scanFailed) {
            if ($null -ne $rootEntry) { Set-RootState -Entry $rootEntry -State 'Failed' }
            $script:CoverageIncomplete = $true
            Write-ColorLine -Text ('[!] Root scan failed; coverage incomplete: {0}' -f (ConvertTo-SafeText -Text $root)) -Color Yellow
            Complete-ScanProgress
            continue
        }

        if ($null -ne $rootEntry) { Set-RootState -Entry $rootEntry -State 'Completed' }
        [long]$assessedHere = $script:Stats.FullScanAssessed - $assessedBefore
        Write-ColorLine -Text ('[*] Root complete: {0} | eligible: {1} | assessed: {2} | findings so far: {3}' -f (ConvertTo-SafeText -Text $root), $eligible.ToString('N0'), $assessedHere.ToString('N0'), $script:Stats.TotalFindings) -Color Cyan
        if ($assessedHere -ne $eligible) {
            # A file appearing/disappearing between passes is a documented race:
            # an explicit inventory coverage gap (truthful COVERAGE INCOMPLETE
            # with non-zero exit), never fabricated equality. Later files and
            # roots still continue.
            $script:PreCountAssessedMismatch = $true
            $script:InventoryChanged = $true
            $script:Stats.GapInventoryMismatch++
            $script:ContentCoverageIncomplete = $true
            Write-ColorLine -Text ('[!] Pre-count ({0}) and assessed ({1}) differ for {2}; the filesystem likely changed during the scan (inventory coverage gap).' -f $eligible, $assessedHere, (ConvertTo-SafeText -Text $root)) -Color Yellow
        }
        Complete-ScanProgress
    }

    # Standard/Deep with nothing scannable is an incomplete coverage run,
    # never a success.
    if ($script:Stats.RootsCompleted -eq 0 -and $script:Stats.FullScanAssessed -eq 0) {
        $script:CoverageIncomplete = $true
        Write-ColorLine -Text '[!] No valid root or supplied file could be scanned; coverage incomplete.' -Color Red
    }

    # The Full filesystem phase is Failed when ANY planned top-level root or
    # direct item failed; it is Completed only when all planned items complete.
    # Expected denied descendants remain local skips and never fail it.
    Sync-RootCounters
    if ($script:Stats.RootsFailed -gt 0) {
        throw (New-Object System.InvalidOperationException ('one or more planned roots/direct items failed'))
    }
}

# ---------------------------------------------------------------------------
# Performance diagnostics commit. The opt-in JSON is built exclusively from
# fixed counters, static pattern identifiers/groups, aggregate ticks and the
# bounded hashed outlier records. It deliberately contains no output path,
# source path, basename, content, finding, value or error text.
# ---------------------------------------------------------------------------
function Write-PerformanceProfile {
    if (-not $script:PerfEnabled) { return $true }
    if ($script:PerfCommitOk) { return $true }
    if ($null -eq $script:PerfStream) {
        Register-OutputFailure -Detail 'PerfStreamUnavailable'
        return $false
    }

    $writer = $null
    try {
        $script:Perf.EndTick = [long][System.Diagnostics.Stopwatch]::GetTimestamp()
        [long]$elapsedTicks = [long]$script:Perf.EndTick - [long]$script:Perf.StartTick
        if ($elapsedTicks -lt 0) { $elapsedTicks = [long]0 }
        [double]$elapsedSeconds = 0.0
        if ($script:Perf.Frequency -gt 0) {
            $elapsedSeconds = [double]$elapsedTicks / [double]$script:Perf.Frequency
        }
        [double]$filesPerMinute = 0.0
        [double]$physicalMiBPerSecond = 0.0
        [double]$emissionMiBPerSecond = 0.0
        [long]$physicalTotal = [long]$script:Perf.PhysicalBytesPreflight + [long]$script:Perf.PhysicalBytesEmission
        if ($elapsedSeconds -gt 0.0) {
            $filesPerMinute = ([double]$script:Perf.Assessed * 60.0) / $elapsedSeconds
            $physicalMiBPerSecond = ([double]$physicalTotal / 1048576.0) / $elapsedSeconds
            $emissionMiBPerSecond = ([double][long]$script:Perf.PhysicalBytesEmission / 1048576.0) / $elapsedSeconds
        }

        $stageRows = [ordered]@{}
        foreach ($stageName in @('Traversal','Open','Read','Decode','Matching','Semantics','Dedupe','Redaction','Output')) {
            $stageRows[$stageName] = [long]$script:Perf.StageTicks[$stageName]
        }

        $patternRows = New-Object 'System.Collections.Generic.List[object]'
        $groupMap = @{}
        foreach ($patternPerf in $script:Perf.Patterns) {
            $patternRows.Add([pscustomobject][ordered]@{
                Id = [string]$patternPerf.Id
                Group = [string]$patternPerf.Group
                Calls = [long]$patternPerf.Calls
                Matches = [long]$patternPerf.Matches
                Timeouts = [long]$patternPerf.Timeouts
                Errors = [long]$patternPerf.Errors
                Ticks = [long]$patternPerf.Ticks
                SkippedFileGate = [long]$patternPerf.SkippedFileGate
                SkippedTrigger = [long]$patternPerf.SkippedTrigger
            })
            $groupName = [string]$patternPerf.Group
            if (-not $groupMap.ContainsKey($groupName)) {
                $groupMap[$groupName] = [pscustomobject][ordered]@{
                    Group=$groupName; Calls=[long]0; Matches=[long]0
                    Timeouts=[long]0; Errors=[long]0; Ticks=[long]0
                    SkippedFileGate=[long]0; SkippedTrigger=[long]0
                }
            }
            $groupPerf = $groupMap[$groupName]
            $groupPerf.Calls = [long]$groupPerf.Calls + [long]$patternPerf.Calls
            $groupPerf.Matches = [long]$groupPerf.Matches + [long]$patternPerf.Matches
            $groupPerf.Timeouts = [long]$groupPerf.Timeouts + [long]$patternPerf.Timeouts
            $groupPerf.Errors = [long]$groupPerf.Errors + [long]$patternPerf.Errors
            $groupPerf.Ticks = [long]$groupPerf.Ticks + [long]$patternPerf.Ticks
            $groupPerf.SkippedFileGate = [long]$groupPerf.SkippedFileGate + [long]$patternPerf.SkippedFileGate
            $groupPerf.SkippedTrigger = [long]$groupPerf.SkippedTrigger + [long]$patternPerf.SkippedTrigger
        }
        $groupRows = New-Object 'System.Collections.Generic.List[object]'
        foreach ($groupName in @($groupMap.Keys | Sort-Object)) { $groupRows.Add($groupMap[$groupName]) }
        $outlierRows = @($script:Perf.Outliers | Sort-Object @{ Expression = { [long]$_.Ticks }; Descending = $true })

        $profile = [pscustomobject][ordered]@{
            SchemaVersion = [int]$script:Perf.SchemaVersion
            ToolVersion = [string]$script:ToolVersion
            Mode = [string]$Mode
            StopwatchFrequency = [long]$script:Perf.Frequency
            StartTick = [long]$script:Perf.StartTick
            EndTick = [long]$script:Perf.EndTick
            ElapsedTicks = $elapsedTicks
            ElapsedSeconds = $elapsedSeconds
            Assessed = [long]$script:Perf.Assessed
            FilesPerMinute = $filesPerMinute
            PhysicalBytesPreflight = [long]$script:Perf.PhysicalBytesPreflight
            PhysicalBytesEmission = [long]$script:Perf.PhysicalBytesEmission
            PhysicalBytesTotal = $physicalTotal
            LogicalBytesEligible = [long]$script:Stats.ContentBytesEligible
            LogicalBytesExamined = [long]$script:Stats.ContentBytesExamined
            LogicalSampledBytesExamined = [long]$script:Stats.SampledBytesExamined
            PhysicalMiBPerSecond = $physicalMiBPerSecond
            EmissionMiBPerSecond = $emissionMiBPerSecond
            UnitsNormal = [long]$script:Perf.UnitsNormal
            UnitsRolling = [long]$script:Perf.UnitsRolling
            PathNormalizations = [long]$script:Perf.PathNormalizations
            RegexBudgetGaps = [long]$script:Stats.GapRegexBudget
            RegexTimeoutEvents = [long]$script:Stats.RegexTimeoutEvents
            CooperativeLimitReached = [bool]$script:CooperativeLimitReached
            LimitReason = [string]$script:LimitReason
            StageTicks = [pscustomobject]$stageRows
            RegexByGroup = $groupRows.ToArray()
            RegexByPattern = $patternRows.ToArray()
            Outliers = $outlierRows
        }
        $json = $profile | ConvertTo-Json -Depth 8 -Compress
        $noBomUtf8 = New-Object System.Text.UTF8Encoding ($false)
        $writer = New-Object System.IO.StreamWriter ($script:PerfStream, $noBomUtf8)
        $writer.Write($json)
        $writer.Write("`r`n")
        $writer.Flush()
        $script:PerfStream.Flush()
        $script:PerfCommitOk = $true
        return $true
    } catch {
        Register-OutputFailure -Detail $_.Exception.GetType().Name
        return $false
    } finally {
        if ($null -ne $writer) {
            try { $writer.Dispose() } catch { if ($script:PerfCommitOk) { $script:Stats.OutputCleanupWarnings++ } }
            $script:PerfStream = $null
        } elseif ($null -ne $script:PerfStream -and -not $script:PerfCommitOk) {
            try { $script:PerfStream.Dispose() } catch { }
            $script:PerfStream = $null
        }
    }
}

# ---------------------------------------------------------------------------
# Output setup: create the output directory, reserve the versioned TXT/CSV pair
# and, when requested, the diagnostic JSON with FileMode.CreateNew (unsuffixed
# first, then _01.._9999; one suffix across the set), open the two streaming
# result writers as UTF-8 without BOM and write headers. Any failure is
# fatal (exit 1) before scanning. Existing result files are never overwritten;
# only a still-zero-byte reservation created by THIS attempt may be rolled back.
# ---------------------------------------------------------------------------
function Initialize-OutputFiles {
    $noBomUtf8 = New-Object System.Text.UTF8Encoding ($false)

    $outDir = $null
    try {
        $outDir = [System.IO.Path]::GetFullPath($OutputDirectory)
    } catch {
        Write-ColorLine -Text ('[!] FATAL: Output directory path is invalid: {0}' -f (ConvertTo-SafeText -Text $OutputDirectory)) -Color Red
        return $false
    }
    if (-not (Test-TargetedPathPolicy -PathValue $outDir -ErrorKey ('OUTPUT:policy|' + $outDir) -CountErrors $true)) {
        Write-ColorLine -Text ('[!] FATAL: Output directory violates the local/reparse policy: {0}' -f (ConvertTo-SafeText -Text $outDir)) -Color Red
        return $false
    }
    try {
        if (-not (Test-Path -LiteralPath $outDir -PathType Container -ErrorAction SilentlyContinue)) {
            [void][System.IO.Directory]::CreateDirectory($outDir)
        }
    } catch {
        Write-ColorLine -Text ('[!] FATAL: Output directory cannot be created: {0}' -f (ConvertTo-SafeText -Text $outDir)) -Color Red
        return $false
    }
    if (-not (Test-TargetedPathPolicy -PathValue $outDir -ErrorKey ('OUTPUT:created-policy|' + $outDir) -CountErrors $true)) {
        Write-ColorLine -Text ('[!] FATAL: Output directory failed the post-create local/reparse policy: {0}' -f (ConvertTo-SafeText -Text $outDir)) -Color Red
        return $false
    }
    $outDirProbe = Get-FileSystemProbe -LiteralPath $outDir -ExpectedType 'Container' -CountErrors $true -ErrorKey ('OUTPUT:path|' + $outDir)
    if ($outDirProbe.Status -ne 'Ok' -or
        (Test-ReparseOrUnknown -Item $outDirProbe.Item -ErrorKey ('OUTPUT:reparse|' + $outDir) -CountErrors $true)) {
        Write-ColorLine -Text ('[!] FATAL: Output directory is unavailable or unsafe: {0}' -f (ConvertTo-SafeText -Text $outDir)) -Color Red
        return $false
    }
    # Build result paths from the provider-resolved directory identity. This
    # keeps self/output exclusion aligned when -OutputDirectory was supplied
    # through an alternate (for example 8.3) spelling.
    $outDirIdentity = Get-PathIdentity -PathValue $outDir -Item $outDirProbe.Item
    if ($null -ne $outDirIdentity) { $outDir = $outDirIdentity }

    $computer = $env:COMPUTERNAME
    if ([string]::IsNullOrEmpty($computer)) { $computer = 'UNKNOWN' }
    $computer = ConvertTo-SafeText -Text $computer
    $stamp = (Get-Date).ToString('yyyyMMdd_HHmmss')
    $baseName = '{0}_v{1}_Results_{2}_{3}' -f $script:ToolName, $script:ToolVersion, $computer, $stamp

    # Reserve the TXT/CSV zero-byte paths and optional diagnostic path with
    # CreateNew semantics before constructing either StreamWriter.
    $reservedPair = $false
    for ($i = 0; $i -le 9999; $i++) {
        $suffix = ''
        if ($i -gt 0) { $suffix = '_' + $i.ToString('00') }
        $txtCandidate = Join-Path -Path $outDir -ChildPath ($baseName + $suffix + '.txt')
        $csvCandidate = Join-Path -Path $outDir -ChildPath ($baseName + $suffix + '.csv')
        $perfCandidate = Join-Path -Path $outDir -ChildPath ($baseName + $suffix + '.perf.json')
        $txtFs = $null
        $csvFs = $null
        $perfFs = $null
        try {
            $txtFs = New-Object System.IO.FileStream ($txtCandidate, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
        } catch { $txtFs = $null }
        if ($null -eq $txtFs) { continue }
        try {
            $csvFs = New-Object System.IO.FileStream ($csvCandidate, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
        } catch { $csvFs = $null }
        if ($null -eq $csvFs) {
            # Second reservation failed: close both handles and delete only the
            # zero-byte first file created by THIS same reservation attempt.
            try { $txtFs.Dispose() } catch { }
            try {
                $roll = Get-Item -LiteralPath $txtCandidate -Force -ErrorAction Stop
                if ($roll.Length -eq 0) { [System.IO.File]::Delete($txtCandidate) }
            } catch { }
            continue
        }
        if ($script:PerfEnabled) {
            try {
                $perfFs = New-Object System.IO.FileStream ($perfCandidate, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
            } catch { $perfFs = $null }
            if ($null -eq $perfFs) {
                try { $txtFs.Dispose() } catch { }
                try { $csvFs.Dispose() } catch { }
                foreach ($ownedZeroPath in @($txtCandidate,$csvCandidate)) {
                    try {
                        $ownedZeroItem = Get-Item -LiteralPath $ownedZeroPath -Force -ErrorAction Stop
                        if ($ownedZeroItem.Length -eq 0) { [System.IO.File]::Delete($ownedZeroPath) }
                    } catch { }
                }
                continue
            }
        }
        $script:TxtPath = $txtCandidate
        $script:CsvPath = $csvCandidate
        $script:PerfPath = $(if ($script:PerfEnabled) { $perfCandidate } else { '' })
        $script:TxtStream = $txtFs
        $script:CsvStream = $csvFs
        $script:PerfStream = $perfFs
        $reservedPair = $true
        break
    }
    if (-not $reservedPair) {
        Write-ColorLine -Text '[!] FATAL: Could not reserve a unique result-file set (all suffixes exhausted). Aborting before scanning.' -Color Red
        return $false
    }

    try {
        $script:TxtWriter = New-Object System.IO.StreamWriter ($script:TxtStream, $noBomUtf8)
        $script:CsvWriter = New-Object System.IO.StreamWriter ($script:CsvStream, $noBomUtf8)
        $script:WritersOpen = $true

        if ($script:FaultSeam.Enabled -and $script:FaultSeam.OutputFailureAt -eq 'TxtWrite') {
            throw (New-Object System.IO.IOException ('injected TXT init write failure'))
        }
        $script:TxtWriter.Write(('{0} results - {1} - {2}' -f $script:ToolName, $computer, (Get-Date).ToString('yyyy-MM-dd HH:mm:ss')))
        $script:TxtWriter.Write("`r`n")
        $script:TxtWriter.Write(('Tool version : {0}' -f $script:ToolVersion))
        $script:TxtWriter.Write("`r`n")
        $script:TxtWriter.Write(('Mode: {0} | RevealSecrets: {1} | LargeFileMode: {2} | PerFileBudgetMB: {3} | MaxRunMinutes: {4}' -f $Mode, $(if ($script:RevealActive) { 'Yes' } else { 'No' }), $script:LargeFileModeActive, $MaxFileSizeMB, $script:MaxRunMinutesActive))
        $script:TxtWriter.Write("`r`n")
        $script:TxtWriter.Write(('=' * 60))
        $script:TxtWriter.Write("`r`n`r`n")

        if ($script:FaultSeam.Enabled -and $script:FaultSeam.OutputFailureAt -eq 'CsvWrite') {
            throw (New-Object System.IO.IOException ('injected CSV init write failure'))
        }
        $script:CsvWriter.Write('Timestamp,Type,Category,Severity,Confidence,Source,FilePath,RegistryPath,ValueName,LineNumber,PatternId,Value,Context,Drive,UserProfile,Notes,FindingKind,App,SourceKind,Account,Endpoint,Port,PhysicalPath,LogicalPath,ContainerEntry,KeyPath,DecodeChain,ConfidenceEvidence,CoverageMode,SampleOffset')
        $script:CsvWriter.Write("`r`n")
        $script:TxtWriter.Flush()
        $script:TxtStream.Flush()
        $script:CsvWriter.Flush()
        $script:CsvStream.Flush()
        $script:OutputDataWritten = $true
        $script:OutputPairInitialized = $true
        return $true
    } catch {
        Write-ColorLine -Text '[!] FATAL: Result files cannot be created or written. Aborting before scanning.' -Color Red
        Close-OutputFiles
        # Roll back only still-zero-byte reservations created by THIS attempt;
        # a file that already holds data is preserved as partial evidence.
        foreach ($p in @($script:TxtPath, $script:CsvPath, $script:PerfPath)) {
            try {
                if (-not [string]::IsNullOrEmpty($p)) {
                    $ri = Get-Item -LiteralPath $p -Force -ErrorAction Stop
                    if ($ri.Length -eq 0) { [System.IO.File]::Delete($p) }
                }
            } catch { }
        }
        return $false
    }
}

function Close-OutputFiles {
    # Idempotent cleanup-only close. No flush and no second summary attempt
    # here: data commits happen only at the explicit finalization commit
    # points. A cleanup failure after a successful commit is a warning, never
    # a retroactive invalidation of committed bytes.
    if ($null -ne $script:TxtWriter) {
        try { $script:TxtWriter.Close() } catch { if ($script:TxtCommitOk) { $script:Stats.OutputCleanupWarnings++ } }
        try { $script:TxtWriter.Dispose() } catch { }
        $script:TxtWriter = $null
    }
    if ($null -ne $script:TxtStream) {
        try { $script:TxtStream.Dispose() } catch { if ($script:TxtCommitOk) { $script:Stats.OutputCleanupWarnings++ } }
        $script:TxtStream = $null
    }
    if ($null -ne $script:CsvWriter) {
        try { $script:CsvWriter.Close() } catch { if ($script:CsvCommitOk) { $script:Stats.OutputCleanupWarnings++ } }
        try { $script:CsvWriter.Dispose() } catch { }
        $script:CsvWriter = $null
    }
    if ($null -ne $script:CsvStream) {
        try { $script:CsvStream.Dispose() } catch { if ($script:CsvCommitOk) { $script:Stats.OutputCleanupWarnings++ } }
        $script:CsvStream = $null
    }
    if ($null -ne $script:PerfStream) {
        try { $script:PerfStream.Dispose() } catch { }
        $script:PerfStream = $null
    }
    $script:WritersOpen = $false
}

# ---------------------------------------------------------------------------
# Terminal status model with explicit precedence:
#   1. OUTPUT INCOMPLETE  (any output setup/write/flush/commit failure; exit 1)
#   2. Interrupted        (Ctrl+C / pipeline stop; exit non-zero)
#   3. EXECUTION FAILED   (phase/root/supplied-item or scan-plan failure)
#   4. COVERAGE INCOMPLETE(access/read/format/size/matcher coverage gap,
#                          regex/content coverage gap, accounting imbalance;
#                          exit 1)
#   5. Scan Complete      (all planned phases/roots terminal-completed, no
#                          content coverage gap, mandatory commits and any
#                          requested diagnostic commit; exit 0)
# ---------------------------------------------------------------------------
function Get-ExecutionStatus {
    if ($script:Interrupted) { return 'Interrupted' }
    # A cooperative limit is a graceful lifecycle completion with deliberately
    # partial coverage. Cancelled work remains visible in phase/root counters;
    # the stable limit marker below distinguishes it from a fully completed scan.
    if ($script:CooperativeLimitReached) { return 'Completed' }
    Sync-PhaseCounters
    Sync-RootCounters
    $phaseImbalance = ($script:Stats.PhasesPlanned -ne ($script:Stats.PhasesCompleted + $script:Stats.PhasesFailed + $script:Stats.PhasesCancelled))
    $rootImbalance = ($script:Stats.RootsPlanned -ne ($script:Stats.RootsCompleted + $script:Stats.RootsFailed + $script:Stats.RootsCancelled))
    if ($script:FatalOuterCatchCount -gt 0 -or $script:AssessmentPartitionMismatch -or
        ((-not $script:IsQuickMode) -and -not $script:FullScanPlanSafe) -or
        $script:Stats.PhasesFailed -gt 0 -or $script:Stats.PhasesCancelled -gt 0 -or
        $script:Stats.RootsFailed -gt 0 -or $script:Stats.RootsCancelled -gt 0 -or
        $phaseImbalance -or $rootImbalance) { return 'Failed' }
    return 'Completed'
}

function Get-CoverageStatus {
    Sync-PhaseCounters
    Sync-RootCounters
    [long]$gapTotal = $script:Stats.GapReadDecodeFailed + $script:Stats.GapToctouMissing +
        $script:Stats.GapRegexBudget + $script:Stats.GapRegexTimeout +
        $script:Stats.GapUnexpectedAssessment + $script:Stats.GapEnumOtherIo +
        $script:Stats.GapAdsFailed + $script:Stats.GapEarlyEof +
        $script:Stats.GapInventoryMismatch + $script:Stats.GapAccessDenied +
        $script:Stats.GapLargeFileSkipped + $script:Stats.GapLargeFileSampled +
        $script:Stats.GapUnsupportedFormat + $script:Stats.GapRunLimit
    if ($script:CoverageIncomplete -or $script:ContentCoverageIncomplete -or
        $gapTotal -gt 0) {
        return 'Partial'
    }
    return 'Complete'
}

function Get-TerminalStatus {
    if ($script:OutputFailed) { return 'OutputIncomplete' }
    $executionStatus = Get-ExecutionStatus
    if ($executionStatus -eq 'Interrupted') { return 'Interrupted' }
    if ($executionStatus -eq 'Failed') { return 'ExecutionFailed' }
    if ((Get-CoverageStatus) -ne 'Complete') { return 'CoverageIncomplete' }
    return 'Complete'
}

function Get-TerminalStatusTitle {
    param([Parameter(Mandatory=$true)][string]$Status)
    switch ($Status) {
        'OutputIncomplete'   { return ('  {0} - Scan Finished (OUTPUT INCOMPLETE)' -f $script:ToolName) }
        'Interrupted'        { return ('  {0} - Scan Interrupted' -f $script:ToolName) }
        'ExecutionFailed'    { return ('  {0} - Scan Finished (EXECUTION FAILED)' -f $script:ToolName) }
        'CoverageIncomplete' { return ('  {0} - Scan Finished (COVERAGE INCOMPLETE)' -f $script:ToolName) }
        default              { return ('  {0} - Scan Complete' -f $script:ToolName) }
    }
}

# ---------------------------------------------------------------------------
# Exactly-once finalization with two mandatory data-commit points and one
# optional performance-diagnostic commit.
# 1. Freeze counters. 2. Explicit CSV flush = CSV commit point. 3. CSV
# Close/Dispose (cleanup-only warnings once committed). 4. Select terminal
# status. 5. Exactly one TXT summary attempt + explicit TXT flush = TXT commit
# point. 6. TXT Close/Dispose with the same cleanup rule. 7. Green console
# success only after every required commit point succeeded. OutputCleanupWarnings is a
# finalization-time counter: the committed TXT snapshot can report only
# warnings known before its own commit; a later TXT cleanup warning is
# sanitized console-only telemetry.
# ---------------------------------------------------------------------------
function Complete-ScanOutputs {
    if ($script:SummaryAttempted) { return }
    $script:SummaryAttempted = $true
    $script:SummaryAttempts++

    # ---- 1. Freeze counters -------------------------------------------------
    # Exact until the bounded set saturates; afterwards this is a truthful
    # retained lower bound and the overflow counter discloses lost cardinality
    # precision without suppressing any finding.
    $script:Stats.FilesWithFindings = [long]$script:FilesWithFindings.Count
    $script:Stats.TotalFileAssessments = $script:Stats.QuickWinFilesAssessed + $script:Stats.FullScanAssessed
    $script:Stats.PreCountCandidates = $script:Stats.ContentCandidatesPreCounted + $script:Stats.MetadataArtifactCandidatesPreCounted
    $script:Stats.FullScanCompleted = $script:Stats.FullScanContentCompleted + $script:Stats.FullScanContentSampled + $script:Stats.FullScanArtifactsReported + $script:Stats.FullScanPolicySkipped
    $script:Stats.UnreadableSkipped = $script:Stats.AccessDeniedSkipped + $script:Stats.OtherUnreadableSkipped
    $assessmentAccounting = Get-AssessmentAccountingState
    $script:AssessmentPartitionMismatch = (-not [bool]$assessmentAccounting.Balanced)
    if ($script:AssessmentPartitionMismatch) {
        $script:CoverageIncomplete = $true
        $script:ContentCoverageIncomplete = $true
    }
    Sync-PhaseCounters
    Sync-RootCounters
    if (($script:Stats.PhasesPlanned -ne ($script:Stats.PhasesCompleted + $script:Stats.PhasesFailed + $script:Stats.PhasesCancelled)) -or
        ($script:Stats.RootsPlanned -ne ($script:Stats.RootsCompleted + $script:Stats.RootsFailed + $script:Stats.RootsCancelled))) {
        $script:CoverageIncomplete = $true
    }
    if ($script:PerfEnabled) {
        # Authoritative assessment cardinality includes terminal empty/artifact
        # decisions that intentionally bypass the content-assessment wrapper.
        $script:Perf.Assessed = [long]$script:Stats.TotalFileAssessments
    }

    # The optional diagnostic has its own explicit commit. A requested profile
    # that cannot be serialized or flushed is an output-integrity failure.
    if ($script:PerfEnabled) { [void](Write-PerformanceProfile) }

    # ---- 2. CSV explicit commit point ----------------------------------------
    if ($null -ne $script:CsvWriter) {
        $script:CsvCommitAttempts++
        try {
            if ($script:FaultSeam.Enabled -and $script:FaultSeam.OutputFailureAt -eq 'CsvFlush') {
                throw (New-Object System.IO.IOException ('injected CSV flush failure'))
            }
            $script:CsvWriter.Flush()
            if ($null -ne $script:CsvStream) { $script:CsvStream.Flush() }
            $script:CsvCommitOk = $true
        } catch {
            Register-OutputFailure -Detail $_.Exception.GetType().Name
        }
    }

    # ---- 3. CSV cleanup-only close -------------------------------------------
    if ($null -ne $script:CsvWriter) {
        try {
            if ($script:FaultSeam.Enabled -and $script:FaultSeam.OutputFailureAt -eq 'CsvClose') {
                throw (New-Object System.IO.IOException ('injected CSV close failure'))
            }
            $script:CsvWriter.Close()
        } catch { if ($script:CsvCommitOk) { $script:Stats.OutputCleanupWarnings++ } }
        try { $script:CsvWriter.Dispose() } catch { }
        $script:CsvWriter = $null
    }
    if ($null -ne $script:CsvStream) {
        try { $script:CsvStream.Dispose() } catch { if ($script:CsvCommitOk) { $script:Stats.OutputCleanupWarnings++ } }
        $script:CsvStream = $null
    }

    # ---- 4. Terminal status (from known output/coverage/interruption state) --
    $status = Get-TerminalStatus
    if ($status -ne 'Complete') { $script:ExitCode = 1 }

    # ---- 5. Exactly one TXT summary attempt + TXT explicit commit point ------
    $lines = Get-SummaryLines -Status $status
    $txtWriteOk = $false
    if ($script:WritersOpen) {
        try {
            $script:TxtWriter.Write("`r`n")
            foreach ($line in $lines) {
                $script:TxtWriter.Write($line)
                $script:TxtWriter.Write("`r`n")
            }
            $txtWriteOk = $true
        } catch {
            Register-OutputFailure -Detail $_.Exception.GetType().Name
            $status = 'OutputIncomplete'
            $script:ExitCode = 1
            $lines = Get-SummaryLines -Status $status
        }
        if ($txtWriteOk) {
            $script:TxtCommitAttempts++
            try {
                if ($script:FaultSeam.Enabled -and $script:FaultSeam.OutputFailureAt -eq 'TxtFlush') {
                    throw (New-Object System.IO.IOException ('injected TXT flush failure'))
                }
                $script:TxtWriter.Flush()
                if ($null -ne $script:TxtStream) { $script:TxtStream.Flush() }
                $script:TxtCommitOk = $true
            } catch {
                # The TXT is untrusted/partial and cannot be rewritten reliably;
                # the final red console OUTPUT INCOMPLETE status is authoritative.
                Register-OutputFailure -Detail $_.Exception.GetType().Name
                $status = 'OutputIncomplete'
                $script:ExitCode = 1
                $lines = Get-SummaryLines -Status $status
            }
        }
    } else {
        # No usable TXT writer: if an output set had been initialized this is
        # an output failure; otherwise this is pre-output usage (SelfTest).
        if ($script:OutputPairInitialized) {
            Register-OutputFailure -Detail 'TxtWriterUnavailable'
            $status = 'OutputIncomplete'
            $script:ExitCode = 1
            $lines = Get-SummaryLines -Status $status
        }
    }

    # ---- 6. TXT cleanup-only close --------------------------------------------
    $txtCleanupFailed = $false
    if ($null -ne $script:TxtWriter) {
        try {
            if ($script:FaultSeam.Enabled -and $script:FaultSeam.OutputFailureAt -eq 'TxtClose') {
                throw (New-Object System.IO.IOException ('injected TXT close failure'))
            }
            $script:TxtWriter.Close()
        } catch { $txtCleanupFailed = $true }
        try { $script:TxtWriter.Dispose() } catch { }
        $script:TxtWriter = $null
    }
    if ($null -ne $script:TxtStream) {
        try { $script:TxtStream.Dispose() } catch { if ($script:TxtCommitOk) { $txtCleanupFailed = $true } }
        $script:TxtStream = $null
    }
    if ($txtCleanupFailed -and $script:TxtCommitOk) { $script:Stats.OutputCleanupWarnings++ }
    $script:WritersOpen = $false

    # ---- 7. Console rendering from fresh post-commit state --------------------
    # Never reuse the pre-commit summary snapshot here. A TXT write/flush may
    # have changed the terminal state after that snapshot was built. Missing
    # commit points are themselves an output-integrity failure even if no
    # writer happened to throw.
    if (-not $script:CsvCommitOk -or -not $script:TxtCommitOk -or
        ($script:PerfEnabled -and -not $script:PerfCommitOk)) {
        if (-not $script:OutputFailed) {
            Register-OutputFailure -Detail 'OutputCommitMissing'
        }
    }
    $status = Get-TerminalStatus
    if ($status -ne 'Complete') { $script:ExitCode = 1 }
    $script:LastConsoleSummaryStatus = $status
    $lines = Get-SummaryLines -Status $status
    $summaryColor = [System.ConsoleColor]::Green
    if ($status -ne 'Complete') { $summaryColor = [System.ConsoleColor]::Red }
    foreach ($line in $lines) { Write-ColorLine -Text $line -Color $summaryColor }
    if ($script:Stats.OutputCleanupWarnings -gt 0) {
        Write-ColorLine -Text ('[!] Output cleanup warnings: {0} (committed result data is unaffected)' -f $script:Stats.OutputCleanupWarnings) -Color Yellow
    }
}

# ---------------------------------------------------------------------------
# Final summary block. Four truthful terminal statuses with explicit precedence
# (Get-TerminalStatus). The legacy two-state helper remains for compatibility
# with the existing tests; the production path uses the four-state selector.
# Write-Summary delegates to Complete-ScanOutputs, which performs the exactly
# once summary attempt and every required output data-commit point.
# ---------------------------------------------------------------------------
function Get-SummaryStatusTitle {
    param([Parameter(Mandatory=$true)][bool]$Failed)
    if ($Failed) { return ('  {0} - Scan Finished (OUTPUT INCOMPLETE)' -f $script:ToolName) }
    return ('  {0} - Scan Complete' -f $script:ToolName)
}

function Get-SummaryLines {
    param([Parameter(Mandatory=$true)][string]$Status)
    $elapsed = $script:SwTotal.Elapsed
    $duration = '{0:00}:{1:00}:{2:00}' -f [int][Math]::Floor($elapsed.TotalHours), $elapsed.Minutes, $elapsed.Seconds
    $elevatedText = if ($script:IsElevated) { 'Yes' } else { 'No' }
    $revealText = if ($script:RevealActive) { 'Yes' } else { 'No' }

    $outputText = 'OK'
    if ($Status -eq 'OutputIncomplete' -or $script:OutputFailed) {
        $outputText = 'FAILED - result files are incomplete/untrusted'
    }
    $executionText = Get-ExecutionStatus
    $coverageText = Get-CoverageStatus
    $contentText = if ($script:ContentCoverageIncomplete) { 'INCOMPLETE - one or more content/ADS/matcher assessments were partial or failed' } else { 'Complete' }
    $interruptText = if ($script:Interrupted) { 'INTERRUPTED' } else { 'No' }

    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('=' * 60)
    $lines.Add((Get-TerminalStatusTitle -Status $Status))
    $lines.Add('  Machine            : {0}' -f $env:COMPUTERNAME)
    $lines.Add('  Date/Time           : {0}' -f (Get-Date).ToString('yyyy-MM-dd HH:mm:ss'))
    $lines.Add('  Tool version        : {0}' -f $script:ToolVersion)
    $lines.Add('LinePrefilter={0}' -f $script:LinePrefilterName)
    $lines.Add('LinePrefilterFallbackEvents={0}' -f $script:LinePrefilterFallbackEvents)
    $lines.Add('  Mode                : {0}' -f $Mode)
    $lines.Add('  Elevated            : {0}' -f $elevatedText)
    $lines.Add('  Secrets revealed    : {0}' -f $revealText)
    $lines.Add('  Output status       : {0}' -f $outputText)
    $lines.Add('  Execution status    : {0}' -f $executionText)
    $lines.Add('  Coverage status     : {0}' -f $coverageText)
    $lines.Add('  Content coverage    : {0}' -f $contentText)
    $lines.Add('  Interruption status : {0}' -f $interruptText)
    $lines.Add('  Limit reason        : {0}' -f $script:LimitReason)
    $lines.Add('  Output cleanup warns: {0}' -f $script:Stats.OutputCleanupWarnings)
    $lines.Add('  Duration            : {0}' -f $duration)
    $lines.Add(('  Large-file mode     : {0} (budget {1} MB per file)' -f $script:LargeFileModeActive, $MaxFileSizeMB))
    $lines.Add('  ' + ('-' * 58))
    $lines.Add('  Roots scanned       : {0}' -f $script:Stats.RootsScanned)
    $lines.Add('  Candidates scanned  : {0}' -f $script:Stats.CandidatesScanned)
    $lines.Add('  ADS scanned         : {0}' -f $script:Stats.AdsScanned)
    if ($script:FindingFileSetSaturated) {
        $lines.Add(('  Files with findings : >= {0} (tracking set saturated; overflow attempts {1})' -f $script:Stats.FilesWithFindings, $script:Stats.FindingFileSetOverflowEvents))
    } else {
        $lines.Add('  Files with findings : {0}' -f $script:Stats.FilesWithFindings)
    }
    $lines.Add('  Content matches     : {0}' -f $script:Stats.ContentMatches)
    $lines.Add('  Artifact findings   : {0}' -f $script:Stats.ArtifactFindings)
    $lines.Add('  Registry findings   : {0}' -f $script:Stats.RegistryFindings)
    $lines.Add(('  Registry opens      : {0} attempts / {1} handles opened' -f $script:Stats.RegistryOpenAttempts, $script:Stats.RegistryHandlesOpened))
    $lines.Add(('  Registry closes     : {0} attempts / {1} handles closed' -f $script:Stats.RegistryCloseAttempts, $script:Stats.RegistryHandlesClosed))
    $lines.Add('  Registry reads      : {0}' -f $script:Stats.RegistryReadAttempts)
    $lines.Add(('  Registry enumerates : values {0} / subkeys {1}' -f $script:Stats.RegistryValueEnumAttempts, $script:Stats.RegistrySubKeyEnumAttempts))
    $lines.Add('  Registry denied     : {0} (coverage gaps; siblings continue)' -f $script:Stats.RegistryDeniedOperations)
    $lines.Add('  Registry errors     : {0} (coverage gaps)' -f $script:Stats.RegistryErrorOperations)
    $lines.Add('  Environment findings: {0}' -f $script:Stats.EnvironmentFindings)
    $lines.Add('  Total findings      : {0}' -f $script:Stats.TotalFindings)
    $lines.Add('  Placeholder refs    : {0}' -f $script:Stats.PlaceholderRefs)
    $lines.Add('  Access denied skips : {0}' -f $script:Stats.AccessDeniedSkipped)
    $lines.Add('  Item/provider other : {0} (non-assessment failures only)' -f $script:Stats.OtherUnreadableSkipped)
    $lines.Add('  Unreadable skipped  : {0} (= access denied + other unreadable)' -f $script:Stats.UnreadableSkipped)
    $lines.Add('  Long paths skipped  : {0}' -f $script:Stats.LongPathsSkipped)
    $lines.Add('  Reparse skipped     : {0}' -f $script:Stats.ReparseItemsSkipped)
    $lines.Add('  Oversize skipped    : {0}' -f $script:Stats.OversizeSkipped)
    $lines.Add('  Large sample attempts: {0}' -f $script:Stats.LargeFilesSampled)
    $lines.Add('  Large full attempts : {0}' -f $script:Stats.LargeFilesFullScanned)
    $lines.Add('  Eligible bytes      : {0:N0} (assessment-attempt carrier bytes)' -f $script:Stats.ContentBytesEligible)
    $lines.Add('  Examined bytes      : {0:N0} (logical read attempts; retries may repeat)' -f $script:Stats.ContentBytesExamined)
    $lines.Add('  Sampled bytes       : {0:N0} (logical sampled windows)' -f $script:Stats.SampledBytesExamined)
    $lines.Add('  Binary skipped      : {0}' -f $script:Stats.BinarySkipped)
    $lines.Add('  Unsupported formats: {0}' -f $script:Stats.UnsupportedFormatsSkipped)
    $lines.Add('  Cooperative limits : {0}' -f $script:Stats.GapRunLimit)
    $lines.Add('  Local volumes in scope: {0} (fixed/removable unique IDs)' -f $script:Stats.VolumesDiscovered)
    $lines.Add('  Folder mounts planned: {0}' -f $script:Stats.VolumeMountRootsPlanned)
    $lines.Add('  Volumes unavailable : {0}' -f $script:Stats.VolumesUnavailable)
    $lines.Add('  Volume discovery err: {0}' -f $script:Stats.VolumeDiscoveryFailures)
    $lines.Add('  Regex timeout events: {0}' -f $script:Stats.RegexTimeoutEvents)
    $lines.Add('  Gap: read/decode    : {0}' -f $script:Stats.GapReadDecodeFailed)
    $lines.Add('    Open sharing      : {0}' -f $script:Stats.AssessmentOpenSharingViolation)
    $lines.Add('    Open other I/O    : {0}' -f $script:Stats.AssessmentOpenOtherIo)
    $lines.Add('    Read I/O          : {0}' -f $script:Stats.AssessmentReadIo)
    $lines.Add('    Decode invalid    : {0}' -f $script:Stats.AssessmentDecodeInvalid)
    $lines.Add('    Missing           : {0}' -f $script:Stats.AssessmentMissing)
    $lines.Add('    Early EOF         : {0}' -f $script:Stats.AssessmentEarlyEof)
    $lines.Add('    Access denied     : {0}' -f $script:Stats.AssessmentAccessDenied)
    $lines.Add('    Regex budget      : {0}' -f $script:Stats.AssessmentRegexBudget)
    $lines.Add('    Unexpected        : {0}' -f $script:Stats.AssessmentUnexpected)
    $lines.Add('    Sharing recovered : {0} (permissive local fallback; finding coverage conservatively Sampled)' -f $script:Stats.AssessmentSharingFallbackUsed)
    foreach ($failureSignature in @($script:AssessmentFailureSignatures.Keys | Sort-Object)) {
        $lines.Add(('    Failure signature : {0} = {1}' -f $failureSignature, $script:AssessmentFailureSignatures[$failureSignature]))
    }
    if ($script:Stats.AssessmentFailureSignatureOverflow -gt 0) {
        $lines.Add('    Signature overflow: {0}' -f $script:Stats.AssessmentFailureSignatureOverflow)
    }
    $lines.Add('  Gap: TOCTOU missing : {0}' -f $script:Stats.GapToctouMissing)
    $lines.Add('  Gap: regex budget   : {0}' -f $script:Stats.GapRegexBudget)
    $lines.Add('  Gap: regex timeout  : {0}' -f $script:Stats.GapRegexTimeout)
    $lines.Add('  Gap: unexpected     : {0}' -f $script:Stats.GapUnexpectedAssessment)
    $lines.Add('  Gap: enum other/IO  : {0}' -f $script:Stats.GapEnumOtherIo)
    $lines.Add('  Gap: ADS enum/read  : {0}' -f $script:Stats.GapAdsFailed)
    $lines.Add('  Gap: early EOF      : {0}' -f $script:Stats.GapEarlyEof)
    $lines.Add('  Gap: inventory race : {0}' -f $script:Stats.GapInventoryMismatch)
    $lines.Add('  Gap: access denied  : {0}' -f $script:Stats.GapAccessDenied)
    $lines.Add('  Gap: large skipped  : {0}' -f $script:Stats.GapLargeFileSkipped)
    $lines.Add('  Gap: large sampled  : {0}' -f $script:Stats.GapLargeFileSampled)
    $lines.Add('  Gap: unsupported fmt: {0}' -f $script:Stats.GapUnsupportedFormat)
    if ($script:AdsUnsupported) {
        $lines.Add('  ADS note            : unsupported scope(s) skipped: {0}' -f (ConvertTo-SafeText -Text ($script:AdsUnsupportedScopes -join '; ')))
    }
    $lines.Add('  Access policy       : AccessDenied never stops siblings, but always makes Coverage status Partial')
    if ($script:ErrorDedupSaturated) {
        $dedupSatLine = '  Error dedup         : SATURATED at {0} keys; later failures counted as attempts (overflow events: {1})' -f $script:ErrorDedupCap, $script:Stats.ErrorDedupOverflowEvents
        $lines.Add($dedupSatLine)
    } else {
        $lines.Add('  Error dedup overflow: {0}' -f $script:Stats.ErrorDedupOverflowEvents)
    }
    if ($script:FindingDedupeSaturated) {
        $lines.Add(('  Finding dedup       : SATURATED with cap {0}; exact peak {1}; later new findings emitted without global retention (overflow events: {2})' -f $script:FindingDedupeCap, $script:Stats.FindingDedupePeakKeys, $script:Stats.FindingDedupeOverflowEvents))
    } else {
        $lines.Add('  Finding dedup overflow: {0}' -f $script:Stats.FindingDedupeOverflowEvents)
    }
    $lines.Add('  Finding dedup peak  : {0} exact SHA-256 keys retained' -f $script:Stats.FindingDedupePeakKeys)
    $lines.Add('  Finding duplicates : {0} suppressed' -f $script:Stats.FindingDuplicatesSuppressed)
    $lines.Add('  ' + ('-' * 58))
    $lines.Add('  Phases planned      : {0}' -f $script:Stats.PhasesPlanned)
    $lines.Add('  Phases completed    : {0}' -f $script:Stats.PhasesCompleted)
    $lines.Add('  Phases failed       : {0}' -f $script:Stats.PhasesFailed)
    $lines.Add('  Phases cancelled    : {0}' -f $script:Stats.PhasesCancelled)
    $lines.Add('  Roots planned       : {0}' -f $script:Stats.RootsPlanned)
    $lines.Add('  Roots completed     : {0}' -f $script:Stats.RootsCompleted)
    $lines.Add('  Roots failed        : {0}' -f $script:Stats.RootsFailed)
    $lines.Add('  Roots cancelled     : {0}' -f $script:Stats.RootsCancelled)
    $lines.Add('  ' + ('-' * 58))
    $lines.Add('  QuickWin invitations: {0}' -f $script:Stats.QuickWinInvitations)
    $qwInvLine = '  QuickWin invocations: {0} (content {1} + sampled {2} + artifact {3} + policy {4} + retryable {5} + unexpected {6} + cancelled {7})' -f $script:Stats.QuickWinFilesAssessed, $script:Stats.QuickWinContentCompleted, $script:Stats.QuickWinContentSampled, $script:Stats.QuickWinArtifactsReported, $script:Stats.QuickWinPolicySkipped, $script:Stats.QuickWinRetryableFailed, $script:Stats.QuickWinUnexpectedFailed, $script:Stats.QuickWinCancelledInFlight
    $lines.Add($qwInvLine)
    $preLine = '  Pre-count candidates: {0} (content {1} + metadata artifact {2})' -f $script:Stats.PreCountCandidates, $script:Stats.ContentCandidatesPreCounted, $script:Stats.MetadataArtifactCandidatesPreCounted
    $lines.Add($preLine)
    $fsInvLine = '  FullScan invocations: {0} (content {1} + sampled {2} + artifact {3} + policy {4} + read-failed {5} + unexpected {6} + cancelled {7})' -f $script:Stats.FullScanAssessed, $script:Stats.FullScanContentCompleted, $script:Stats.FullScanContentSampled, $script:Stats.FullScanArtifactsReported, $script:Stats.FullScanPolicySkipped, $script:Stats.FullScanReadFailed, $script:Stats.FullScanUnexpectedFailed, $script:Stats.FullScanCancelledInFlight
    $lines.Add($fsInvLine)
    $lines.Add('  FullScan handled    : {0} (content+sampled+artifact+policy terminal outcomes)' -f $script:Stats.FullScanCompleted)
    $lines.Add('  Total invocations   : {0} (attempts, not confirmed scans)' -f $script:Stats.TotalFileAssessments)
    if ($script:PreCountAssessedMismatch) {
        $lines.Add('  Coverage note       : pre-count vs assessed mismatch (filesystem changed during scan)')
    }
    $lines.Add('  ' + ('-' * 58))
    $lines.Add('  Canonical roots     : {0}' -f (ConvertTo-SafeText -Text $script:CanonicalRootsText))
    $lines.Add('  Active exclusions   :')
    foreach ($exPrefix in $script:ExcludedPrefixes) {
        $lines.Add('    - {0}' -f (ConvertTo-SafeText -Text $exPrefix))
    }
    if ($script:UserExclusionList.Count -gt 0) {
        $lines.Add('  Operator ExcludePath: {0}' -f (ConvertTo-SafeText -Text ($script:UserExclusionList -join '; ')))
    }
    if ($script:IsDeepMode) {
        $lines.Add('  Deep exclusions note: performance-only cache exclusions disabled; .git\objects remains an explicitly unsupported Git object database.')
    }
    $lines.Add('  ' + ('-' * 58))
    $lines.Add('  TXT output          : {0}' -f (ConvertTo-SafeText -Text $script:TxtPath))
    $lines.Add('  CSV output          : {0}' -f (ConvertTo-SafeText -Text $script:CsvPath))
    if ($script:PerfEnabled) {
        $lines.Add('  Performance profile: {0}' -f (ConvertTo-SafeText -Text $script:PerfPath))
    }
    $lines.Add('=' * 60)
    return $lines
}

function Write-Summary {
    # Exactly one summary attempt per initialized output set; delegates to the
    # finalization sequence (guard inside makes repeated calls no-ops).
    Complete-ScanOutputs
}

# ---------------------------------------------------------------------------
# SelfTest helpers.
# ---------------------------------------------------------------------------
function Get-SelfTestPlanIds {
    # Explicit versioned manifest. Its cardinality is derived from unique IDs,
    # not from a magic numeric constant or fragile source-text counting. T152
    # intentionally consists of the distinct T152a/T152b cases.
    $candidates = New-Object 'System.Collections.Generic.List[string]'
    for ($testNumber = 1; $testNumber -le 150; $testNumber++) {
        $candidates.Add(('T{0}' -f $testNumber))
    }
    $candidates.Add('T150b')
    $candidates.Add('T151')
    $candidates.Add('T152a')
    $candidates.Add('T152b')
    $candidates.Add('T153')
    $candidates.Add('T153b')
    for ($testNumber = 154; $testNumber -le 226; $testNumber++) {
        $candidates.Add(('T{0}' -f $testNumber))
    }

    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $plan = New-Object 'System.Collections.Generic.List[string]'
    foreach ($testId in $candidates) {
        if (-not $seen.Add($testId)) {
            throw (New-Object System.InvalidOperationException ('duplicate SelfTest plan identifier'))
        }
        $plan.Add($testId)
    }

    $result = New-Object 'string[]' $plan.Count
    $plan.CopyTo($result)
    return $result
}

function Register-SelfTestAbort {
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Reason)
    if ($script:SelfTestAborted) { return }
    if ([string]::IsNullOrEmpty($Reason)) { $Reason = 'UnknownSelfTestError' }
    $script:SelfTestAborted = $true
    $script:SelfTestAbortReason = $Reason
    $script:SelfTestUnhandledErrors++
    # An aborted/incomplete suite is itself a release-blocking failure, but it
    # is not counted as an executed test outcome.
    $script:SelfTestFailures++
    Write-Host ('FAIL: SelfTest aborted or incomplete ({0})' -f $Reason)
}

function Write-SelfTestResultSummary {
    if ($script:SelfTestSummaryPrinted) { return }
    $script:SelfTestSummaryPrinted = $true
    if (-not $script:SelfTestReachedEnd) {
        Register-SelfTestAbort -Reason 'CompletionSentinelNotReached'
    }
    if ($script:SelfTestExecuted -ne $script:SelfTestPlanned) {
        Register-SelfTestAbort -Reason 'PlannedExecutedOutcomeMismatch'
    }
    Write-Host ('=' * 60)
    Write-Host ('SelfTest summary: {0} passed, {1} failed, {2} skipped' -f `
        $script:SelfTestPasses, $script:SelfTestFailures, $script:SelfTestSkips)
    Write-Host ('SelfTest coverage: {0} planned, {1} executed, reached end: {2}, aborted: {3}, unhandled errors: {4}' -f `
        $script:SelfTestPlanned, $script:SelfTestExecuted, `
        $(if ($script:SelfTestReachedEnd) { 'Yes' } else { 'No' }), `
        $(if ($script:SelfTestAborted) { 'Yes' } else { 'No' }), $script:SelfTestUnhandledErrors)
    if ($script:SelfTestAborted) {
        Write-Host ('SelfTest abort reason: {0}' -f $script:SelfTestAbortReason)
    }
}

function Assert-SelfTest {
    param(
        [Parameter(Mandatory=$true)][string]$Name,
        [Parameter(Mandatory=$true)][bool]$Condition
    )
    $script:SelfTestExecuted++
    if ($script:SelfTestPlanned -gt 0 -and $script:SelfTestExecuted -gt $script:SelfTestPlanned) {
        Register-SelfTestAbort -Reason 'ExecutedOutcomeCountExceededPlan'
    }
    if ($Condition) {
        $script:SelfTestPasses++
        Write-Host ('PASS: {0}' -f $Name)
    } else {
        $script:SelfTestFailures++
        Write-Host ('FAIL: {0}' -f $Name)
    }
}

function Skip-SelfTest {
    param([Parameter(Mandatory=$true)][string]$Name)
    $script:SelfTestExecuted++
    if ($script:SelfTestPlanned -gt 0 -and $script:SelfTestExecuted -gt $script:SelfTestPlanned) {
        Register-SelfTestAbort -Reason 'ExecutedOutcomeCountExceededPlan'
    }
    $script:SelfTestSkips++
    Write-Host ('SKIP: {0}' -f $Name)
}

function Reset-SelfTestCapture {
    $script:CapturedFindings.Clear()
    $script:CaptureCountOnly = $false
    $script:CapturedFindingCount = [long]0
    $script:CapturedFindingFirstKey = ''
    $script:CapturedFindingLastKey = ''
    $script:DedupeKeys.Clear()
    $script:FilesWithFindings.Clear()
    $script:FindingDedupeSaturated = $false
    $script:FindingFileSetSaturated = $false
    $script:FindingFileSetCap = 100000
    $script:QuickWinAttemptedPaths.Clear()
    $script:TerminalAssessedPaths.Clear()
    $script:AdsHandledPaths.Clear()
    $script:PgpassGrammarPaths.Clear()
    $script:NpmrcGrammarPaths.Clear()
    Reset-RegexUnitBudgetState
    $script:RxFileTimeoutEvents = 0
    $script:RxFileElapsedMs = [long]0
    $script:RxFileElapsedTicks = [long]0
    $script:RxFileBudgetExhausted = $false
    $script:RxFileGapRecorded = $false
    $script:ContentCoverageIncomplete = $false
}

# Zeroes every operational counter and run-state flag so accounting invariants
# can be asserted per test. SelfTest-only helper.
function Reset-StCounters {
    foreach ($k in @($script:Stats.Keys)) { $script:Stats[$k] = [long]0 }
    $script:SummaryAttempts = 0
    $script:CsvCommitAttempts = 0
    $script:TxtCommitAttempts = 0
    $script:FatalOuterCatchCount = 0
    $script:LastConsoleSummaryStatus = ''
    $script:SummaryAttempted = $false
    $script:CsvCommitOk = $false
    $script:TxtCommitOk = $false
    $script:CoverageIncomplete = $false
    $script:ContentCoverageIncomplete = $false
    $script:InventoryChanged = $false
    $script:ErrorDedupSaturated = $false
    $script:ErrorDedupSet.Clear()
    $script:AssessmentFailureSignatures.Clear()
    $script:SharingFallbackRootCache.Clear()
    $script:LastAssessmentPrimaryCause = ''
    $script:LastAssessmentFailureType = ''
    $script:LastAssessmentFailureHResult = [int]0
    $script:ErrorDedupCap = 50000
    $script:Interrupted = $false
    $script:FullScanPlanSafe = $true
    $script:PreCountAssessedMismatch = $false
    $script:AssessmentPartitionMismatch = $false
    $script:LastTraversalRootFailed = $false
    $script:PhaseStates.Clear()
    $script:RootStates.Clear()
    $script:VolumeRootIds.Clear()
    $script:VolumeMountRoots.Clear()
    $script:UnavailableVolumeLabels.Clear()
}

# Prepares and runs the REAL protected lifecycle with real output files under
# the disposable fixture root. Every phase-plan/root-plan combination is built
# exactly as in production. Returns the Initialize-OutputFiles result.
function Invoke-StLifecycle {
    param(
        [bool]$FullScan,
        [string[]]$Roots,
        [string[]]$Files
    )
    Reset-StCounters
    Reset-SelfTestCapture
    $script:CaptureMode = $false
    $script:PhaseStates.Clear()
    $script:RootStates.Clear()
    $script:WritersOpen = $false
    $script:OutputFailed = $false
    $script:OutputFailureDetail = ''
    $script:OutputErrorReported = $false
    $script:SummaryAttempted = $false
    $script:CsvCommitOk = $false
    $script:TxtCommitOk = $false
    $script:OutputDataWritten = $false
    $script:OutputPairInitialized = $false
    $script:ExitCode = 0
    $script:IsQuickMode = (-not $FullScan)
    $script:Mode = $(if ($FullScan) { 'Standard' } else { 'Quick' })
    $script:OutputDirectory = $script:StOutDir
    Add-PhaseState -Name 'QuickWins'
    Add-PhaseState -Name 'Environment'
    Add-PhaseState -Name 'Registry'
    if ($FullScan) { Add-PhaseState -Name 'FullScan' }
    foreach ($r in $Roots) { Add-RootState -Name $r -Kind 'Root' -State 'Pending' }
    foreach ($f in $Files) { Add-RootState -Name $f -Kind 'File' -State 'Pending' }
    $plan = @{ Roots = $Roots; Files = $Files; Rejected = @() }
    # Lifecycle SelfTests must be deterministic and must not depend on the
    # caller's real registry ACLs/content. An explicitly supplied fake tree is
    # preserved; otherwise the real adapter runs against an empty fake tree.
    $insertedEmptyFakeRegistry = ($null -eq $script:FaultSeam.FakeRegistry)
    if ($insertedEmptyFakeRegistry) { $script:FaultSeam.FakeRegistry = @{} }
    try {
        if (-not (Initialize-OutputFiles)) { return $false }
        Invoke-ProtectedLifecycle -ScanPlan $plan
        return $true
    } finally {
        if ($insertedEmptyFakeRegistry) { $script:FaultSeam.FakeRegistry = $null }
    }
}

# Restores every seam field to real production behavior and re-enables the
# seam for the next injected test. Called in finally after injected tests.
function Reset-StSeam {
    Reset-FaultSeam
    $script:FaultSeam.Enabled = $true
}

function New-StHashSet {
    param([string[]]$Items)
    $set = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($i in $Items) { [void]$set.Add($i) }
    return $set
}

# Creates a disposable fixture file under $env:TEMP for SelfTest use only.
function Write-StFixtureFile {
    param(
        [Parameter(Mandatory=$true)][string]$Path,
        [Parameter(Mandatory=$true)][AllowEmptyString()][string]$Content
    )
    $parent = [System.IO.Path]::GetDirectoryName($Path)
    if (-not [System.IO.Directory]::Exists($parent)) {
        [void][System.IO.Directory]::CreateDirectory($parent)
    }
    [System.IO.File]::WriteAllText($Path, $Content, (New-Object System.Text.UTF8Encoding ($false)))
}

function Test-CapturedValue {
    param([Parameter(Mandatory=$true)][string]$Value)
    foreach ($c in $script:CapturedFindings) {
        if ($c.RawValue -eq $Value) { return $true }
    }
    return $false
}

# Returns $true when the given raw secret appears anywhere it must be
# redacted: DisplayValue, Context or Notes of any captured finding.
function Test-CapturedLeak {
    param([Parameter(Mandatory=$true)][string]$Secret)
    $secretForms = @($Secret, (ConvertTo-SafeText -Text $Secret))
    $outputFields = @('DisplayValue','Context','Notes','DisplaySource','RegistryPath','ValueName','FindingKind','App','SourceKind',
                      'Account','Endpoint','Port','PhysicalPath','LogicalPath','ContainerEntry','KeyPath',
                      'DecodeChain','ConfidenceEvidence')
    foreach ($c in $script:CapturedFindings) {
        foreach ($fieldName in $outputFields) {
            $fieldValue = $null
            if ($c -is [System.Collections.IDictionary]) {
                if ($c.Contains($fieldName)) { $fieldValue = $c[$fieldName] }
            } else {
                $property = $c.PSObject.Properties[$fieldName]
                if ($null -ne $property) { $fieldValue = $property.Value }
            }
            foreach ($secretForm in $secretForms) {
                if (-not [string]::IsNullOrEmpty([string]$secretForm) -and
                    [string]$fieldValue -match [regex]::Escape([string]$secretForm)) { return $true }
            }
        }
    }
    return $false
}

# Parses one RFC-4180-style record emitted by ConvertTo-CsvField. SelfTest-only
# helper: rows are already split at CRLF because ConvertTo-SafeText prevents
# embedded control characters in serialized finding fields.
function ConvertFrom-StCsvRecord {
    param([Parameter(Mandatory=$true)][AllowEmptyString()][string]$Line)

    $parsed = @{ Valid = $false; Fields = @() }
    $fields = New-Object 'System.Collections.Generic.List[string]'
    $field = New-Object System.Text.StringBuilder
    $inQuotes = $false
    $justClosedQuote = $false
    $i = 0
    while ($i -lt $Line.Length) {
        $ch = $Line[$i]
        if ($inQuotes) {
            if ($ch -eq '"') {
                if (($i + 1) -lt $Line.Length -and $Line[$i + 1] -eq '"') {
                    [void]$field.Append('"')
                    $i += 2
                    continue
                }
                $inQuotes = $false
                $justClosedQuote = $true
                $i++
                continue
            }
            [void]$field.Append($ch)
            $i++
            continue
        }
        if ($justClosedQuote) {
            if ($ch -ne ',') { return $parsed }
            $fields.Add($field.ToString())
            [void]$field.Clear()
            $justClosedQuote = $false
            $i++
            continue
        }
        if ($ch -eq ',') {
            $fields.Add($field.ToString())
            [void]$field.Clear()
            $i++
            continue
        }
        if ($ch -eq '"') {
            if ($field.Length -ne 0) { return $parsed }
            $inQuotes = $true
            $i++
            continue
        }
        [void]$field.Append($ch)
        $i++
    }
    if ($inQuotes) { return $parsed }
    $fields.Add($field.ToString())
    $parsed.Valid = $true
    $parsed.Fields = $fields.ToArray()
    return $parsed
}

# ---------------------------------------------------------------------------
# SelfTest: deterministic, offline tests of the production functions using
# disposable, path-restricted fixtures and result files under TEMP. It never
# performs an unrestricted drive scan and removes its fixtures in finally.
# Returns 0 when every test passes, 2 otherwise.
# ---------------------------------------------------------------------------
function Invoke-SelfTest {
    $script:CaptureMode = $true
    $script:RevealActive = $false
    $script:DecodeGppActive = $false
    $script:SelfTestPasses = 0
    $script:SelfTestFailures = 0
    $script:SelfTestSkips = 0
    $script:SelfTestPlanIds = @(Get-SelfTestPlanIds)
    $script:SelfTestPlanned = $script:SelfTestPlanIds.Count
    $script:SelfTestExecuted = 0
    $script:SelfTestAborted = $false
    $script:SelfTestReachedEnd = $false
    $script:SelfTestUnhandledErrors = 0
    $script:SelfTestAbortReason = ''
    $script:SelfTestSummaryPrinted = $false
    $script:OutputFailed = $false
    $script:OutputFailureDetail = ''
    $script:OutputErrorReported = $false
    $script:WritersOpen = $false
    $script:ExitCode = 0
    $script:NoProgressActive = $true
    $script:CoverageIncomplete = $false
    $script:ContentCoverageIncomplete = $false
    $script:Interrupted = $false
    $script:LastTraversalRootFailed = $false
    $script:PreCountAssessedMismatch = $false
    $script:SummaryAttempted = $false
    $script:CsvCommitOk = $false
    $script:TxtCommitOk = $false
    $script:OutputDataWritten = $false
    $script:OutputPairInitialized = $false
    $script:ErrorDedupSaturated = $false
    $script:ErrorDedupSet.Clear()
    $script:PhaseStates.Clear()
    $script:RootStates.Clear()
    Reset-FaultSeam
    $script:FaultSeam.Enabled = $true
    Reset-SelfTestCapture

    Write-Host ('{0} SelfTest (local disposable fixtures; may read limited host metadata/capabilities)' -f $script:ToolName)
    Write-Host ('=' * 60)

    $testFile = 'C:\selftest\case.config'

    # T1: quoted password containing spaces.
    Reset-SelfTestCapture
    [void](Add-TextFindings -Text 'password = "My S3cret Pass Phrase!"' -BaseLine 1 -Source $testFile -FilePath $testFile)
    Assert-SelfTest -Name 'Quoted password containing spaces' -Condition ($script:CapturedFindings.Count -eq 1 -and (Test-CapturedValue -Value 'My S3cret Pass Phrase!'))

    # T2: JSON client_secret.
    Reset-SelfTestCapture
    [void](Add-TextFindings -Text '{"client_secret": "abc123XYZ-sEcR3t-value"}' -BaseLine 1 -Source $testFile -FilePath $testFile)
    Assert-SelfTest -Name 'JSON client_secret' -Condition ($script:CapturedFindings.Count -eq 1 -and (Test-CapturedValue -Value 'abc123XYZ-sEcR3t-value'))

    # T3: AWS access key ID and secret assignment.
    Reset-SelfTestCapture
    [void](Add-TextFindings -Text 'aws_access_key_id = AKIAIOSFODNN7EXAMPLE' -BaseLine 1 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'aws_secret_access_key = wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY' -BaseLine 2 -Source $testFile -FilePath $testFile)
    $awsRolling3 = New-RollingWindowState
    [void](Add-RollingWindowLine -State $awsRolling3 -Line 'aws_access_key_id = AKIAIOSFODNN7EXAMPLE')
    # Once the assignment is no longer the terminal line, the line-oriented
    # KV_CLOUD grammar does not replay it but AWS_KEY_ID still does.  This is
    # the exact Deep rolling-window path that must collide with the richer
    # finding emitted by the preceding ordinary line scan.
    $awsWindow3 = Add-RollingWindowLine -State $awsRolling3 -Line 'profile = synthetic'
    [void](Add-TextFindings -Text $awsWindow3 -BaseLine $awsRolling3.StartLine -Source $testFile -FilePath $testFile)
    $t3 = ($script:CapturedFindings.Count -eq 2 -and (Test-CapturedValue -Value 'AKIAIOSFODNN7EXAMPLE') -and (Test-CapturedValue -Value 'wJalrXUtnFEMI/K7MDENG/bPxRfiCYEXAMPLEKEY'))
    foreach ($awsExample3 in $script:CapturedFindings) {
        if ($awsExample3.PatternId -ne 'KV_CLOUD' -or $awsExample3.App -ne 'AWS' -or
