    Assert-SelfTest -Name 'Focus span redacted when ContextSpans is empty' -Condition $t34

    # T35: decoded short password (dDphYmM= is Base64 for t:abc) exposes
    # neither the encoded representation nor the decoded value.
    Reset-SelfTestCapture
    [void](Add-TextFindings -Text '  "auth": "dDphYmM="' -BaseLine 1 -Source $testFile -FilePath $testFile)
    $t35 = ($script:CapturedFindings.Count -eq 1)
    foreach ($c in $script:CapturedFindings) {
        if ($c.PatternId -ne 'DOCKER_AUTH') { $t35 = $false }
        if ($c.Context -ne '[context-redacted:short-secret]') { $t35 = $false }
    }
    if (Test-CapturedLeak -Secret 'dDphYmM=') { $t35 = $false }
    if (Test-CapturedLeak -Secret 'abc') { $t35 = $false }
    Assert-SelfTest -Name 'Decoded short password: encoded and decoded both hidden' -Condition $t35

    # T36: dedicated key-vocabulary patterns detect short/symbol values directly.
    Reset-SelfTestCapture
    [void](Add-TextFindings -Text 'pass=S3c!' -BaseLine 1 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'api-key: Api!Key99' -BaseLine 2 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'client-secret=Cli!Sec77' -BaseLine 3 -Source $testFile -FilePath $testFile)
    $dedicatedLong36 = 'CHQA_DedicatedValue_ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789Z9!'
    [void](Add-TextFindings -Text ('db-password="' + $dedicatedLong36 + '"') -BaseLine 4 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'access-token=Tok!123' -BaseLine 5 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'credentials=Cred!55' -BaseLine 6 -Source $testFile -FilePath $testFile)
    $expectedKeys = @('S3c!','Api!Key99','Cli!Sec77',$dedicatedLong36,'Tok!123','Cred!55')
    $t36 = ($script:CapturedFindings.Count -eq 6)
    foreach ($ek in $expectedKeys) {
        $foundDedicated = $false
        foreach ($c in $script:CapturedFindings) {
            if ($c.RawValue -eq $ek -and $c.PatternId -ne 'GENERIC_CONTEXT') { $foundDedicated = $true }
        }
        if (-not $foundDedicated) { $t36 = $false }
    }
    if ($t36) {
        # A dedicated direct finding and the truncated GENERIC_CONTEXT prefix
        # produced by a later rolling replay are one logical credential.
        Reset-SelfTestCapture
        $fallbackValue36 = 'CHQA_GenericFallback_ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789Z9!'
        [void](Add-TextFindings -Text ('password=' + $fallbackValue36) -BaseLine 7 -Source $testFile -FilePath $testFile)
        [void](Add-TextFindings -Text ("password=$fallbackValue36`r`nprofile=synthetic") -BaseLine 7 -Source $testFile -FilePath $testFile)
        $t36 = ($script:CapturedFindings.Count -eq 1 -and
                $script:CapturedFindings[0].PatternId -eq 'KV_PASSWORD' -and
                $script:CapturedFindings[0].RawValue -eq $fallbackValue36)
    }
    if ($t36) {
        # Same line/key/prefix at two physical columns is not a replay and must
        # retain both findings.
        Reset-SelfTestCapture
        $samePrefix36 = 'AbCdEfGhIjKlMnOpQrSt'
        $twoOffsets36 = '<add key="monkey-secret-label" value="' + $samePrefix36 + '!"/> monkey-secret-label=' + $samePrefix36
        [void](Add-TextFindings -Text $twoOffsets36 -BaseLine 8 -Source $testFile -FilePath $testFile)
        $xmlCount36 = @($script:CapturedFindings | Where-Object { $_.PatternId -eq 'XML_ADD_KEY_VALUE' }).Count
        $genericCount36 = @($script:CapturedFindings | Where-Object { $_.PatternId -eq 'GENERIC_CONTEXT' }).Count
        $t36 = ($script:CapturedFindings.Count -eq 2 -and $xmlCount36 -eq 1 -and $genericCount36 -eq 1)
    }
    Assert-SelfTest -Name 'Dedicated patterns detect pass=/api-key/db-password/etc.' -Condition $t36

    # T37: key-boundary negatives remain non-findings.
    Reset-SelfTestCapture
    [void](Add-TextFindings -Text 'compass=1' -BaseLine 1 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'bypass=1' -BaseLine 2 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'passion=example' -BaseLine 3 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'tokenization=true' -BaseLine 4 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'monkey=value' -BaseLine 5 -Source $testFile -FilePath $testFile)
    [void](Add-TextFindings -Text 'keyboard=value' -BaseLine 6 -Source $testFile -FilePath $testFile)
    Assert-SelfTest -Name 'compass/bypass/passion/tokenization/monkey/keyboard produce nothing' -Condition ($script:CapturedFindings.Count -eq 0)

    # T38: net use drive-letter, user-first and quoted-password variants.
    Reset-SelfTestCapture
    [void](Add-TextFindings -Text 'net use Z: \\fileserv\share DriveLetterSecret6 /user:CORP\deploy' -BaseLine 1 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    [void](Add-TextFindings -Text 'net use Z: \\fileserv\share /user:CORP\deploy DriveFirstSecret7' -BaseLine 2 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    [void](Add-TextFindings -Text 'net use Z: \\fileserv\share "Quoted Pass! 9" /user:CORP\deploy' -BaseLine 3 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    [void](Add-TextFindings -Text 'net use \\fileserv\share PlainNetUseSecret5 /user:CORP\deploy' -BaseLine 4 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    [void](Add-TextFindings -Text 'net use \\fileserv\share /user:CORP\deploy PlainNetUseSecret4' -BaseLine 5 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    $t38 = ($script:CapturedFindings.Count -eq 5 -and
            (Test-CapturedValue -Value 'DriveLetterSecret6') -and
            (Test-CapturedValue -Value 'DriveFirstSecret7') -and
            (Test-CapturedValue -Value 'Quoted Pass! 9') -and
            (Test-CapturedValue -Value 'PlainNetUseSecret5') -and
            (Test-CapturedValue -Value 'PlainNetUseSecret4'))
    Assert-SelfTest -Name 'net use drive-letter and quoted-password variants detected' -Condition $t38

    # T39: net use forms lacking full credential context produce nothing.
    Reset-SelfTestCapture
    [void](Add-TextFindings -Text 'net use' -BaseLine 1 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    [void](Add-TextFindings -Text 'net use Z: \\server\share' -BaseLine 2 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    [void](Add-TextFindings -Text 'net use Z: \\server\share /persistent:yes' -BaseLine 3 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    [void](Add-TextFindings -Text 'net use Z: \\server\share /user:DOMAIN\user /persistent:no' -BaseLine 4 -Source 'C:\selftest\history.txt' -FilePath 'C:\selftest\history.txt')
    Assert-SelfTest -Name 'net use without full credential context produces nothing' -Condition ($script:CapturedFindings.Count -eq 0)

    # T40: malformed/oversized attributes return safely, quickly, no finding.
    Reset-SelfTestCapture
    $bigLine1 = '<Pass ' + ('a' * 5000) + '>S3cr3tValue</Pass>'
    $bigLine2 = '<Password ' + ('b' * 5000) + '><Value>S3cr3tValue</Value></Password>'
    $perfWatch = [System.Diagnostics.Stopwatch]::StartNew()
    [void](Add-TextFindings -Text $bigLine1 -BaseLine 1 -Source 'C:\selftest\sitemanager.xml' -FilePath 'C:\selftest\sitemanager.xml')
    [void](Add-TextFindings -Text $bigLine2 -BaseLine 2 -Source 'C:\selftest\unattend.xml' -FilePath 'C:\selftest\unattend.xml')
    $perfWatch.Stop()
    $t40 = ($script:CapturedFindings.Count -eq 0 -and $perfWatch.ElapsedMilliseconds -lt 5000)
    Assert-SelfTest -Name 'Oversized attributes: safe, fast, no finding' -Condition $t40

    # T41: strict UTF-8 decoding rejects invalid byte sequences.
    $invalidUtf8Result = Invoke-PlainBase64Decode -Encoded 'wyg='
    $validUtf8Result = Invoke-PlainBase64Decode -Encoded 'U3VwZXJTZWNyZXQh'
    Assert-SelfTest -Name 'Strict UTF-8: invalid Base64 payload returns null' -Condition (($null -eq $invalidUtf8Result) -and ($validUtf8Result -eq 'SuperSecret!'))

    # T42: final-summary writer failure yields failure state and failure status.
    $script:WritersOpen = $true
    $script:TxtWriter = $null
    $script:CsvWriter = $null
    $script:TxtPath = 'C:\selftest\fake.txt'
    $script:CsvPath = 'C:\selftest\fake.csv'
    Write-Summary
    $t42 = ($script:OutputFailed -eq $true -and $script:ExitCode -ne 0)
    $okTitle = Get-SummaryStatusTitle -Failed $false
    $badTitle = Get-SummaryStatusTitle -Failed $true
    if ($okTitle -ne ('  {0} - Scan Complete' -f $script:ToolName)) { $t42 = $false }
    if ($okTitle -match 'OUTPUT INCOMPLETE') { $t42 = $false }
    if ($badTitle -notmatch 'OUTPUT INCOMPLETE') { $t42 = $false }
    $script:OutputFailed = $false
    $script:OutputFailureDetail = ''
    $script:OutputErrorReported = $false
    $script:ExitCode = 0
    Assert-SelfTest -Name 'Final-summary writer failure selects failure status' -Condition $t42

    # ==================== v3 regression suite (T43-T67) =======================
    $stFixRoot = Join-Path -Path $env:TEMP -ChildPath ('ch_st_' + [DateTime]::Now.Ticks)
    $script:StOutDir = Join-Path -Path $stFixRoot -ChildPath 'out'
    try {
        [void][System.IO.Directory]::CreateDirectory($stFixRoot)
        [void][System.IO.Directory]::CreateDirectory($script:StOutDir)

        # T43: canonical volume roots preserved exactly.
        $t43 = ((ConvertTo-CanonicalRoot -PathValue 'C:\') -ceq 'C:\' -and (ConvertTo-CanonicalRoot -PathValue 'D:\') -ceq 'D:\')
        Assert-SelfTest -Name 'Canonical C:\ and D:\ preserved exactly' -Condition $t43

        # T44: bare drive designator normalized explicitly to a volume root.
        Assert-SelfTest -Name 'Bare C: normalized to C:\ explicitly' -Condition ((ConvertTo-CanonicalRoot -PathValue 'C:') -ceq 'C:\')

        # T45: drive-relative forms rejected.
        $t45 = ($null -eq (ConvertTo-CanonicalRoot -PathValue 'C:relative') -and
                $null -eq (ConvertTo-CanonicalRoot -PathValue 'C:.\relative'))
        Assert-SelfTest -Name 'Drive-relative C:relative and C:.\relative rejected' -Condition $t45

        # T46: no canonical result is a bare drive-relative form.
        $t46 = $true
        foreach ($p in @('C:\', 'D:\', 'C:', 'C:\folder', (Join-Path $stFixRoot 'sub'))) {
            $cr = ConvertTo-CanonicalRoot -PathValue $p
            if ($null -ne $cr -and $cr -match '^[A-Za-z]:$') { $t46 = $false }
        }
        Assert-SelfTest -Name 'No planned root is a bare drive-relative form' -Condition $t46

        # T47: overlap elimination preserves parent and removes covered child.
        $ovParent = Join-Path $stFixRoot 'ov'
        $ovChild = Join-Path $ovParent 'child'
        [void][System.IO.Directory]::CreateDirectory($ovChild)
        $savedPathParam = $script:Path
        $script:Path = @($ovChild, $ovParent)
        $ovPlan = Get-ScanPlan
        $script:Path = $savedPathParam
        $t47 = ($ovPlan.Roots.Count -eq 1 -and $ovPlan.Roots[0] -eq (Get-NormalizedPath -PathValue $ovParent))
        Assert-SelfTest -Name 'Overlap elimination keeps parent, drops covered child' -Condition $t47

        # T48: exclusion prefix construction from C:\ is boundary-aware.
        $savedPrefixes = New-Object System.Collections.Generic.List[string]
        foreach ($e in $script:ExcludedPrefixes) { $savedPrefixes.Add($e) }
        $savedDirSet = New-Object System.Collections.Generic.List[string]
        foreach ($e in $script:ExcludedDirSet) { $savedDirSet.Add($e) }
        Initialize-Exclusions -DriveRoots @('C:\')
        $t48 = $true
        foreach ($e in $script:ExcludedPrefixes) {
            if ($e -match '^[A-Za-z]:\\{2}' -or $e -match '^[A-Za-z]:[^\\]') { $t48 = $false }
        }
        if (-not (Test-ExcludedDirectory -FullPath 'C:\$Recycle.Bin\sub' -Name 'sub')) { $t48 = $false }
        if (Test-ExcludedDirectory -FullPath 'C:\$Recycle.BinX' -Name '$Recycle.BinX') { $t48 = $false }
        $script:ExcludedPrefixes.Clear()
        foreach ($e in $savedPrefixes) { $script:ExcludedPrefixes.Add($e) }
        $script:ExcludedDirSet.Clear()
        foreach ($e in $savedDirSet) { $script:ExcludedDirSet.Add($e) }
        Assert-SelfTest -Name 'Exclusion prefixes from C:\ correct and boundary-aware' -Condition $t48

        # T49: a Quick Win finding is emitted, then the full scan continues.
        Reset-SelfTestCapture
        $qwFile = Join-Path $stFixRoot 'qw\target.ini'
        Write-StFixtureFile -Path $qwFile -Content 'password=QuickWinSecret11'
        Add-QuickWinFile -PathValue $qwFile
        $scanDir = Join-Path $stFixRoot 'scan'
        Write-StFixtureFile -Path (Join-Path $scanDir 's1.ini') -Content 'password=LaterSecret22'
        Write-StFixtureFile -Path (Join-Path $scanDir 'sub\s2.ini') -Content 'apikey=LaterSecret33x'
        [void](Invoke-DirectoryTraversal -Root $scanDir -Purpose Scan -EligibleTotal 2)
        $t49 = ((Test-CapturedValue -Value 'QuickWinSecret11') -and
                (Test-CapturedValue -Value 'LaterSecret22') -and
                (Test-CapturedValue -Value 'LaterSecret33x'))
        if (Test-CapturedLeak -Secret 'QuickWinSecret11') { $t49 = $false }
        if (Test-CapturedLeak -Secret 'LaterSecret22') { $t49 = $false }
        if (Test-CapturedLeak -Secret 'LaterSecret33x') { $t49 = $false }
        Assert-SelfTest -Name 'Quick Win finding emitted; full scan finds later secrets' -Condition $t49

        # T50: a Critical private-key Quick Win does not stop the full scan.
