        Write-StFixtureFile -Path $pemFile -Content '-----BEGIN RSA PRIVATE KEY-----'
        Add-QuickWinFile -PathValue $pemFile
        [void](Invoke-DirectoryTraversal -Root $scanDir -Purpose Scan -EligibleTotal 2)
