        if (-not $hasCritical) { $t50 = $false }
        Assert-SelfTest -Name 'Critical private-key Quick Win does not stop full scan' -Condition $t50

        # T51: TerminalAssessedPaths skips only the exact terminally assessed file.
        Reset-SelfTestCapture
        $handledDir = Join-Path $stFixRoot 'scan2'
        $handledFile = Join-Path $handledDir 'target.ini'
        Write-StFixtureFile -Path $handledFile -Content 'password=HandledSecret44'
        Write-StFixtureFile -Path (Join-Path $handledDir 'sibling.ini') -Content 'password=SiblingSecret55'
        Write-StFixtureFile -Path (Join-Path $handledDir 'nested\deep.ini') -Content 'password=NestedSecret66'
        Add-QuickWinFile -PathValue $handledFile
        [void](Invoke-DirectoryTraversal -Root $handledDir -Purpose Scan -EligibleTotal 2)
        $t51 = ((Test-CapturedValue -Value 'SiblingSecret55') -and (Test-CapturedValue -Value 'NestedSecret66'))
        $handledCount = 0
        foreach ($c in $script:CapturedFindings) { if ($c.RawValue -eq 'HandledSecret44') { $handledCount++ } }
        if ($handledCount -ne 1) { $t51 = $false }
        Assert-SelfTest -Name 'Handled paths skip exact file only; siblings scanned' -Condition $t51

        # T52: start/middle/end secrets all emitted; pre-count equals assessed.
        Reset-SelfTestCapture
        $smeDir = Join-Path $stFixRoot 'scan3'
        Write-StFixtureFile -Path (Join-Path $smeDir 'a\first.ini') -Content 'password=StartSecret77'
        Write-StFixtureFile -Path (Join-Path $smeDir 'm\mid\middle.ini') -Content 'password=MiddleSecret88'
        Write-StFixtureFile -Path (Join-Path $smeDir 'z\last.ini') -Content 'password=EndSecret99'
        $pre52 = Invoke-DirectoryTraversal -Root $smeDir -Purpose Count -EligibleTotal 0
        $assessedBefore52 = $script:Stats.FullScanAssessed
        [void](Invoke-DirectoryTraversal -Root $smeDir -Purpose Scan -EligibleTotal $pre52)
        $assessed52 = $script:Stats.FullScanAssessed - $assessedBefore52
