        if (Test-CapturedLeak -Secret 'MiddleSecret88') { $t52 = $false }
        Assert-SelfTest -Name 'Start/middle/end secrets emitted; pre-count equals assessed' -Condition $t52

        # T53/T54: Deep covers extensionless and unknown-extension text files.
        $savedDeepMode = $script:IsDeepMode
        $script:IsDeepMode = $true
        Reset-SelfTestCapture
        $noExtFile = Join-Path $stFixRoot 'deep\noextfile'
        Write-StFixtureFile -Path $noExtFile -Content 'password=DeepExtless1'
        $unkExtFile = Join-Path $stFixRoot 'deep\mystery.zzz'
        Write-StFixtureFile -Path $unkExtFile -Content 'password=DeepUnknown2'
        $noExtItem = Get-Item -LiteralPath $noExtFile
        $clsNoExt = Get-FileClassification -FullPath $noExtFile -Name $noExtItem.Name -Extension $noExtItem.Extension -ParentName 'deep' -Length ([long]$noExtItem.Length) -ForceEligible $false
        if ($clsNoExt.Process) { [void](Invoke-FileAssessment -FullPath $noExtFile -Classification $clsNoExt -FromQuickWin $false) }
        $unkItem = Get-Item -LiteralPath $unkExtFile
        $clsUnk = Get-FileClassification -FullPath $unkExtFile -Name $unkItem.Name -Extension $unkItem.Extension -ParentName 'deep' -Length ([long]$unkItem.Length) -ForceEligible $false
        if ($clsUnk.Process) { [void](Invoke-FileAssessment -FullPath $unkExtFile -Classification $clsUnk -FromQuickWin $false) }
        Assert-SelfTest -Name 'Deep detects secret in extensionless text file' -Condition (Test-CapturedValue -Value 'DeepExtless1')
        Assert-SelfTest -Name 'Deep detects secret in unknown-extension file' -Condition (Test-CapturedValue -Value 'DeepUnknown2')

        # T55: Standard does not select the unknown file; explicit supply does.
        $script:IsDeepMode = $false
        $clsUnkStd = Get-FileClassification -FullPath $unkExtFile -Name $unkItem.Name -Extension $unkItem.Extension -ParentName 'deep' -Length ([long]$unkItem.Length) -ForceEligible $false
        $clsUnkForced = Get-FileClassification -FullPath $unkExtFile -Name $unkItem.Name -Extension $unkItem.Extension -ParentName 'deep' -Length ([long]$unkItem.Length) -ForceEligible $true
        $t55 = ((-not $clsUnkStd.Process) -and $clsUnkForced.Process)
        Assert-SelfTest -Name 'Standard narrower for unknown extension; explicit supply eligible' -Condition $t55
        $script:IsDeepMode = $savedDeepMode

        # T56: Deep rejects both an obvious binary header and binary content
        # that begins after the initial 8 KiB encoding probe. Neither may emit
        # a credential, and every binary rejection is a declared format gap.
        $script:IsDeepMode = $true
        Reset-StCounters
        Reset-SelfTestCapture
        $binFile = Join-Path $stFixRoot 'deep\payload.bin'
        $binBytes = New-Object 'System.Collections.Generic.List[byte]'
        $binBytes.Add(0x4D)
        $binBytes.Add(0x5A)
        for ($i = 0; $i -lt 256; $i++) { $binBytes.Add(0x90) }
        [System.IO.File]::WriteAllBytes($binFile, $binBytes.ToArray())
        $binSkippedBefore = $script:Stats.BinarySkipped
        $binItem = Get-Item -LiteralPath $binFile
        $clsBin = Get-FileClassification -FullPath $binFile -Name $binItem.Name -Extension $binItem.Extension -ParentName 'deep' -Length ([long]$binItem.Length) -ForceEligible $false
        if ($clsBin.Process) { [void](Invoke-FileAssessment -FullPath $binFile -Classification $clsBin -FromQuickWin $false) }
        $lateBinFile = Join-Path $stFixRoot 'deep\late-binary.txt'
        $lateSecret56 = 'MustNotEmitLateBinary56'
        $latePrefix56 = [System.Text.Encoding]::ASCII.GetBytes(('A' * 9000))
        $lateNuls56 = New-Object 'byte[]' 12000
        $lateTail56 = [System.Text.Encoding]::ASCII.GetBytes("`r`npassword=$lateSecret56`r`n")
        $lateBytes56 = New-Object 'byte[]' ($latePrefix56.Length + $lateNuls56.Length + $lateTail56.Length)
        [Array]::Copy($latePrefix56, 0, $lateBytes56, 0, $latePrefix56.Length)
        [Array]::Copy($lateNuls56, 0, $lateBytes56, $latePrefix56.Length, $lateNuls56.Length)
        [Array]::Copy($lateTail56, 0, $lateBytes56, $latePrefix56.Length + $lateNuls56.Length, $lateTail56.Length)
        [System.IO.File]::WriteAllBytes($lateBinFile, $lateBytes56)
        $lateItem56 = Get-Item -LiteralPath $lateBinFile
        $lateClass56 = Get-FileClassification -FullPath $lateBinFile -Name $lateItem56.Name -Extension $lateItem56.Extension -ParentName 'deep' -Length ([long]$lateItem56.Length) -ForceEligible $false
        if ($lateClass56.Process) { [void](Invoke-FileAssessment -FullPath $lateBinFile -Classification $lateClass56 -FromQuickWin $false) }
        $sparseBinFile56 = Join-Path $stFixRoot 'deep\sparse-nul-binary.txt'
        $sparseSecret56 = 'SparseNulMustNotEmit56' + ('X' * 260) + 'Z9!'
        $sparseTail56 = [System.Text.Encoding]::ASCII.GetBytes('password=' + $sparseSecret56)
        $sparseBytes56 = New-Object 'byte[]' (32 + $sparseTail56.Length)
        for ($sparseIndex56 = 0; $sparseIndex56 -lt 32; $sparseIndex56++) {
            $sparseBytes56[$sparseIndex56] = $(if (($sparseIndex56 % 3) -eq 0) { 0 } else { [byte](65 + ($sparseIndex56 % 20)) })
        }
        [Array]::Copy($sparseTail56, 0, $sparseBytes56, 32, $sparseTail56.Length)
        [System.IO.File]::WriteAllBytes($sparseBinFile56, $sparseBytes56)
        $sparseItem56 = Get-Item -LiteralPath $sparseBinFile56
        $sparseClass56 = Get-FileClassification -FullPath $sparseBinFile56 -Name $sparseItem56.Name -Extension $sparseItem56.Extension -ParentName 'deep' -Length ([long]$sparseItem56.Length) -ForceEligible $false
        if ($sparseClass56.Process) { [void](Invoke-FileAssessment -FullPath $sparseBinFile56 -Classification $sparseClass56 -FromQuickWin $false) }

        # A printable first block must not commit a finding before a later
        # block proves that the same carrier is binary.
        $earlyLateBinFile56 = Join-Path $stFixRoot 'deep\early-secret-late-nul.txt'
        $earlyLateSecret56 = 'MustRollbackBeforeLateBinary56'
        $earlyLatePrefix56 = [System.Text.Encoding]::ASCII.GetBytes("password=$earlyLateSecret56`r`n" + ('A' * ($script:ReadBlockBytes + 1024)))
        $earlyLateNuls56 = New-Object 'byte[]' 64
        $earlyLateBytes56 = New-Object 'byte[]' ($earlyLatePrefix56.Length + $earlyLateNuls56.Length)
        [Array]::Copy($earlyLatePrefix56, 0, $earlyLateBytes56, 0, $earlyLatePrefix56.Length)
        [Array]::Copy($earlyLateNuls56, 0, $earlyLateBytes56, $earlyLatePrefix56.Length, $earlyLateNuls56.Length)
        [System.IO.File]::WriteAllBytes($earlyLateBinFile56, $earlyLateBytes56)
        $earlyLateItem56 = Get-Item -LiteralPath $earlyLateBinFile56
        $earlyLateClass56 = Get-FileClassification -FullPath $earlyLateBinFile56 -Name $earlyLateItem56.Name -Extension $earlyLateItem56.Extension -ParentName 'deep' -Length ([long]$earlyLateItem56.Length) -ForceEligible $false
        if ($earlyLateClass56.Process) { [void](Invoke-FileAssessment -FullPath $earlyLateBinFile56 -Classification $earlyLateClass56 -FromQuickWin $false) }
        $binaryNoFindingsBeforeRace56 = ($script:CapturedFindings.Count -eq 0 -and
                                         -not (Test-CapturedValue -Value $lateSecret56) -and
                                         -not (Test-CapturedValue -Value $sparseSecret56) -and
                                         -not (Test-CapturedValue -Value $earlyLateSecret56))

        # Deterministic live-source race: at the second preflight callback try
        # to replace bytes in the already-read block without changing length.
        # The read-only sharing contract must reject the writer, keeping the
        # classified snapshot stable through the emission pass.
        $raceBinFile56 = Join-Path $stFixRoot 'deep\race-to-binary.txt'
        $raceSecret56 = 'RaceMustNotCommitBeforeBinary56'
        [System.IO.File]::WriteAllText($raceBinFile56,
            ("password=$raceSecret56`r`n" + ('A' * ($script:ReadBlockBytes * 2 + 2048))),
            (New-Object System.Text.UTF8Encoding ($false)))
        $raceNorm56 = Get-NormalizedPath -PathValue $raceBinFile56
        $script:StRaceBlockCount56 = 0
        $script:StRaceWriteAttempted56 = $false
        $script:StRaceWriteBlocked56 = $false
        $raceResult56 = $null
        try {
            $script:FaultSeam.Enabled = $true
            $script:FaultSeam.OnBlockRead = {
                param($racePath56)
                if ($racePath56 -eq $raceNorm56) { $script:StRaceBlockCount56++ }
                if ($script:StRaceBlockCount56 -eq 2 -and -not $script:StRaceWriteAttempted56 -and
