                        [void]$raceWriter56.Seek(($script:ReadBlockBytes + 512), [System.IO.SeekOrigin]::Begin)
                        $raceNuls56 = New-Object 'byte[]' 64
                        $raceWriter56.Write($raceNuls56, 0, $raceNuls56.Length)
                        $raceWriter56.Flush()
                    } catch {
                        $script:StRaceWriteBlocked56 = $true
                    } finally {
                        if ($null -ne $raceWriter56) { $raceWriter56.Dispose() }
                    }
                }
            }
            $raceResult56 = Invoke-TextScan -Path $raceNorm56 -DisplaySource $raceNorm56 -Extension '.txt' -DoRolling $false
        } finally {
            Reset-StSeam
        }
        $raceStable56 = ($null -ne $raceResult56 -and $raceResult56.Outcome -eq 'Completed' -and
                         $script:StRaceWriteAttempted56 -and $script:StRaceWriteBlocked56 -and
