        $dbcsResult56 = @{ Outcome = 'Completed'; BinaryKind = ''; EncodingUsed = $dbcsEncoding56 }
        $dbcsState56 = @{
            Stop = $false; Result = $dbcsResult56; PreambleSkipped = $true; PreambleBytes = 0
            Decoder = $dbcsEncoding56.GetDecoder()
        }
        $dbcsBytes56 = [byte[]](0x81,0x00,0x41,0x42)
        Process-ScanBlock -State $dbcsState56 -Bytes $dbcsBytes56 -Count $dbcsBytes56.Length -Flush $false
        $dbcsBinary56 = ($dbcsState56.Stop -and $dbcsResult56.Outcome -eq 'Binary' -and
