        Assert-SelfTest -Name 'T81 ProfileList AccessDenied still processes USERPROFILE and later finding' -Condition $t81

        # Enumeration and roots ----------------------------------------------

        # T82 (case 9): enumeration wrapper dispatches an accessible item and
