        Reset-StCounters; Reset-SelfTestCapture
        $enumDir = Join-Path $stFixRoot 'enumw'
        $enumFile = Join-Path $enumDir 'visible.ini'
        Write-StFixtureFile -Path $enumFile -Content 'password=EnumVisible1'
        $enumItem = Get-Item -LiteralPath $enumFile
        $script:FaultSeam.EnumHandler = {
            param($dir)
