                $errs82.Add((New-Object System.UnauthorizedAccessException ('injected partial')))
                $errs82.Add((New-Object System.IO.PathTooLongException ('injected long path')))
                return @{ Items = @($enumItem); Errors = $errs82; EnumerationStarted = $true; EnumerationCompleted = $true; TopLevelFatal = $false }
            }
            return $null
        }
        try {
            $enumState82 = @{ Seen = [long]0 }
            $enumResult = Invoke-DirectoryEnumeration -Directory (Get-NormalizedPath -PathValue $enumDir) -IsTopLevel $false -CountErrors $true -State $enumState82 -OnItem {
                param($visibleItem, $state)
                if ($null -ne $visibleItem) { $state.Seen++ }
            }
            $t82 = ($enumResult.ItemCount -eq 1 -and $enumState82.Seen -eq 1 -and $enumResult.Errors.Count -eq 2 -and
                    $script:Stats.AccessDeniedSkipped -eq 1 -and
                    $script:Stats.LongPathsSkipped -eq 1 -and
