        $root108 = & $newNode108
        $software108 = & $newNode108
        $microsoft108 = & $newNode108
        $windowsNt108 = & $newNode108
        $currentVersion108 = & $newNode108
        $winlogon108 = & $newNode108
        $root108.SubKeys['SOFTWARE'] = $software108
        $software108.SubKeys['Microsoft'] = $microsoft108
        $microsoft108.SubKeys['Windows NT'] = $windowsNt108
        $windowsNt108.SubKeys['CurrentVersion'] = $currentVersion108
        $currentVersion108.SubKeys['Winlogon'] = $winlogon108
        $script:FaultSeam.FakeRegistry = @{ 'LocalMachine|Default' = $root108 }
        $script:FaultSeam.ThrowAtOperation = New-StHashSet -Items @('Registry.Winlogon.Body')
        $base108 = $null
        $escaped = $false
        $t108 = $false
        try {
            try {
                $base108 = Open-RegistryBase -Hive ([Microsoft.Win32.RegistryHive]::LocalMachine) -View 'Default'
                Invoke-RegistryFamily -FamilyId 'HKLM|Default|Winlogon' -Body {
                    if (Test-RegOpenSuccess -Record $base108 -ErrKey 'SelfTest.T108.OpenBase') {
                        Test-RegistryWinlogon -Hklm $base108.Key -View 'Default'
                    }
                }
            } catch { $escaped = $true }
        } finally {
            if ($null -ne $base108 -and $base108.Status -eq 'Ok') {
