            }
            $t108 = ((-not $escaped) -and $script:CoverageIncomplete -and
                    $script:Stats.RegistryHandlesOpened -eq 2 -and
                    $script:Stats.RegistryHandlesClosed -eq 2 -and
                    $script:Stats.RegistryCloseAttempts -eq 2)
            Reset-StSeam
        }
        Assert-SelfTest -Name 'T108 Injected registry body error is contained and disposed' -Condition $t108

        # T109 (case 36): unexpected registry driver failure does not stop the
        # restricted full scan.
        Reset-StCounters; Reset-SelfTestCapture
        $script:FaultSeam.SkipRealQuickWins = $true
        $script:FaultSeam.QuickWinExtraFiles = @()
        $script:FaultSeam.ThrowAtOperation = New-StHashSet -Items @('Phase.Registry')
        try {
            Add-PhaseState -Name 'QuickWins'; Add-PhaseState -Name 'Environment'; Add-PhaseState -Name 'Registry'; Add-PhaseState -Name 'FullScan'
            Add-RootState -Name (Get-NormalizedPath -PathValue $isoRoot) -Kind 'Root' -State 'Pending'
            Invoke-Phase -Name 'QuickWins' -Body { Invoke-QuickWins }
            Invoke-Phase -Name 'Environment' -Body { Invoke-EnvironmentChecks }
            Invoke-Phase -Name 'Registry' -Body { Invoke-RegistryChecks }
            Invoke-Phase -Name 'FullScan' -Body { Invoke-FullScanPhase -Plan @{ Roots = @((Get-NormalizedPath -PathValue $isoRoot)); Files = @(); Rejected = @() } }
