                     (Test-IsSelfOrOutput -FullPath 'C:\x\Umbra_v4.2.3_Results_TEST0_20000101_000000_01.txt') -and
                     (Test-IsSelfOrOutput -FullPath 'C:\x\CredHunter_Results_TEST0_20000101_000000.txt') -and
                     (Test-IsSelfOrOutput -FullPath 'C:\x\CredHunter_v4.1.0_Results_TEST0_20000101_000000.csv') -and
                     (Test-IsSelfOrOutput -FullPath 'C:\x\CredHunter_v4.1.0_Results_TEST0_20000101_000000_01.txt') -and
                     (Test-IsSelfOrOutput -FullPath ([string]$selfItem117.FullName)) -and
