        } finally { $script:ScriptPath = $savedScript117 }
        Assert-SelfTest -Name 'T117 Umbra and legacy result files excluded' -Condition $t117

        # T118 (case 45): CSV header byte-exact and BOTH outputs UTF-8 no BOM.
        $csvBytes118 = [System.IO.File]::ReadAllBytes($firstCsv)
        $txtBytes118 = [System.IO.File]::ReadAllBytes($firstTxt)
