        try { $firstLine118 = $sr118.ReadLine(); $dataLine118 = $sr118.ReadLine() } finally { $sr118.Dispose() }
        $noBom118 = ($csvBytes118.Length -ge 3 -and $txtBytes118.Length -ge 3 -and
