                    -not ($txtBytes118[0] -eq 0xEF -and $txtBytes118[1] -eq 0xBB -and $txtBytes118[2] -eq 0xBF))
        $t118 = ($noBom118 -and $firstLine118.Split(',').Count -eq 30 -and
