                ($firstLine118 -ceq 'Timestamp,Type,Category,Severity,Confidence,Source,FilePath,RegistryPath,ValueName,LineNumber,PatternId,Value,Context,Drive,UserProfile,Notes,FindingKind,App,SourceKind,Account,Endpoint,Port,PhysicalPath,LogicalPath,ContainerEntry,KeyPath,DecodeChain,ConfidenceEvidence,CoverageMode,SampleOffset'))
        Assert-SelfTest -Name 'T118 CSV header/data schema exact, TXT and CSV UTF-8 without BOM' -Condition $t118

        # T119 (case 46): phase and root equations balance exactly in success
        # and failure fixtures (T115 completed execution/partial coverage,
        # T114 execution failure above).
        $t119 = (($script:Stats.PhasesPlanned -eq ($script:Stats.PhasesCompleted + $script:Stats.PhasesFailed + $script:Stats.PhasesCancelled)) -and
                 ($script:Stats.RootsPlanned -eq ($script:Stats.RootsCompleted + $script:Stats.RootsFailed + $script:Stats.RootsCancelled)))
        Assert-SelfTest -Name 'T119 Phase and root equations balance exactly' -Condition $t119

        $script:CaptureMode = $true

