        # recover it exactly once. The following file proves continuation.
        Reset-StCounters; Reset-SelfTestCapture
        $hugeDir = Join-Path $stFixRoot 'huge'
        $crossSecret120 = 'CrossChunkSecret99'
        $crossAssignment120 = ' password="' + $crossSecret120 + '"'
        $crossPad120 = $script:MaxUnitChars - 14
        if ($crossPad120 -lt 1) { $crossPad120 = 1 }
        $hugeLine = ('A' * $crossPad120) + $crossAssignment120
        Write-StFixtureFile -Path (Join-Path $hugeDir 'huge.txt') -Content $hugeLine
        Write-StFixtureFile -Path (Join-Path $hugeDir 'next.txt') -Content 'password=NextFileSecret77'
        [void](Invoke-DirectoryTraversal -Root $hugeDir -Purpose Scan -EligibleTotal 2)
        $crossCount = 0
        foreach ($c in $script:CapturedFindings) {
            if ($c.RawValue -eq $crossSecret120 -and $c.PatternId -eq 'KV_PASSWORD') { $crossCount++ }
        }
        $t120 = ($crossCount -eq 1 -and (Test-CapturedValue -Value 'NextFileSecret77'))
        Assert-SelfTest -Name 'T120 Dynamic cross-chunk quoted secret found once; next file scanned' -Condition $t120

        # T186: an unquoted assignment with a logical remainder beyond the
        # exact 512-character grammar bound must not disappear. Emit one
