        Reset-StCounters; Reset-SelfTestCapture
        $longTailDir186 = Join-Path $stFixRoot 'longtail186'
        $prefixSecret186 = 'LongTailSecret186'
        $tailSensitive186 = 'TailSensitiveMaterial186'
        $longTailLine186 = 'password=' + $prefixSecret186 + ' ' + $tailSensitive186 + ('Z' * 600)
        Write-StFixtureFile -Path (Join-Path $longTailDir186 'longtail.ini') -Content $longTailLine186
        Write-StFixtureFile -Path (Join-Path $longTailDir186 'after.ini') -Content 'password=AfterLongTailSecret186'
        [void](Invoke-DirectoryTraversal -Root $longTailDir186 -Purpose Scan -EligibleTotal 2)
        $longTailMatches186 = @($script:CapturedFindings | Where-Object {
            $_.PatternId -eq 'KV_PASSWORD_LONGTAIL_CANDIDATE' -and
            $_.RawValue -eq $prefixSecret186
        })
        $t186 = ($longTailMatches186.Count -eq 1 -and
                 $longTailMatches186[0].Confidence -eq 'Low' -and
                 $longTailMatches186[0].Notes -match 'ValueBoundaryUncertain' -and
                 $longTailMatches186[0].Notes -match 'LongTailPrefixCandidate' -and
                 (Test-CapturedValue -Value 'AfterLongTailSecret186') -and
                 -not (Test-CapturedLeak -Secret $prefixSecret186) -and
