        Reset-StCounters; Reset-SelfTestCapture
        $script:FaultSeam.TimeoutPatternIds = New-StHashSet -Items @('KV_PASSWORD')
        try {
            [void](Add-TextFindings -Text 'password=TimeoutSecret1 apikey=GoodCredVal12345' -BaseLine 1 -Source 'C:\selftest\to.ini' -FilePath 'C:\selftest\to.ini')
            $t121 = ($script:Stats.RegexTimeoutEvents -ge 1 -and $script:ContentCoverageIncomplete -and
