            }
            if (Test-CapturedLeak -Secret 'TimeoutSecret1') { $t121 = $false }
            if (Test-CapturedLeak -Secret 'GoodCredVal12345') { $t121 = $false }
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T121 Regex timeout: fail-closed finding, later patterns continue' -Condition $t121

        # T122 (case 49): a UTF-8 multi-byte sequence split at the probe
        # boundary does not force a false ANSI decision.
        Reset-StCounters; Reset-SelfTestCapture
        $splitFile = Join-Path $stFixRoot 'enc\split.txt'
        [void][System.IO.Directory]::CreateDirectory((Join-Path $stFixRoot 'enc'))
        $splitBytes = New-Object 'System.Collections.Generic.List[byte]'
        $padBytes = [System.Text.Encoding]::ASCII.GetBytes('A' * 8191)
        foreach ($b in $padBytes) { $splitBytes.Add($b) }
        foreach ($b in [System.Text.Encoding]::UTF8.GetBytes([char]0xE9)) { $splitBytes.Add($b) }
        foreach ($b in [System.Text.Encoding]::UTF8.GetBytes("`r`npassword=Utf8SplitSecret7")) { $splitBytes.Add($b) }
        [System.IO.File]::WriteAllBytes($splitFile, $splitBytes.ToArray())
        $splitResult = Invoke-TextScan -Path $splitFile -DisplaySource $splitFile -Extension '.txt' -DoRolling $false
        $t122 = ($splitResult.Outcome -eq 'Completed' -and (Test-CapturedValue -Value 'Utf8SplitSecret7'))
        Assert-SelfTest -Name 'T122 UTF-8 split at probe boundary stays UTF-8' -Condition $t122

        # T123/T124 (cases 50/51): BOM-less UTF-16LE/BE are recognized and
        # scanned.
        Reset-StCounters; Reset-SelfTestCapture
        $leFile = Join-Path $stFixRoot 'enc\le.txt'
        $unicodePrefix123 = (([string][char]0x6F22) * 500) + "`r`n"
        [System.IO.File]::WriteAllBytes($leFile, [System.Text.Encoding]::Unicode.GetBytes($unicodePrefix123 + 'password=Utf16LeSecret9'))
        $beFile = Join-Path $stFixRoot 'enc\be.txt'
        [System.IO.File]::WriteAllBytes($beFile, [System.Text.Encoding]::BigEndianUnicode.GetBytes($unicodePrefix123 + 'password=Utf16BeSecret8'))
        $leResult = Invoke-TextScan -Path $leFile -DisplaySource $leFile -Extension '.txt' -DoRolling $false
        $beResult = Invoke-TextScan -Path $beFile -DisplaySource $beFile -Extension '.txt' -DoRolling $false
        $t123 = ($leResult.Outcome -eq 'Completed' -and $leResult.EncodingUsed.CodePage -eq 1200 -and
                 (Test-CapturedValue -Value 'Utf16LeSecret9'))
        $t124 = ($beResult.Outcome -eq 'Completed' -and $beResult.EncodingUsed.CodePage -eq 1201 -and
                 (Test-CapturedValue -Value 'Utf16BeSecret8'))

        # Every BOM-selected decoder is strict. Malformed data placed beyond
        # the initial 8 KiB probe must fail before the early credential can be
        # emitted, and UTF-8 BOM data is never retried as ANSI.
        Reset-SelfTestCapture
        $malformedSecret123 = 'MalformedBomMustNotEmit123'
        $malformedText123 = "password=$malformedSecret123`r`n" + ('A' * 9000)
        $strictCases123 = @(
            @{ Name='utf8';    Preamble=[byte[]](0xEF,0xBB,0xBF); Encoding=(New-Object System.Text.UTF8Encoding ($false)); Invalid=[byte[]](0xFF) },
            @{ Name='utf16le'; Preamble=[byte[]](0xFF,0xFE); Encoding=(New-Object System.Text.UnicodeEncoding ($false,$false)); Invalid=[byte[]](0x00,0xD8) },
            @{ Name='utf16be'; Preamble=[byte[]](0xFE,0xFF); Encoding=(New-Object System.Text.UnicodeEncoding ($true,$false)); Invalid=[byte[]](0xD8,0x00) },
            @{ Name='utf32le'; Preamble=[byte[]](0xFF,0xFE,0x00,0x00); Encoding=(New-Object System.Text.UTF32Encoding ($false,$false)); Invalid=[byte[]](0x00,0x00,0x11,0x00) },
            @{ Name='utf32be'; Preamble=[byte[]](0x00,0x00,0xFE,0xFF); Encoding=(New-Object System.Text.UTF32Encoding ($true,$false)); Invalid=[byte[]](0x00,0x11,0x00,0x00) }
        )
        $strictBom123 = $true
        foreach ($strictCase123 in $strictCases123) {
            $validBytes123 = $strictCase123.Encoding.GetBytes($malformedText123)
            $strictBytes123 = New-Object 'byte[]' ($strictCase123.Preamble.Length + $validBytes123.Length + $strictCase123.Invalid.Length)
            [Array]::Copy($strictCase123.Preamble, 0, $strictBytes123, 0, $strictCase123.Preamble.Length)
            [Array]::Copy($validBytes123, 0, $strictBytes123, $strictCase123.Preamble.Length, $validBytes123.Length)
            [Array]::Copy($strictCase123.Invalid, 0, $strictBytes123,
                ($strictCase123.Preamble.Length + $validBytes123.Length), $strictCase123.Invalid.Length)
            $strictPath123 = Join-Path $stFixRoot ('enc\malformed-' + $strictCase123.Name + '.txt')
            [System.IO.File]::WriteAllBytes($strictPath123, $strictBytes123)
            $strictResult123 = Invoke-TextScan -Path $strictPath123 -DisplaySource $strictPath123 -Extension '.txt' -DoRolling $false
            if ($strictResult123.Outcome -ne 'DecodeInvalid' -or
                $strictResult123.PrimaryCause -ne 'DecodeInvalid' -or
                $strictResult123.FailureType -ne 'DecoderFallbackException' -or
                -not ($strictResult123.EncodingUsed.DecoderFallback -is [System.Text.DecoderExceptionFallback])) {
                $strictBom123 = $false
            }
        }
        if (Test-CapturedValue -Value $malformedSecret123) { $strictBom123 = $false }
        $t123 = ($t123 -and $strictBom123)
        $t124 = ($t124 -and $strictBom123)
        Assert-SelfTest -Name 'T123 BOM-less UTF-16LE recognized and scanned' -Condition $t123
        Assert-SelfTest -Name 'T124 BOM-less UTF-16BE recognized and scanned' -Condition $t124

        # T125 (case 52): magic-signature binary fixtures produce no findings.
        Reset-StCounters; Reset-SelfTestCapture
        $pngFile = Join-Path $stFixRoot 'enc\img.bin'
        $pngBytes = New-Object 'System.Collections.Generic.List[byte]'
        foreach ($b in @(0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A)) { $pngBytes.Add([byte]$b) }
        foreach ($b in [System.Text.Encoding]::ASCII.GetBytes('password=PngBinNotSeen1')) { $pngBytes.Add($b) }
        [System.IO.File]::WriteAllBytes($pngFile, $pngBytes.ToArray())
        $pngResult = Invoke-TextScan -Path $pngFile -DisplaySource $pngFile -Extension '.bin' -DoRolling $false
        $t125 = ($pngResult.Outcome -eq 'Binary' -and (-not (Test-CapturedValue -Value 'PngBinNotSeen1')))
        Assert-SelfTest -Name 'T125 Magic-signature binary produces no findings' -Condition $t125

        # T126 (case 53): metadata containing ESC/CR/LF cannot inject terminal
        # or TXT/CSV lines.
        Reset-SelfTestCapture
        $script:RevealActive = $false
        Add-EnvSecretFinding -Name 'API_KEY' -Value ("raw`r`n" + [char]27 + '[31mInjectedSecret1') -Scope 'Process'
        $t126 = ($script:CapturedFindings.Count -eq 1)
        foreach ($c in $script:CapturedFindings) {
            foreach ($prop in @('DisplayValue', 'Context', 'Notes')) {
                $v = [string]$c[$prop]
                if ($v.IndexOf("`r") -ge 0 -or $v.IndexOf("`n") -ge 0 -or $v.IndexOf([char]27) -ge 0) { $t126 = $false }
            }
        }
        Assert-SelfTest -Name 'T126 Control characters in metadata are collapsed' -Condition $t126

        # T127 (case 54): an injected redaction transformation failure replaces
        # the whole field with [redacted:transformation-failed] and leaks nothing.
        Reset-StCounters; Reset-SelfTestCapture
        $badSpanRec = New-FindingRecord
        $badSpanRec.Type = 'Content'; $badSpanRec.Category = 'Password'; $badSpanRec.Severity = 'High'; $badSpanRec.Confidence = 'High'
        $badSpanRec.Source = 'C:\selftest\spanfail.ini'; $badSpanRec.DisplaySource = 'C:\selftest\spanfail.ini'; $badSpanRec.FilePath = 'C:\selftest\spanfail.ini'
        $badSpanRec.LineNumber = 1; $badSpanRec.PatternId = 'KV_PASSWORD'
        $badSpanRec.RawValue = 'TransformFailSecret1'; $badSpanRec.RawContext = 'password=TransformFailSecret1'
        $badSpanRec.MatchIndex = 9; $badSpanRec.MatchLength = 19
        $badSpanRec.ContextSpans = @($null)
        [void](Add-Finding -Finding $badSpanRec)
        $t127 = ($script:CapturedFindings.Count -eq 1 -and $script:ContentCoverageIncomplete)
        foreach ($c in $script:CapturedFindings) {
            if ($c.Context -ne '[redacted:transformation-failed]') { $t127 = $false }
        }
        if (Test-CapturedLeak -Secret 'TransformFailSecret1') { $t127 = $false }
        Assert-SelfTest -Name 'T127 Redaction transformation failure fails closed' -Condition $t127

        # T128 (case 55): the redacted runtime hides both values and keeps the
        # protected blob accurately labelled; the opt-in display/context code
        # remains source-pinned without enabling it in qualification.
        Reset-SelfTestCapture
        $script:RevealActive = $false
        [void](Add-TextFindings -Text 'password=RevealExpected1' -BaseLine 1 -Source 'C:\selftest\r.ini' -FilePath 'C:\selftest\r.ini')
        [void](Add-TextFindings -Text 'password 51:b:0300A1B2C3D4E5F60718' -BaseLine 1 -Source 'C:\selftest\b.rdp' -FilePath 'C:\selftest\b.rdp')
        $t128 = $false
        $plainOk = $false; $blobOk = $false
        foreach ($c in $script:CapturedFindings) {
            if ($c.RawValue -eq 'RevealExpected1' -and $c.DisplayValue -ne 'RevealExpected1' -and
                $c.Context -notmatch 'RevealExpected1') { $plainOk = $true }
            if ($c.PatternId -eq 'RDP_PASSWORD_BLOB' -and $c.DisplayValue -notmatch '0300A1B2C3D4E5F60718' -and
                $c.Notes -match 'not plaintext') { $blobOk = $true }
        }
        $t128 = ($plainOk -and $blobOk -and
                 $revealContractSource.Contains('$displayValue = ConvertTo-SafeText -Text $rawValue') -and
                 $revealContextGuard21 -ge 0)
        Assert-SelfTest -Name 'T128 RevealSecrets contract source-pinned; runtime values stay redacted' -Condition $t128

        # Versioning and documentation ------------------------------------------

        # T129 (case 56): param block is the first executable statement and the
        # version constants occur only after param/StrictMode.
        $selfPath = $PSCommandPath
        $t129 = $false
        $selfText = ''
        if (-not [string]::IsNullOrEmpty($selfPath) -and (Test-Path -LiteralPath $selfPath)) {
            $selfText = [System.IO.File]::ReadAllText($selfPath)
            $idxCmdlet = $selfText.IndexOf('[CmdletBinding()]')
            $idxStrict = $selfText.IndexOf('Set-StrictMode -Version 2.0')
            $idxVer = $selfText.IndexOf(("`$script:ToolVersion = '{0}'" -f $script:ToolVersion))
            $idxInit = $selfText.IndexOf('Initialize-Patterns')
