        }
        Assert-SelfTest -Name 'T129 Param first; version constants after param/StrictMode' -Condition $t129

        # T130 (case 57): filename, banner, TXT initialization, summary and
        # result basenames carry the current ToolVersion.
        $verRx = [regex]::Escape($script:ToolVersion)
        $selfLeaf130 = [System.IO.Path]::GetFileName($selfPath)
        $releaseLeaf130 = $script:ToolName + '_v' + $script:ToolVersion + '.ps1'
        $candidateLeaf130 = $script:ToolName + '_v' + $script:ToolVersion + '-candidate.ps1'
        $t130 = ($selfLeaf130 -ceq $releaseLeaf130 -or $selfLeaf130 -ceq $candidateLeaf130)
        $sumLines130 = Get-SummaryLines -Status 'Complete'
