        Assert-SelfTest -Name 'T130 Filename, summary and result basenames carry current version' -Condition $t130

        # T131 (case 58): runtime versioned strings derive from ToolVersion.
        $prodText = $selfText.Substring(0, $selfText.IndexOf('function Invoke-SelfTest'))
        $t131 = $true
        foreach ($srcLine in ($prodText -split "`n")) {
            if ($srcLine.Contains($script:ToolVersion) -and -not $srcLine.TrimStart().StartsWith('#') -and
                -not $srcLine.Contains(("`$script:ToolVersion = '{0}'" -f $script:ToolVersion))) { $t131 = $false }
        }
        Assert-SelfTest -Name 'T131 No duplicated hard-coded runtime version strings' -Condition $t131

        # T132 (case 59): no ACL/permission-mutating primitive anywhere in the
