        $fb1 = 'Set-' + 'Acl'; $fb2 = 'Get-' + 'Acl'; $fb3 = 'SetAccess' + 'Control'
        $fb4 = 'take' + 'own'; $fb5 = 'ica' + 'cls'
        $t132 = (-not $selfText.Contains($fb1) -and -not $selfText.Contains($fb3) -and
                 -not $selfText.Contains($fb4) -and -not $selfText.Contains($fb5) -and
                 -not $selfText.Contains($fb2))
        Assert-SelfTest -Name 'T132 No ACL/permission-mutating primitive anywhere' -Condition $t132

        # T133 (case 60): a fatal mid-scan output failure stops scanning and
        # transitions current/remaining phase/root states to Cancelled once.
        try {
            $qwSecretFile = Join-Path $stFixRoot 'qwout\secret.ini'
            Write-StFixtureFile -Path $qwSecretFile -Content 'password=OutStopSecret1'
            $script:FaultSeam.SkipRealQuickWins = $true
            $script:FaultSeam.QuickWinExtraFiles = @($qwSecretFile)
            $script:FaultSeam.OutputFailureAt = 'FindingWrite'
            [void](Invoke-StLifecycle -FullScan $true -Roots @((Get-NormalizedPath -PathValue $isoRoot)) -Files @())
            $txt133 = Get-Content -LiteralPath $script:TxtPath -Raw
            # Writers are closed by the failure: the TXT stays partial (no
            # success title), the red console OUTPUT INCOMPLETE is authoritative.
            $t133 = ($script:ExitCode -eq 1 -and $script:OutputFailed -and
                    $txt133 -notmatch ([regex]::Escape($script:ToolName + ' - Scan Complete')) -and
                    ($script:Stats.PhasesPlanned -eq ($script:Stats.PhasesCompleted + $script:Stats.PhasesFailed + $script:Stats.PhasesCancelled)) -and
                    ($script:Stats.RootsPlanned -eq ($script:Stats.RootsCompleted + $script:Stats.RootsFailed + $script:Stats.RootsCancelled)))
        } finally { Reset-StSeam; $script:FaultSeam.SkipRealQuickWins = $true; $script:FaultSeam.QuickWinExtraFiles = @() }
        $script:CaptureMode = $true
        Assert-SelfTest -Name 'T133 Fatal mid-scan output failure stops and cancels exactly once' -Condition $t133

        # T134 (case 61): failure constructing mandatory safety exclusions
