        try {
            $script:FaultSeam.SkipRealQuickWins = $true
            $script:FaultSeam.QuickWinExtraFiles = @()
            $script:FaultSeam.ThrowAtOperation = New-StHashSet -Items @('Preflight.Exclusions')
            [void](Invoke-StLifecycle -FullScan $true -Roots @((Get-NormalizedPath -PathValue $isoRoot)) -Files @())
            $t134 = ($script:Stats.PhasesCompleted -eq 3 -and $script:Stats.PhasesFailed -eq 1 -and
                    $script:ExitCode -eq 1)
        } finally { Reset-StSeam; $script:FaultSeam.SkipRealQuickWins = $true; $script:FaultSeam.QuickWinExtraFiles = @() }
        $script:CaptureMode = $true
        Assert-SelfTest -Name 'T134 Exclusion construction failure blocks full scan only' -Condition $t134

        # T135 (case 62): a successful artifact assessment is terminal even
