        Reset-StCounters; Reset-SelfTestCapture
        $kdbxFile = Join-Path $stFixRoot 'art\vault.kdbx'
        Write-StFixtureFile -Path $kdbxFile -Content 'KDBX-binary-ish'
        $kdbxItem = Get-Item -LiteralPath $kdbxFile
        $kdbxCls = Get-FileClassification -FullPath $kdbxFile -Name $kdbxItem.Name -Extension $kdbxItem.Extension -ParentName 'art' -Length ([long]$kdbxItem.Length) -ForceEligible $false
        $findingsBefore135 = $script:CapturedFindings.Count
