        $out135b = Invoke-FileAssessment -FullPath $kdbxFile -Classification $kdbxCls -FromQuickWin $false
        $t135 = ($out135a -eq 'ArtifactReported' -and $out135b -eq 'ArtifactReported' -and
                ($script:CapturedFindings.Count - $findingsBefore135) -eq 1)
        Assert-SelfTest -Name 'T135 Artifact terminal even when dedupe suppresses duplicate' -Condition $t135

        # T136 (case 63): a known GPP cpassword vector decodes correctly through
        # the production function; redacted by default, revealed on request.
        Reset-SelfTestCapture
        $gppKeyHex = '4e9906e8fcb66cc9faf49310620ffee8f496e806cc057990209b09a433b66c1b'
        $gppKeyBytes = New-Object 'byte[]' 32
        for ($i = 0; $i -lt 32; $i++) { $gppKeyBytes[$i] = [Convert]::ToByte($gppKeyHex.Substring($i * 2, 2), 16) }
        $gppPlain = 'GppKnownVector!23'
        $gppBytes = [System.Text.Encoding]::Unicode.GetBytes($gppPlain)
        $gppPad = 16 - ($gppBytes.Length % 16)
        if ($gppPad -gt 0) { $gppPadded = New-Object 'byte[]' ($gppBytes.Length + $gppPad); [Array]::Copy($gppBytes, $gppPadded, $gppBytes.Length) } else { $gppPadded = $gppBytes }
        $gppAes = [System.Security.Cryptography.Aes]::Create()
        $gppAes.Mode = [System.Security.Cryptography.CipherMode]::CBC
        $gppAes.Padding = [System.Security.Cryptography.PaddingMode]::Zeros
        $gppAes.Key = $gppKeyBytes
        $gppAes.IV = (New-Object 'byte[]' 16)
        $gppEnc = $gppAes.CreateEncryptor()
        $gppCipher = $gppEnc.TransformFinalBlock($gppPadded, 0, $gppPadded.Length)
        $gppEnc.Dispose(); $gppAes.Dispose()
        $gppVector = [Convert]::ToBase64String($gppCipher).TrimEnd('=')
        $decodedVector = ConvertFrom-GppCpassword -Cpassword $gppVector
        $t136 = ($decodedVector -eq $gppPlain)
        Assert-SelfTest -Name 'T136 GPP known vector decodes through production function' -Condition $t136

        # T137 (case 64): verify the ADS call boundary without creating,
        # enumerating or reading any alternate stream. Qualification explicitly
        # forbids ADS I/O; source-bound evidence proves all three size branches
        # inherit the bounded local sharing policy from the validated carrier.
        $t137 = $false
        try {
            $source137 = [System.IO.File]::ReadAllText($PSCommandPath)
            $textStart137 = $source137.IndexOf('function Invoke-TextScan {', [StringComparison]::Ordinal)
            $adsStart137 = $source137.IndexOf('function Invoke-CarrierAds {', [StringComparison]::Ordinal)
            $adsEnd137 = $source137.IndexOf('function Invoke-CarrierAdsOnce {', [StringComparison]::Ordinal)
            if ($textStart137 -ge 0 -and $adsStart137 -gt $textStart137 -and $adsEnd137 -gt $adsStart137) {
                $textBody137 = $source137.Substring($textStart137, $adsStart137 - $textStart137)
                $adsBody137 = $source137.Substring($adsStart137, $adsEnd137 - $adsStart137)
                $policyLine137 = '$allowAdsSharingFallback = Test-PathAllowsSharingFallback -PathValue $FullPath'
                $policyUse137 = 'Open-ScanSnapshot -Path $streamPath -AllowPermissiveFallback $allowAdsSharingFallback'
                $t137 = ($adsBody137.IndexOf($policyLine137, [StringComparison]::Ordinal) -ge 0 -and
                    [regex]::Matches($adsBody137, [regex]::Escape($policyUse137)).Count -eq 1 -and
                    $adsBody137.IndexOf('-ExistingStream $adsStream', [StringComparison]::Ordinal) -ge 0 -and
                    $adsBody137.IndexOf('-SnapshotLength $effectiveStreamLength', [StringComparison]::Ordinal) -ge 0 -and
                    $adsBody137.IndexOf('elseif ($effectiveStreamLength -gt $script:MaxFileSizeBytes)', [StringComparison]::Ordinal) -ge 0 -and
                    $adsBody137.IndexOf('Invoke-LargeFileSampleScan', [StringComparison]::Ordinal) -lt 0 -and
                    [regex]::Matches($adsBody137, [regex]::Escape("-CoverageMode 'Sampled'")).Count -eq 2 -and
                    $textBody137.IndexOf('if ($isAdsPath -and $null -eq $ExistingStream -and $StartOffset -ne 0)', [StringComparison]::Ordinal) -ge 0)
            }
        } catch { $t137 = $false }
        Assert-SelfTest -Name 'T137 ADS calls inherit bounded local sharing policy without ADS I/O' -Condition $t137

        # T138 (case 65): known container/key artifacts — including an oversized
        # fixture — are metadata-assessed without oversized content reads.
        Reset-StCounters; Reset-SelfTestCapture
        $ovKey = Join-Path $stFixRoot 'art\big.pem'
        Write-StFixtureFile -Path $ovKey -Content ('-----BEGIN RSA PRIVATE KEY-----' + ('A' * 4096))
        $savedMaxBytes138 = $script:MaxFileSizeBytes
        $savedLargeMode138 = $script:LargeFileModeActive
        $script:MaxFileSizeBytes = 1024
        $script:LargeFileModeActive = 'Skip'
        try {
            $ovItem = Get-Item -LiteralPath $ovKey
            $ovCls = Get-FileClassification -FullPath $ovKey -Name $ovItem.Name -Extension $ovItem.Extension -ParentName 'art' -Length ([long]$ovItem.Length) -ForceEligible $false
            # If the implementation attempts an open, this deterministic seam
            # fails it. The metadata artifact must precede content I/O exactly as
