        try { Invoke-FullScanPhase -Plan @{ Roots = @((Get-NormalizedPath -PathValue $okOnly)); Files = @(); Rejected = @() } } catch { $phaseThrew141 = $true }
        $t141a = (-not $phaseThrew141)   # all complete: no phase failure
        Reset-StCounters
        Add-RootState -Name (Get-NormalizedPath -PathValue $okOnly) -Kind 'Root' -State 'Pending'
        Add-RootState -Name (Join-Path $stFixRoot 'missing-root') -Kind 'Root' -State 'Pending'
        $phaseThrew141b = $false
