        $t141 = ($t141a -and $phaseThrew141b)
        Assert-SelfTest -Name 'T141 Full phase Failed on any root failure; Completed only when all complete' -Condition $t141

        # T142 (case 69): injected interruption during a running phase selects
        # Scan Interrupted, cancels current/remaining exactly once, one partial
        # summary, balanced equations, non-zero exit.
        try {
            $script:FaultSeam.SkipRealQuickWins = $true
            $script:FaultSeam.QuickWinExtraFiles = @()
            $script:FaultSeam.ThrowAtOperation = New-StHashSet -Items @('Interrupt:Phase.FullScan')
            [void](Invoke-StLifecycle -FullScan $true -Roots @((Get-NormalizedPath -PathValue $isoRoot)) -Files @())
            $txt142 = Get-Content -LiteralPath $script:TxtPath -Raw
            $t142 = ($script:Interrupted -and $script:ExitCode -ne 0 -and
                    $txt142 -match 'Scan Interrupted' -and $txt142 -notmatch ([regex]::Escape($script:ToolName + ' - Scan Complete')) -and
                    ($script:Stats.PhasesPlanned -eq ($script:Stats.PhasesCompleted + $script:Stats.PhasesFailed + $script:Stats.PhasesCancelled)) -and
                    ($script:Stats.RootsPlanned -eq ($script:Stats.RootsCompleted + $script:Stats.RootsFailed + $script:Stats.RootsCancelled)))
        } finally { Reset-StSeam; $script:FaultSeam.SkipRealQuickWins = $true; $script:FaultSeam.QuickWinExtraFiles = @() }
        $script:CaptureMode = $true
        Assert-SelfTest -Name 'T142 Interruption: Scan Interrupted, Cancelled exactly once' -Condition $t142

        # T143 (case 70): error-dedup cap: saturation discloses and switches to
        # documented attempt semantics while invariants stay valid.
        Reset-StCounters
        $script:ErrorDedupCap = 3
        try {
            for ($i = 0; $i -lt 5; $i++) {
                Register-ItemError -Key ('FS:C:\cap\file' + $i + '.ini|AccessDenied') -Category 'AccessDenied' -CountNow $true
            }
            $sum143 = Get-SummaryLines -Status 'CoverageIncomplete'
            $t143 = ($script:ErrorDedupSaturated -and $script:Stats.ErrorDedupOverflowEvents -eq 2 -and
                    $script:Stats.AccessDeniedSkipped -eq 5 -and
                    ($script:Stats.UnreadableSkipped -eq ($script:Stats.AccessDeniedSkipped + $script:Stats.OtherUnreadableSkipped)) -and
                    (($sum143 -join "`n") -match 'SATURATED'))
        } finally { $script:ErrorDedupCap = 50000; $script:ErrorDedupSaturated = $false; $script:ErrorDedupSet.Clear() }
        Assert-SelfTest -Name 'T143 Dedup cap: saturation disclosed, attempt semantics' -Condition $t143

        # T144 (case 71): a TXT Close/Dispose failure after successful commits
        # attempts no second summary, keeps the committed TXT valid, and raises
        # a console-only cleanup warning.
        try {
            $script:FaultSeam.SkipRealQuickWins = $true
            $script:FaultSeam.QuickWinExtraFiles = @()
            $script:FaultSeam.OutputFailureAt = 'TxtClose'
            [void](Invoke-StLifecycle -FullScan $false -Roots @() -Files @())
            $txt144 = Get-Content -LiteralPath $script:TxtPath -Raw
            $t144 = ($script:SummaryAttempted -and $script:TxtCommitOk -and
                    $script:Stats.OutputCleanupWarnings -ge 1 -and
                    $txt144 -match ([regex]::Escape($script:ToolName + ' - Scan Complete')) -and $script:ExitCode -eq 0)
        } finally { Reset-StSeam; $script:FaultSeam.SkipRealQuickWins = $true; $script:FaultSeam.QuickWinExtraFiles = @() }
        $script:CaptureMode = $true
        Assert-SelfTest -Name 'T144 TXT cleanup failure after commits: warning only, snapshot valid' -Condition $t144

        # T145 (case 72): TOCTOU disappearance after invocation maps to the
        # retryable partition; pre-invocation rejection changes no denominator.
        Reset-StCounters; Reset-SelfTestCapture
        $toctou = Join-Path $stFixRoot 'toctou\gone.ini'
        Write-StFixtureFile -Path $toctou -Content 'password=ToctouSecret1'
        $toctouNorm = Get-NormalizedPath -PathValue $toctou
        $script:FaultSeam.MissingOpenPaths = New-StHashSet -Items @($toctouNorm)
        try {
            Add-QuickWinFile -PathValue $toctou           # invoked, then "disappears"
            Add-QuickWinFile -PathValue (Join-Path $stFixRoot 'toctou\never.ini')   # rejected pre-invocation
            $realMissing145 = Join-Path $stFixRoot 'toctou\constructor-missing.ini'
            $wrappedMissing145 = Invoke-TextScan -Path $realMissing145 -DisplaySource $realMissing145 -Extension '.ini' -DoRolling $false
            # Opening a directory through New-Object FileStream is not a
            # portable access-denied oracle on WinPS 5.1: some hosts expose it
            # as ObjectNotFound. Inject the normalized native exception so this
            # wrapper contract remains deterministic on both architectures.
            $script:FaultSeam.DenyOpenPaths = New-StHashSet -Items @($stFixRoot)
            $wrappedDenied145 = Invoke-TextScan -Path $stFixRoot -DisplaySource $stFixRoot -Extension '' -DoRolling $false
            $script:FaultSeam.DenyOpenPaths = $null
            $sampleMissing145 = Invoke-LargeFileSampleScan -Path $realMissing145 -DisplaySource $realMissing145 `
                -Extension '.ini' -GrammarPath $realMissing145 -Length 4096 -DoRolling $false
            $t145 = ($script:Stats.QuickWinFilesAssessed -eq 1 -and
                    $script:Stats.QuickWinRetryableFailed -eq 1 -and
                    $wrappedMissing145.Outcome -eq 'Missing' -and
                    $wrappedDenied145.Outcome -eq 'AccessDenied' -and
                    $sampleMissing145.Outcome -eq 'Missing' -and
                    ($script:Stats.QuickWinFilesAssessed -eq ($script:Stats.QuickWinContentCompleted + $script:Stats.QuickWinContentSampled + $script:Stats.QuickWinArtifactsReported + $script:Stats.QuickWinPolicySkipped + $script:Stats.QuickWinRetryableFailed + $script:Stats.QuickWinUnexpectedFailed)))
            if (-not $t145) {
                Write-Host ('[i] T145 diagnostics: assessed={0}; retryable={1}; wrapped-missing={2}; wrapped-denied={3}; sampled-missing={4}; completed={5}; sampled={6}; artifacts={7}; policy={8}; unexpected={9}' -f
                    $script:Stats.QuickWinFilesAssessed, $script:Stats.QuickWinRetryableFailed,
                    $wrappedMissing145.Outcome, $wrappedDenied145.Outcome, $sampleMissing145.Outcome,
                    $script:Stats.QuickWinContentCompleted, $script:Stats.QuickWinContentSampled,
                    $script:Stats.QuickWinArtifactsReported, $script:Stats.QuickWinPolicySkipped,
                    $script:Stats.QuickWinUnexpectedFailed)
            }
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T145 TOCTOU after invocation maps to retryable partition' -Condition $t145

        # T146 (case 73): repeated injected regex timeouts exhaust cumulative
        # budgets after a bounded number of calls; the item is partial, no
        # secret leaks, and the next file is still assessed without real waits.
        Reset-StCounters; Reset-SelfTestCapture
        $toDir = Join-Path $stFixRoot 'timeouts'
        $manyLines = ''
        for ($i = 0; $i -lt 20; $i++) { $manyLines += ('password=TimeoutVictim' + $i + "`r`n") }
        Write-StFixtureFile -Path (Join-Path $toDir 'many.ini') -Content $manyLines
        Write-StFixtureFile -Path (Join-Path $toDir 'next.ini') -Content 'password=AfterTimeoutSecret1'
        $script:FaultSeam.TimeoutPatternIds = New-StHashSet -Items @('KV_PASSWORD')
        try {
            $toItem = Get-Item -LiteralPath (Join-Path $toDir 'many.ini')
            $toCls = Get-FileClassification -FullPath $toItem.FullName -Name $toItem.Name -Extension $toItem.Extension -ParentName 'timeouts' -Length ([long]$toItem.Length) -ForceEligible $false
            $out146 = Invoke-FileAssessment -FullPath $toItem.FullName -Classification $toCls -FromQuickWin $false
            if ($out146 -eq 'BudgetExhausted') { Register-AssessmentCoverageGap -Outcome $out146 }
            $t146 = ($out146 -eq 'BudgetExhausted' -and
                    $script:Stats.RegexTimeoutEvents -ge 2 -and
                    $script:Stats.GapRegexBudget -eq 1 -and
                    $script:ContentCoverageIncomplete)
            if (Test-CapturedLeak -Secret 'TimeoutVictim0') { $t146 = $false }
            Reset-StSeam
            [void](Invoke-DirectoryTraversal -Root $toDir -Purpose Scan -EligibleTotal 2)
            if (-not (Test-CapturedValue -Value 'AfterTimeoutSecret1')) { $t146 = $false }
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T146 Cumulative timeout budgets stop file; next file assessed' -Condition $t146

        # T147 (case 74): the stable read handle rejects a concurrent append,
        # and the original snapshotted content is still scanned exactly once.
        Reset-StCounters; Reset-SelfTestCapture
        $growFile = Join-Path $stFixRoot 'grow\live.log'
        Write-StFixtureFile -Path $growFile -Content ('password=SnapshotSecret5' + "`r`n")
        $script:StGrowOnce = $false
        $script:StGrowBlocked147 = $false
        $script:FaultSeam.OnBlockRead = {
            param($p)
            if (-not $script:StGrowOnce -and $p -eq (Get-NormalizedPath -PathValue $growFile)) {
                $script:StGrowOnce = $true
                try {
                    $appender = New-Object System.IO.FileStream ($p, [System.IO.FileMode]::Append, [System.IO.FileAccess]::Write, [System.IO.FileShare]::ReadWrite)
                    $extra = [System.Text.Encoding]::UTF8.GetBytes("password=AppendedSecret6`r`n")
                    $appender.Write($extra, 0, $extra.Length)
                    $appender.Dispose()
                } catch { $script:StGrowBlocked147 = $true }
            }
        }
        try {
            $growResult = Invoke-TextScan -Path (Get-NormalizedPath -PathValue $growFile) -DisplaySource 'live' -Extension '.log' -DoRolling $false
            $t147 = ($growResult.Outcome -eq 'Completed' -and
                    $script:StGrowOnce -and $script:StGrowBlocked147 -and
                    (Test-CapturedValue -Value 'SnapshotSecret5') -and
                    (-not (Test-CapturedValue -Value 'AppendedSecret6')))
        } finally { Reset-StSeam; $script:StGrowOnce = $false; $script:StGrowBlocked147 = $false }
        Assert-SelfTest -Name 'T147 Stable read handle rejects concurrent append' -Condition $t147

        # T148 (case 75): injected cumulative elapsed-time exhaustion without
        # any RegexMatchTimeoutException stops remaining patterns in the unit,
        # fail-closes the co-located finding, obeys the file budget, and still
        # reaches the next unit/file.
        Reset-StCounters; Reset-SelfTestCapture
        $elapsedContent = ''
        for ($i = 0; $i -lt 8; $i++) { $elapsedContent += ('cpassword="fAKECIPHER0123=abcdef" password=ElapsedCoLocated1' + "`r`n") }
        Write-StFixtureFile -Path (Join-Path $toDir 'elapsed.ini') -Content $elapsedContent
        Write-StFixtureFile -Path (Join-Path $toDir 'elapsednext.ini') -Content 'password=ElapsedNextFile1'
        $script:FaultSeam.RegexElapsedAddMs = 2000
        try {
            $elItem = Get-Item -LiteralPath (Join-Path $toDir 'elapsed.ini')
            $elCls = Get-FileClassification -FullPath $elItem.FullName -Name $elItem.Name -Extension $elItem.Extension -ParentName 'timeouts' -Length ([long]$elItem.Length) -ForceEligible $false
            $out148 = Invoke-FileAssessment -FullPath $elItem.FullName -Classification $elCls -FromQuickWin $false
            if ($out148 -eq 'BudgetExhausted') { Register-AssessmentCoverageGap -Outcome $out148 }
            $t148 = ($out148 -eq 'BudgetExhausted' -and $script:Stats.RegexTimeoutEvents -eq 0 -and
                    $script:Stats.GapRegexBudget -eq 1 -and
                    $script:ContentCoverageIncomplete)
            foreach ($c in $script:CapturedFindings) {
                if ($c.Context -ne '[context-redacted:regex-timeout]') { $t148 = $false }
            }
            if (Test-CapturedLeak -Secret 'ElapsedCoLocated1') { $t148 = $false }
            Reset-StSeam
            [void](Invoke-DirectoryTraversal -Root $toDir -Purpose Scan -EligibleTotal 2)
            if (-not (Test-CapturedValue -Value 'ElapsedNextFile1')) { $t148 = $false }
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T148 Elapsed-time budget exhaustion without timeout exception' -Condition $t148

        # ==================== v4.1.2 regression suite (T149+) =================

        # T149 (§2): 10,000 synthetic terminal files through the REAL traversal
        # branch produce zero TerminalAssessedPaths growth (bounded memory).
        Reset-StCounters; Reset-SelfTestCapture
        $script:FaultSeam.AssessmentOverride = 'ContentCompleted'
        $script:FaultSeam.EnumHandler = {
            param($dir, $emit, $consumerState)
            if ($dir.EndsWith('memroot', [System.StringComparison]::OrdinalIgnoreCase)) {
                for ($mi = 0; $mi -lt 10000; $mi++) {
                    $memItem = [pscustomobject]@{
                        PSIsContainer = $false
                        FullName      = ($dir + '\f' + $mi + '.ini')
                        Name          = ('f' + $mi + '.ini')
                        Extension     = '.ini'
                        DirectoryName = $dir
                        Length        = [long]10
                        Attributes    = [System.IO.FileAttributes]::Normal
                    }
                    & $emit $memItem | Out-Null
                }
                return @{ Items = @(); Errors = (New-Object System.Collections.Generic.List[object]); EnumerationStarted = $true; EnumerationCompleted = $true; TopLevelFatal = $false }
            }
            return $null
        }
        try {
            $termBefore149 = $script:TerminalAssessedPaths.Count
            [void](Invoke-DirectoryTraversal -Root (Join-Path $stFixRoot 'memroot') -Purpose Scan -EligibleTotal 10000)
            $t149 = ($script:Stats.FullScanAssessed -eq 10000 -and
                    $script:Stats.FullScanContentCompleted -eq 10000 -and
                    ($script:Stats.FullScanReadFailed + $script:Stats.FullScanUnexpectedFailed) -eq 0 -and
                    ($script:Stats.AccessDeniedSkipped + $script:Stats.OtherUnreadableSkipped) -eq 0 -and
                    ($script:TerminalAssessedPaths.Count - $termBefore149) -eq 0)
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T149 10k terminal descendants: zero drive-wide set growth' -Condition $t149

        # T150 (§2/§8-tests): automatic-root overlap elimination, boundary-aware.
        Reset-StCounters; Reset-SelfTestCapture
        $ovParent = Join-Path $stFixRoot 'ovroot'
        $ovChild = Join-Path $ovParent 'child'
        $ovSibling = Join-Path $stFixRoot 'ovroot2'
        New-Item -ItemType Directory -Path $ovChild -Force | Out-Null
        New-Item -ItemType Directory -Path $ovSibling -Force | Out-Null
        $ovParentNorm = Get-NormalizedPath -PathValue $ovParent
        $ovChildNorm = Get-NormalizedPath -PathValue $ovChild
        $ovSiblingNorm = Get-NormalizedPath -PathValue $ovSibling
        # Two custom PSDrive roots (parent + child) plus a sibling sharing only
        # a name prefix: parent covers child; sibling stays distinct.
        $script:FaultSeam.DriveList = @(
            @{ Name = 'CH0'; Root = $ovParentNorm; DisplayRoot = '' },
            @{ Name = 'CH1'; Root = $ovChildNorm; DisplayRoot = '' },
            @{ Name = 'CH2'; Root = $ovSiblingNorm; DisplayRoot = '' }
        )
        try {
            $savedPath150 = $script:Path
            $script:Path = @()
            $plan150 = Get-ScanPlan
            $script:Path = $savedPath150
            $hasParent = $false; $hasChild = $false; $hasSibling = $false
            foreach ($pr in $plan150.Roots) {
                if ($pr -eq $ovParentNorm) { $hasParent = $true }
                if ($pr -eq $ovChildNorm) { $hasChild = $true }
                if ($pr -eq $ovSiblingNorm) { $hasSibling = $true }
            }
            $t150 = ($hasParent -and (-not $hasChild) -and $hasSibling)
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T150 Auto-root overlap: parent covers child, sibling prefix distinct' -Condition $t150

        # T150b: UNC auto roots honored/excluded by IncludeNetworkDrives; pure
        # boundary coverage proven for UNC parent/child and distinct shares.
        $script:FaultSeam.DriveList = @(
            @{ Name = 'N1'; Root = '\\srv\share'; DisplayRoot = '\\srv\share' }
        )
        try {
            $savedPath150b = $script:Path; $script:Path = @()
            $savedNet150 = $script:NetworkDrivesAllowed
            $script:NetworkDrivesAllowed = $false
            $plan150off = Get-ScanPlan
            $script:NetworkDrivesAllowed = $savedNet150
            $script:Path = $savedPath150b
            $t150b = ($plan150off.Roots.Count -eq 0)   # UNC excluded without the switch
            if (-not (Test-RootCovered -Candidate '\\srv\share\sub' -Other '\\srv\share')) { $t150b = $false }
            if (Test-RootCovered -Candidate '\\other\share' -Other '\\srv\share') { $t150b = $false }
            if (Test-RootCovered -Candidate 'C:\Database' -Other 'C:\Data') { $t150b = $false }
            if (-not (Test-RootCovered -Candidate 'C:\Users' -Other 'C:\')) { $t150b = $false }
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T150b UNC gating and boundary-aware coverage proofs' -Condition $t150b

        # T151 (§3): a TOCTOU-missing descendant sets a truthful gap and never
        # stops a later sibling credential or a later root.
        Reset-StCounters; Reset-SelfTestCapture
        $gapRootA = Join-Path $stFixRoot 'gapA'
        $gapRootB = Join-Path $stFixRoot 'gapB'
        Write-StFixtureFile -Path (Join-Path $gapRootA 'gone.ini') -Content 'password=GoneRace1'
        Write-StFixtureFile -Path (Join-Path $gapRootA 'later.ini') -Content 'password=LaterSiblingSecret1'
        Write-StFixtureFile -Path (Join-Path $gapRootB 'b.ini') -Content 'password=GapRootBSecret1'
        $goneNorm = Get-NormalizedPath -PathValue (Join-Path $gapRootA 'gone.ini')
        $script:FaultSeam.MissingOpenPaths = New-StHashSet -Items @($goneNorm)
        try {
            Add-RootState -Name (Get-NormalizedPath -PathValue $gapRootA) -Kind 'Root' -State 'Pending'
            Add-RootState -Name (Get-NormalizedPath -PathValue $gapRootB) -Kind 'Root' -State 'Pending'
            try { Invoke-FullScanPhase -Plan @{ Roots = @((Get-NormalizedPath -PathValue $gapRootA), (Get-NormalizedPath -PathValue $gapRootB)); Files = @(); Rejected = @() } } catch { }
            $t151 = ($script:ContentCoverageIncomplete -and
                    $script:Stats.GapToctouMissing -eq 1 -and
                    (Test-CapturedValue -Value 'LaterSiblingSecret1') -and
                    (Test-CapturedValue -Value 'GapRootBSecret1'))
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T151 TOCTOU descendant: gap set, sibling and later root found' -Condition $t151

        # T152 (§7): inventory races (addition AND removal) set InventoryChanged
        # gap, keep going, and still emit the later finding.
        Reset-StCounters; Reset-SelfTestCapture
        $raceRoot = Join-Path $stFixRoot 'invrace'
        Write-StFixtureFile -Path (Join-Path $raceRoot 'one.ini') -Content 'password=InvRaceOne1'
        Write-StFixtureFile -Path (Join-Path $raceRoot 'two.ini') -Content 'password=InvRaceTwo2'
        # Addition race: Count sees nothing, Scan sees the real files.
        $script:StInvCalls = 0
        $script:FaultSeam.EnumHandler = {
            param($dir)
            if ($dir.EndsWith('invrace', [System.StringComparison]::OrdinalIgnoreCase)) {
                $script:StInvCalls++
                if ($script:StInvCalls -eq 1) {
                    return @{ Items = @(); Errors = (New-Object System.Collections.Generic.List[object]); EnumerationStarted = $true; EnumerationCompleted = $true; TopLevelFatal = $false }
                }
            }
            return $null
        }
        try {
            Add-RootState -Name (Get-NormalizedPath -PathValue $raceRoot) -Kind 'Root' -State 'Pending'
            try { Invoke-FullScanPhase -Plan @{ Roots = @((Get-NormalizedPath -PathValue $raceRoot)); Files = @(); Rejected = @() } } catch { }
            $t152a = ($script:InventoryChanged -and $script:Stats.GapInventoryMismatch -ge 1 -and
                     $script:ContentCoverageIncomplete -and (Test-CapturedValue -Value 'InvRaceOne1'))
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T152a Inventory addition race: explicit gap, finding still emitted' -Condition $t152a
        # Removal race: Count sees both files, Scan sees only one.
        Reset-StCounters; Reset-SelfTestCapture
        $script:StInvCalls = 0
        $script:FaultSeam.EnumHandler = {
            param($dir, $emit, $consumerState)
            if ($dir.EndsWith('invrace', [System.StringComparison]::OrdinalIgnoreCase)) {
                $script:StInvCalls++
                if ($script:StInvCalls -eq 2) {
                    $oneItem = Get-Item -LiteralPath (Join-Path $dir 'one.ini') -Force -ErrorAction SilentlyContinue
                    if ($null -ne $oneItem) { & $emit $oneItem | Out-Null }
                    return @{ Items = @(); Errors = (New-Object System.Collections.Generic.List[object]); EnumerationStarted = $true; EnumerationCompleted = $true; TopLevelFatal = $false }
                }
            }
            return $null
        }
        try {
            Add-RootState -Name (Get-NormalizedPath -PathValue $raceRoot) -Kind 'Root' -State 'Pending'
            try { Invoke-FullScanPhase -Plan @{ Roots = @((Get-NormalizedPath -PathValue $raceRoot)); Files = @(); Rejected = @() } } catch { }
            $t152b = ($script:InventoryChanged -and (Test-CapturedValue -Value 'InvRaceOne1'))
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T152b Inventory removal race: explicit gap, finding still emitted' -Condition $t152b

        # T153 (§4): late CP1252 byte after >8 KiB of ASCII triggers exactly one
        # bounded ANSI retry; credential found; terminal Completed; no gap.
        Reset-StCounters; Reset-SelfTestCapture
        $ansiFile = Join-Path $stFixRoot 'enc2\lateansi.txt'
        [void][System.IO.Directory]::CreateDirectory((Join-Path $stFixRoot 'enc2'))
        $ansiBytes = New-Object 'System.Collections.Generic.List[byte]'
        foreach ($b in [System.Text.Encoding]::ASCII.GetBytes(('A' * 9000))) { $ansiBytes.Add($b) }
        $ansiBytes.Add(0xE9)
        foreach ($b in [System.Text.Encoding]::ASCII.GetBytes("`r`npassword=LateAnsiSecret9")) { $ansiBytes.Add($b) }
        [System.IO.File]::WriteAllBytes($ansiFile, $ansiBytes.ToArray())
        $ansiResult = Invoke-TextScan -Path $ansiFile -DisplaySource $ansiFile -Extension '.txt' -DoRolling $false
        $t153 = ($ansiResult.Outcome -eq 'Completed' -and
                (Test-CapturedValue -Value 'LateAnsiSecret9') -and
                (-not $script:ContentCoverageIncomplete))
        Assert-SelfTest -Name 'T153 Late ANSI byte: single bounded retry finds credential, terminal' -Condition $t153

        # T153b: a genuine regex timeout gap persists even when the ANSI retry
        # completes successfully.
        Reset-StCounters; Reset-SelfTestCapture
        $script:FaultSeam.TimeoutPatternIds = New-StHashSet -Items @('KV_PASSWORD')
        try {
            $ansiResult2 = Invoke-TextScan -Path $ansiFile -DisplaySource $ansiFile -Extension '.txt' -DoRolling $false
            $t153b = ($ansiResult2.Outcome -eq 'Completed' -and $script:ContentCoverageIncomplete -and
                    $script:Stats.RegexTimeoutEvents -ge 1 -and
                    (-not (Test-CapturedValue -Value 'LateAnsiSecret9')))
        } finally { Reset-StSeam }
        Assert-SelfTest -Name 'T153b ANSI retry success never clears genuine regex gap' -Condition $t153b

        # T154 (§5): ADS through the production full-traversal control flow for
        # every carrier type, each invoked exactly once. Capability-aware.
        # The v4.2.4 qualification contract forbids every ADS create/enumerate/
        # read operation. Keep the historical integration body unreachable and
        # replace its four IDs with source-bound contract checks; this preserves
        # the test plan and proves routing/taxonomy without touching a stream.
        $runAdsIoSelfTests = $false
        if (-not $runAdsIoSelfTests) {
            $adsSource154 = [System.IO.File]::ReadAllText($PSCommandPath)
            $carrierStart154 = $adsSource154.IndexOf('function Invoke-CarrierAds {', [StringComparison]::Ordinal)
            $onceStart154 = $adsSource154.IndexOf('function Invoke-CarrierAdsOnce {', [StringComparison]::Ordinal)
            $rangesStart154 = $adsSource154.IndexOf('function Get-LargeFileSampleRanges {', [StringComparison]::Ordinal)
            $textScanStart154 = $adsSource154.IndexOf('function Invoke-TextScan {', [StringComparison]::Ordinal)
            $quickStart154 = $adsSource154.IndexOf('function Add-QuickWinFile {', [StringComparison]::Ordinal)
            $quickEnd154 = $adsSource154.IndexOf('function Add-QuickWinArtifact {', [StringComparison]::Ordinal)
            $suppliedStart154 = $adsSource154.IndexOf('function Invoke-SuppliedFiles {', [StringComparison]::Ordinal)
            $suppliedEnd154 = $adsSource154.IndexOf('function Invoke-FullScanPhase {', [StringComparison]::Ordinal)

            $carrierBody154 = ''
            $onceBody154 = ''
            $textScanBody154 = ''
            $quickBody154 = ''
            $suppliedBody154 = ''
            if ($carrierStart154 -ge 0 -and $onceStart154 -gt $carrierStart154) {
                $carrierBody154 = $adsSource154.Substring($carrierStart154, $onceStart154 - $carrierStart154)
            }
            if ($onceStart154 -ge 0 -and $rangesStart154 -gt $onceStart154) {
                $onceBody154 = $adsSource154.Substring($onceStart154, $rangesStart154 - $onceStart154)
            }
            if ($textScanStart154 -ge 0 -and $carrierStart154 -gt $textScanStart154) {
                $textScanBody154 = $adsSource154.Substring($textScanStart154, $carrierStart154 - $textScanStart154)
            }
            if ($quickStart154 -ge 0 -and $quickEnd154 -gt $quickStart154) {
                $quickBody154 = $adsSource154.Substring($quickStart154, $quickEnd154 - $quickStart154)
            }
            if ($suppliedStart154 -ge 0 -and $suppliedEnd154 -gt $suppliedStart154) {
                $suppliedBody154 = $adsSource154.Substring($suppliedStart154, $suppliedEnd154 - $suppliedStart154)
            }

            $t154 = ($carrierBody154.Length -gt 0 -and
                $carrierBody154.IndexOf('if (-not $script:IsDeepMode -or -not $script:IncludeAdsActive) { return }', [StringComparison]::Ordinal) -ge 0 -and
                $carrierBody154.IndexOf("if (`$streamName -eq ':`$DATA') { continue }", [StringComparison]::Ordinal) -ge 0 -and
                $carrierBody154.IndexOf('Zone.Identifier', [StringComparison]::Ordinal) -ge 0 -and
                [regex]::Matches($carrierBody154, [regex]::Escape('Open-ScanSnapshot -Path $streamPath -AllowPermissiveFallback $allowAdsSharingFallback')).Count -eq 1 -and
                $carrierBody154.IndexOf('-ExistingStream $adsStream', [StringComparison]::Ordinal) -ge 0 -and
