                (Test-CapturedValue -Value 'Str0ng!Passw0rd') -and (Test-CapturedValue -Value 'J;son,(Val)ue') -and
                (Test-CapturedValue -Value 'yam;l,v[a]l'))
        $uncertain = $false
        foreach ($c in $script:CapturedFindings) {
            if ($c.RawValue -eq 'abc;def=ghi' -and $c.Confidence -eq 'Low' -and $c.Notes -match 'ValueBoundaryUncertain') { $uncertain = $true }
            if ($c.RawValue -eq 'abc') { $t162 = $false }   # confidently wrong truncation
        }
        if (-not $uncertain) { $t162 = $false }
        Assert-SelfTest -Name 'T162 Punctuation preserved; connstr boundary; uncertain marked' -Condition $t162

        # T163 (§8): Deep content-probes a misnamed .crt holding private-key
        # material while a normal public certificate yields zero findings;
        # Standard rolling matches a multiline nested credential in a non-Quick
        # structured file.
        Reset-StCounters; Reset-SelfTestCapture
        $certRoot = Join-Path $stFixRoot 'certroot'
