        Write-StFixtureFile -Path (Join-Path $certRoot 'public.crt') -Content ("-----BEGIN CERTIFICATE-----`r`nMIIBIjANBgkqhkiG9w0BAQEFAAOCAQ8A")
        Write-StFixtureFile -Path (Join-Path $certRoot 'nested.xml') -Content ("<unattend>`r`n<AutoLogon>`r`n<Password>`r`n  <Value>StdNestedSecret1</Value>`r`n</Password>`r`n</AutoLogon>")
        $savedDeep163 = $script:IsDeepMode
