        # T164 (§9.1): pgpass production scan/output proves exact raw-span
        # redaction; a non-pgpass basename with identical content must not emit
        # PGPASS_CRED. The common opt-in branch is source-pinned without running
        # a plaintext lifecycle during qualification.
        $pgRoot164 = Join-Path $stFixRoot 'pgpass164'
        $pgFile164 = Join-Path $pgRoot164 'custom-credentials.data'
        $pgNoise164 = Join-Path $pgRoot164 'notes.txt'
        $pgRaw164 = 'P@ss\:w0rd\\x'
        $pgDecoded164 = 'P@ss:w0rd\x'
        Write-StFixtureFile -Path $pgFile164 -Content ('dbhost:5432:appdb:deploy:' + $pgRaw164)
        Write-StFixtureFile -Path $pgNoise164 -Content ('dbhost:5432:appdb:deploy:' + $pgRaw164)
        # Provider enumeration may expand an 8.3 TEMP spelling to the long
        # FullName.  Compare the emitted source with that provider identity,
        # not with the original Join-Path spelling.
        $pgFile164Actual = (Get-Item -LiteralPath $pgFile164 -ErrorAction Stop).FullName
        $savedPgpassEnv164 = [Environment]::GetEnvironmentVariable('PGPASSFILE', 'Process')
        $savedReveal164 = $script:RevealActive
        $t164 = $true
        try {
            [Environment]::SetEnvironmentVariable('PGPASSFILE', $pgFile164, 'Process')
            $script:FaultSeam.SkipRealQuickWins = $true
            $script:FaultSeam.QuickWinExtraFiles = @()
            # Exact source/count must not depend on a real host PGPASSFILE or
            # registry credential.  The production phase runner still handles
            # these injected phase failures and continues into FullScan.
            $script:FaultSeam.ThrowAtOperation = New-StHashSet -Items @('Phase.Registry')
            $script:RevealActive = $false
            [void](Invoke-StLifecycle -FullScan $true -Roots @((Get-NormalizedPath -PathValue $pgRoot164)) -Files @())
            $txt164a = [System.IO.File]::ReadAllText($script:TxtPath)
            $csv164a = [System.IO.File]::ReadAllText($script:CsvPath)
            $rows164a = @([System.IO.File]::ReadAllLines($script:CsvPath) | Where-Object {
                $_ -match 'PGPASS_CRED' -and $_ -match [regex]::Escape($pgFile164Actual)
            })
            if ($rows164a.Count -ne 1 -or $txt164a.Contains($pgDecoded164) -or $csv164a.Contains($pgDecoded164) -or
                $txt164a.Contains($pgRaw164) -or $csv164a.Contains($pgRaw164) -or
                -not $script:PgpassGrammarPaths.Contains($pgFile164Actual)) { $t164 = $false }

            if (-not $revealContractSource.Contains('$displayValue = ConvertTo-SafeText -Text $rawValue')) { $t164 = $false }
        } finally {
            [Environment]::SetEnvironmentVariable('PGPASSFILE', $savedPgpassEnv164, 'Process')
            $script:RevealActive = $savedReveal164
            $script:CaptureMode = $true
            Reset-StSeam
            $script:FaultSeam.SkipRealQuickWins = $true; $script:FaultSeam.QuickWinExtraFiles = @()
        }
        Assert-SelfTest -Name 'T164 pgpass end-to-end redaction; RevealSecrets branch source-pinned' -Condition $t164

        # T165 (§9.2): exact one-row output and exact source-path gating.
        $vaultRoot165 = Join-Path $stFixRoot 'vault165'
        $vaultFile165 = Join-Path $vaultRoot165 '.vault-token'
