        Write-StFixtureFile -Path $vaultNoise165 -Content $vaultValue165
        $vaultFile165Actual = (Get-Item -LiteralPath $vaultFile165 -ErrorAction Stop).FullName
        $vaultNoise165Actual = (Get-Item -LiteralPath $vaultNoise165 -ErrorAction Stop).FullName
        $savedReveal165 = $script:RevealActive
        try {
            $script:FaultSeam.SkipRealQuickWins = $true
