            # Keep the exact-one assertion independent of real host metadata;
            # the lifecycle and FullScan paths remain production paths.
            $script:FaultSeam.ThrowAtOperation = New-StHashSet -Items @('Phase.Environment','Phase.Registry')
            $script:RevealActive = $false
            [void](Invoke-StLifecycle -FullScan $true -Roots @((Get-NormalizedPath -PathValue $vaultRoot165)) -Files @())
            $vaultRows165 = @([System.IO.File]::ReadAllLines($script:CsvPath) | Where-Object { $_ -match 'VAULT_TOKEN_FILE' })
            $t165 = ($vaultRows165.Count -eq 1 -and
