        # T167 (§9.4): quoted netrc passwords with filename gating.
        Reset-SelfTestCapture
        [void](Add-TextFindings -Text 'machine ftp.example.com login deploy password "Netrc Quoted 1"' -BaseLine 1 -Source 'C:\selftest\.netrc' -FilePath 'C:\selftest\.netrc')
        [void](Add-TextFindings -Text 'machine ftp.example.com login deploy password "Netrc Quoted 1"' -BaseLine 1 -Source 'C:\selftest\notes.txt' -FilePath 'C:\selftest\notes.txt')
        $t167 = ((Test-CapturedValue -Value 'Netrc Quoted 1') -and ($script:CapturedFindings.Count -eq 1))
        Assert-SelfTest -Name 'T167 Quoted netrc password with gating' -Condition $t167

        # T168 (§9.4): Kubernetes exec credential split across bounded YAML list
