        Write-StFixtureFile -Path (Join-Path $prof169 '.ssh\custom_backup_key') -Content '-----BEGIN OPENSSH PRIVATE KEY-----'
        Write-StFixtureFile -Path (Join-Path $prof169 '.ssh\known_hosts') -Content 'host ssh-rsa AAAAB3NzaFakeKeyMaterial111'
        Write-StFixtureFile -Path (Join-Path $prof169 '.ssh\config') -Content 'Host example'
        Write-StFixtureFile -Path (Join-Path $prof169 '.ssh\id_rsa.pub') -Content 'ssh-rsa AAAAB3NzaFakePubKey222'
        $savedProfiles169 = New-Object System.Collections.Generic.List[string]
        foreach ($p in $script:UserProfiles) { $savedProfiles169.Add($p) }
        $savedSR169 = $env:SystemRoot; $savedSD169 = $env:SystemDrive; $savedPD169 = $env:ProgramData
        $script:UserProfiles.Clear(); $script:UserProfileSet.Clear()
        [void]$script:UserProfiles.Add((Get-NormalizedPath -PathValue $prof169))
        $env:SystemRoot = ''; $env:SystemDrive = ''; $env:ProgramData = ''
        try {
