        # T170 (§9.6): command-specific plaintext forms and negatives.
        Reset-SelfTestCapture
        [void](Add-TextFindings -Text 'ConvertTo-SecureString "SecStrCmd1!" -AsPlainText -Force' -BaseLine 1 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'ConvertTo-SecureString -AsPlainText -Force "SecStrCmd2!"' -BaseLine 2 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
