        [void](Add-TextFindings -Text 'cmdkey /add:srv01 /pass:/CmdkeySecret3 /generic:TERMSRV/srv01 /user:admin' -BaseLine 3 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'schtasks /create /rp -SchtasksSecret4 /f /tn task /tr x.exe /ru corp\svc' -BaseLine 4 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'sqlcmd.exe -P /SqlcmdSecret5 -S db01 -l 30 -U sa' -BaseLine 5 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'psexec64.exe \\web01 -p -PsexecSecret6 -accepteula -n 10 -u corp\admin' -BaseLine 6 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'net user helpdesk /NetUserSecret7 /comment:"service account" /add /domain' -BaseLine 7 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'net user operator -NetUserSecret8 /expires:never /add' -BaseLine 8 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'net use Z: \\srv\share "Net Use Secret 9" /persistent:no /user:corp\svc' -BaseLine 9 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'net use \\srv\share /persistent:no /user:corp\svc /NetUseSecret10' -BaseLine 10 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'sqlcmd -?' -BaseLine 11 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'somecli -p' -BaseLine 12 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'net user /domain' -BaseLine 13 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'net user guest /active:no' -BaseLine 14 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        # Options from separate shell commands must never be paired, while a
        # quoted separator remains part of a legitimate credential value.
        [void](Add-TextFindings -Text 'sqlcmd -U sa ; echo -P CrossCommandNoise11' -BaseLine 15 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'net use \\srv\share /user:corp\svc | echo CrossCommandNoise12' -BaseLine 16 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'net user obsolete NotACredential13 /delete' -BaseLine 17 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        [void](Add-TextFindings -Text 'sqlcmd -U sa -P "Quoted;Password14"' -BaseLine 18 -Source 'C:\selftest\h.txt' -FilePath 'C:\selftest\h.txt')
        $t170 = ((Test-CapturedValue -Value 'SecStrCmd1!') -and (Test-CapturedValue -Value 'SecStrCmd2!') -and
                (Test-CapturedValue -Value '/CmdkeySecret3') -and (Test-CapturedValue -Value '-SchtasksSecret4') -and
                (Test-CapturedValue -Value '/SqlcmdSecret5') -and (Test-CapturedValue -Value '-PsexecSecret6') -and
                (Test-CapturedValue -Value '/NetUserSecret7') -and (Test-CapturedValue -Value '-NetUserSecret8') -and
                (Test-CapturedValue -Value 'Net Use Secret 9') -and (Test-CapturedValue -Value '/NetUseSecret10'))
        $t170 = ($t170 -and (Test-CapturedValue -Value 'Quoted;Password14'))
