        $fakeTree['LocalMachine|Registry64'] = $lmRoot
        $lmSoftware = & $newFakeRegistryNode
        $lmRoot.SubKeys['SOFTWARE'] = $lmSoftware
        $orl = & $newFakeRegistryNode
        $lmSoftware.SubKeys['ORL'] = $orl
