        $cuSoftware.SubKeys['SimonTatham'] = $simon
        $putty = & $newFakeRegistryNode
        $simon.SubKeys['PuTTY'] = $putty
        $puttySessions = & $newFakeRegistryNode
        $putty.SubKeys['Sessions'] = $puttySessions
        $puttyProd = & $newFakeRegistryNode
        $puttyProd.Values['HostName'] = 'p.example'
        $puttyProd.Values['UserName'] = 'puttyuser'
        $puttyProd.Values['Password'] = 'PuttyPlantedSecret1'
        $puttySessions.SubKeys['prod'] = $puttyProd

        $martin = & $newFakeRegistryNode
        $cuSoftware.SubKeys['Martin Prikryl'] = $martin
        $winScp = & $newFakeRegistryNode
        $martin.SubKeys['WinSCP 2'] = $winScp
        $winScpSessions = & $newFakeRegistryNode
        $winScp.SubKeys['Sessions'] = $winScpSessions
        $winScpMain = & $newFakeRegistryNode
        $winScpMain.Values['HostName'] = 'w.example'
        $winScpMain.Values['UserName'] = 'scpuser'
        $winScpMain.Values['Password'] = 'WinScpPlantedSecret2'
