        $cuSoftware.SubKeys['Microsoft'] = $microsoft
        $windows = & $newFakeRegistryNode
        $microsoft.SubKeys['Windows'] = $windows
        $currentVersion = & $newFakeRegistryNode
        $windows.SubKeys['CurrentVersion'] = $currentVersion
        $run = & $newFakeRegistryNode
