        $run.ValueKinds['Updater'] = 'ExpandString'
        $run.Values['Multi'] = [string[]]@('one', 'password=RunMultiSecret4')
        $run.ValueKinds['Multi'] = 'MultiString'
        $currentVersion.SubKeys['Run'] = $run

