                    (Test-CapturedValue -Value 'SvcPlantedSecret9') -and
                    (Test-CapturedValue -Value 'RunPlantedSecret3') -and
                    (Test-CapturedValue -Value 'RunMultiSecret4') -and
                    $script:Stats.AccessDeniedSkipped -ge 1 -and
                    $script:Stats.RegistryDeniedOperations -ge 1 -and
                    (-not $script:CoverageIncomplete) -and $script:ContentCoverageIncomplete -and
                    ($script:FaultSeam.RegOpenAttempts -ge $script:FaultSeam.RegOpenSucceeded) -and
                    ($script:FaultSeam.RegOpenSucceeded -eq $script:FaultSeam.RegCloseSucceeded) -and
