        # disabling per-window binary probes. A later invalid UTF-8 byte gets
        # one successful ANSI retry, a NUL-dominated window is skipped, a magic
        # token at an arbitrary window boundary stays text, and the final text
        # window remains searchable.
        Reset-StCounters; Reset-SelfTestCapture
        $mixedPath202 = Join-Path $stFixRoot 'large\mixed-encoding202.log'
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($mixedPath202))
        $mixedBytes202 = New-Object 'byte[]' 5000
        for ($byteIndex202 = 0; $byteIndex202 -lt $mixedBytes202.Length; $byteIndex202++) { $mixedBytes202[$byteIndex202] = 0x41 }
        $mixedBytes202[1200] = 0xE9
        $mixedBytes202[1201] = 0x0A
        $ansiLine202 = [System.Text.Encoding]::ASCII.GetBytes("password=AnsiWindowSecret202`r`n")
        [Array]::Copy($ansiLine202, 0, $mixedBytes202, 1202, $ansiLine202.Length)
        for ($nulIndex202 = 2400; $nulIndex202 -lt 2450; $nulIndex202++) { $mixedBytes202[$nulIndex202] = 0x00 }
        # The first disconnected line is intentionally partial and ignored;
        # the complete following line proves the whole window was not discarded
        # merely because its first physical bytes resemble a file header.
        $magicText202 = [System.Text.Encoding]::ASCII.GetBytes("%PDF-text-not-a-header`r`npassword=MagicTextSecret202`r`n")
        [Array]::Copy($magicText202, 0, $mixedBytes202, 3600, $magicText202.Length)
        $mixedBytes202[4800] = 0x0A
        $tailLine202 = [System.Text.Encoding]::ASCII.GetBytes("password=TailAfterBinary202`r`n")
        [Array]::Copy($tailLine202, 0, $mixedBytes202, 4801, $tailLine202.Length)
        [System.IO.File]::WriteAllBytes($mixedPath202, $mixedBytes202)
        $mixedItem202 = Get-Item -LiteralPath $mixedPath202
        $mixedClass202 = Get-FileClassification -FullPath $mixedItem202.FullName -Name $mixedItem202.Name `
            -Extension $mixedItem202.Extension -ParentName 'large' -Length ([long]$mixedItem202.Length) -ForceEligible $false
        $savedMax202 = $script:MaxFileSizeBytes
        $savedLargeMode202 = $script:LargeFileModeActive
        $t202 = $false
        try {
            $script:MaxFileSizeBytes = 1000
            $script:LargeFileModeActive = 'Sample'
            $out202 = Invoke-FileAssessment -FullPath $mixedItem202.FullName -Classification $mixedClass202 -FromQuickWin $false
            $t202 = ($out202 -eq 'ContentSampled' -and
                    (Test-CapturedValue -Value 'AnsiWindowSecret202') -and
                    (Test-CapturedValue -Value 'MagicTextSecret202') -and
                    (Test-CapturedValue -Value 'TailAfterBinary202') -and
                    $script:Stats.GapReadDecodeFailed -eq 0 -and
                    $script:Stats.GapLargeFileSampled -eq 1 -and
                    $script:Stats.BinarySkipped -eq 1 -and
                    $script:Stats.GapUnsupportedFormat -eq 1)
        } finally {
            $script:MaxFileSizeBytes = $savedMax202
            $script:LargeFileModeActive = $savedLargeMode202
        }
        Assert-SelfTest -Name 'T202 Sample windows retain ANSI fallback and offset-safe binary probes' -Condition $t202

        # T203: an explicit npm/pgpass override remains authoritative when the
        # physical file has a backup suffix and classification supplies an
        # effective grammar path with that wrapper removed.
        Reset-StCounters; Reset-SelfTestCapture
        $npmPhysical203 = Get-NormalizedPath -PathValue (Join-Path $stFixRoot 'overrides\npm-custom.ini.bak')
        $pgPhysical203 = Get-NormalizedPath -PathValue (Join-Path $stFixRoot 'overrides\pg-custom.data.old')
        [void]$script:NpmrcGrammarPaths.Add($npmPhysical203)
        [void]$script:PgpassGrammarPaths.Add($pgPhysical203)
        $npmClass203 = Get-FileClassification -FullPath $npmPhysical203 -Name 'npm-custom.ini.bak' `
            -Extension '.bak' -ParentName 'overrides' -Length 100 -ForceEligible $true
        $pgClass203 = Get-FileClassification -FullPath $pgPhysical203 -Name 'pg-custom.data.old' `
            -Extension '.old' -ParentName 'overrides' -Length 100 -ForceEligible $true
        [void](Add-TextFindings -Text '_authToken="NpmBackupOverride203"' -BaseLine 1 `
            -Source $npmPhysical203 -FilePath $npmPhysical203 -GrammarPath $npmClass203.GrammarPath)
        [void](Add-TextFindings -Text 'pg203.example.test:5433:app:deploy:PgBackupOverride203' -BaseLine 1 `
            -Source $pgPhysical203 -FilePath $pgPhysical203 -GrammarPath $pgClass203.GrammarPath)
        $npmCollision203 = Get-NormalizedPath -PathValue $npmClass203.GrammarPath
        $pgCollision203 = Get-NormalizedPath -PathValue $pgClass203.GrammarPath
        [void](Add-TextFindings -Text '_authToken="NpmSiblingGeneric203"' -BaseLine 1 `
            -Source $npmCollision203 -FilePath $npmCollision203)
        [void](Add-TextFindings -Text 'pg203.example.test:5433:app:deploy:PgSiblingMustNotParse203' -BaseLine 1 `
            -Source $pgCollision203 -FilePath $pgCollision203)
        $npmFinding203 = @($script:CapturedFindings | Where-Object { $_.RawValue -eq 'NpmBackupOverride203' })
        $pgFinding203 = @($script:CapturedFindings | Where-Object { $_.RawValue -eq 'PgBackupOverride203' })
        $npmSiblingSpecific203 = @($script:CapturedFindings | Where-Object {
            $_.RawValue -eq 'NpmSiblingGeneric203' -and $_.PatternId -eq 'NPMRC_AUTH'
        })
        $pgSibling203 = @($script:CapturedFindings | Where-Object { $_.RawValue -eq 'PgSiblingMustNotParse203' })
        $t203 = ($npmFinding203.Count -eq 1 -and $npmFinding203[0].PatternId -eq 'NPMRC_AUTH' -and
                $pgFinding203.Count -eq 1 -and $pgFinding203[0].PatternId -eq 'PGPASS_CRED' -and
                $pgFinding203[0].Account -eq 'deploy' -and $pgFinding203[0].Endpoint -eq 'pg203.example.test' -and
                $npmSiblingSpecific203.Count -eq 0 -and $pgSibling203.Count -eq 0 -and
                -not $script:NpmrcGrammarPaths.Contains($npmCollision203) -and
                -not $script:PgpassGrammarPaths.Contains($pgCollision203))
        Assert-SelfTest -Name 'T203 Backup-wrapped npm and pgpass overrides retain exact grammar' -Condition $t203

        # T204: CSV cells containing revealed or metadata-controlled formula
        # prefixes are neutralized before RFC 4180 quoting; ordinary cells are
        # unchanged and TXT/captured values remain exact.
        $t204 = ((ConvertTo-CsvField -Field '=1+1').StartsWith("'", [System.StringComparison]::Ordinal) -and
                (ConvertTo-CsvField -Field '+SUM(A1)').StartsWith("'", [System.StringComparison]::Ordinal) -and
                (ConvertTo-CsvField -Field '-2+3').StartsWith("'", [System.StringComparison]::Ordinal) -and
                (ConvertTo-CsvField -Field '@cmd').StartsWith("'", [System.StringComparison]::Ordinal) -and
                (ConvertTo-CsvField -Field '  =HYPERLINK').StartsWith("'", [System.StringComparison]::Ordinal) -and
                (ConvertTo-CsvField -Field 'plain') -ceq 'plain')
        Assert-SelfTest -Name 'T204 CSV formula prefixes are neutralized without changing ordinary cells' -Condition $t204

        # T205: an ANSI retry in a later sample window must preserve the
        # cumulative regex accounting inherited from earlier windows.
        Reset-StCounters; Reset-SelfTestCapture
        $script:RxFileTimeoutEvents = 1
        $script:RxFileElapsedMs = [long]777
        $script:RxFileElapsedTicks = [long][Math]::Ceiling((777.0 * [double]$script:StopwatchFrequency) / 1000.0)
        $script:RxFileGapRecorded = $true
        $strictUtf8205 = New-Object System.Text.UTF8Encoding ($false, $true)
        $sampleStream205 = $null
        $t205 = $false
        try {
            $sampleStream205 = New-Object System.IO.FileStream ($mixedPath202, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
            $validSegment205 = Invoke-TextScan -Path $mixedPath202 -DisplaySource $mixedPath202 -Extension '.log' `
                -DoRolling $false -StartOffset 3600 -ReadLength 200 -CoverageMode 'Sampled' -SampleOffset 3600 `
                -ExistingStream $sampleStream205 -SnapshotLength 5000 -ResetRegexFileBudget $false `
                -EncodingOverride $strictUtf8205 -AllowAnsiRetryOverride $true
            $segment205 = Invoke-TextScan -Path $mixedPath202 -DisplaySource $mixedPath202 -Extension '.log' `
                -DoRolling $false -StartOffset 1200 -ReadLength 200 -CoverageMode 'Sampled' -SampleOffset 1200 `
                -ExistingStream $sampleStream205 -SnapshotLength 5000 -ResetRegexFileBudget $false `
                -EncodingOverride $strictUtf8205 -AllowAnsiRetryOverride $true
            $t205 = ($validSegment205.Outcome -eq 'Completed' -and -not [bool]$validSegment205.AnsiRetryOccurred -and
                    $segment205.Outcome -eq 'Completed' -and [bool]$segment205.AnsiRetryOccurred -and
                    $segment205.EncodingUsed.CodePage -eq [System.Text.Encoding]::Default.CodePage -and
                    (Test-CapturedValue -Value 'AnsiWindowSecret202') -and
                    $script:RxFileTimeoutEvents -ge 1 -and $script:RxFileElapsedMs -ge 777 -and
                    $script:RxFileGapRecorded)
        } finally {
            if ($null -ne $sampleStream205) { $sampleStream205.Dispose() }
            Reset-RegexFileBudgetState
        }
        Assert-SelfTest -Name 'T205 Later sample ANSI retry preserves cumulative regex budget state' -Condition $t205

        # T206: inherited UTF-32 is re-probed with encoding-aware decoded
        # controls, not the byte-oriented NUL heuristic. A disconnected UTF-16
        # window beginning on a low surrogate is also advanced safely.
        Reset-StCounters; Reset-SelfTestCapture
        $utf32Path206 = Join-Path $stFixRoot 'large\utf32-tail206.log'
        $utf32Text206 = ('A' * 3000) + "`r`npassword=Utf32TailSecret206`r`n"
        $utf32Preamble206 = [System.Text.Encoding]::UTF32.GetPreamble()
        $utf32Payload206 = [System.Text.Encoding]::UTF32.GetBytes($utf32Text206)
        $utf32Bytes206 = New-Object 'byte[]' ($utf32Preamble206.Length + $utf32Payload206.Length)
        [Array]::Copy($utf32Preamble206, 0, $utf32Bytes206, 0, $utf32Preamble206.Length)
        [Array]::Copy($utf32Payload206, 0, $utf32Bytes206, $utf32Preamble206.Length, $utf32Payload206.Length)
        [System.IO.File]::WriteAllBytes($utf32Path206, $utf32Bytes206)
        $utf32Item206 = Get-Item -LiteralPath $utf32Path206
        $utf32Class206 = Get-FileClassification -FullPath $utf32Item206.FullName -Name $utf32Item206.Name `
            -Extension $utf32Item206.Extension -ParentName 'large' -Length ([long]$utf32Item206.Length) -ForceEligible $false
        $utf16Path206 = Join-Path $stFixRoot 'large\utf16-split206.log'
        $utf16Bytes206 = New-Object 'byte[]' 5000
        $utf16Bytes206[0] = 0xFF; $utf16Bytes206[1] = 0xFE
        for ($utf16Offset206 = 2; $utf16Offset206 -lt $utf16Bytes206.Length; $utf16Offset206 += 2) {
            $utf16Bytes206[$utf16Offset206] = 0x41
            if (($utf16Offset206 + 1) -lt $utf16Bytes206.Length) { $utf16Bytes206[$utf16Offset206 + 1] = 0x00 }
        }
        # For length=5000/budget=1000 the second sample starts at byte 1200.
        # Put the high surrogate immediately before it and the low surrogate at
        # the exact range start; a stateless probe would reject this valid pair.
        $utf16Bytes206[1198] = 0x3D; $utf16Bytes206[1199] = 0xD8
        $utf16Bytes206[1200] = 0x00; $utf16Bytes206[1201] = 0xDE
        $utf16Tail206 = [System.Text.Encoding]::Unicode.GetBytes("`r`npassword=Utf16TailSecret206`r`n")
        [Array]::Copy($utf16Tail206, 0, $utf16Bytes206, 4800, $utf16Tail206.Length)
        [System.IO.File]::WriteAllBytes($utf16Path206, $utf16Bytes206)
        $utf16Item206 = Get-Item -LiteralPath $utf16Path206
        $utf16Class206 = Get-FileClassification -FullPath $utf16Item206.FullName -Name $utf16Item206.Name `
            -Extension $utf16Item206.Extension -ParentName 'large' -Length ([long]$utf16Item206.Length) -ForceEligible $false
        $savedMax206 = $script:MaxFileSizeBytes
        $savedLargeMode206 = $script:LargeFileModeActive
        $t206 = $false
        try {
            $script:MaxFileSizeBytes = 1000
            $script:LargeFileModeActive = 'Sample'
            $out206 = Invoke-FileAssessment -FullPath $utf32Item206.FullName -Classification $utf32Class206 -FromQuickWin $false
            $utf16Out206 = Invoke-FileAssessment -FullPath $utf16Item206.FullName -Classification $utf16Class206 -FromQuickWin $false
            $utf32Finding206 = @($script:CapturedFindings | Where-Object { $_.RawValue -eq 'Utf32TailSecret206' })
            $utf16Finding206 = @($script:CapturedFindings | Where-Object { $_.RawValue -eq 'Utf16TailSecret206' })
            $t206 = ($out206 -eq 'ContentSampled' -and $utf16Out206 -eq 'ContentSampled' -and
                     $utf32Finding206.Count -eq 1 -and $utf16Finding206.Count -eq 1 -and
                     $utf32Finding206[0].CoverageMode -eq 'Sampled' -and
                     $script:Stats.UnsupportedFormatsSkipped -eq 0)
        } finally {
            $script:MaxFileSizeBytes = $savedMax206
            $script:LargeFileModeActive = $savedLargeMode206
        }
        Assert-SelfTest -Name 'T206 UTF-32 and split-surrogate UTF-16 samples stay text' -Condition $t206

        # T207: a private-key marker emitted from an early strict-UTF8 block is
        # retained when a later block forces the bounded ANSI replay. Dedupe
        # suppresses the replayed content row, but artifact promotion must not
        # lose the already-observed marker.
        Reset-StCounters; Reset-SelfTestCapture
        $keyRetryPath207 = Join-Path $stFixRoot 'encoding\private-key-retry207.pem'
        [void][System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($keyRetryPath207))
        $keyRetryBytes207 = New-Object 'byte[]' 20000
        for ($keyByte207 = 0; $keyByte207 -lt $keyRetryBytes207.Length; $keyByte207++) { $keyRetryBytes207[$keyByte207] = 0x41 }
        $keyPrefix207 = [System.Text.Encoding]::ASCII.GetBytes("-----BEGIN PRIVATE KEY-----`r`n")
        [Array]::Copy($keyPrefix207, 0, $keyRetryBytes207, 0, $keyPrefix207.Length)
        $keyRetryBytes207[18000] = 0xE9
        $keyRetryBytes207[18001] = 0x0A
        [System.IO.File]::WriteAllBytes($keyRetryPath207, $keyRetryBytes207)
        $keyRetryItem207 = Get-Item -LiteralPath $keyRetryPath207
        $keyRetryClass207 = Get-FileClassification -FullPath $keyRetryItem207.FullName -Name $keyRetryItem207.Name `
            -Extension $keyRetryItem207.Extension -ParentName 'encoding' -Length ([long]$keyRetryItem207.Length) -ForceEligible $false
        $out207 = Invoke-FileAssessment -FullPath $keyRetryItem207.FullName -Classification $keyRetryClass207 -FromQuickWin $false
        $contentKey207 = @($script:CapturedFindings | Where-Object { $_.PatternId -eq 'PRIV_KEY_HEADER' })
        $artifactKey207 = @($script:CapturedFindings | Where-Object { $_.PatternId -eq 'ARTIFACT_PRIVATEKEY' })
        $t207 = ($out207 -eq 'ContentCompleted' -and $contentKey207.Count -eq 1 -and
                 $artifactKey207.Count -eq 1 -and $artifactKey207[0].FindingKind -eq 'SensitiveNamedArtifact')
        Assert-SelfTest -Name 'T207 Private-key marker survives ANSI replay and promotes artifact' -Condition $t207

        # T208: derive every probe from the live ordered catalog. For every
        # pattern fixture, filename context, case variant and normal/rolling
        # mode, a catalog-admitted unit must be admitted by its dispatch gate
        # or belong to an explicit complete-matcher bypass.
        $t208 = $true
        $savedLineRegex208 = $script:LinePrefilterRegex
        $savedLineEnabled208 = [bool]$script:LinePrefilterEnabled
        $savedLineFallbacks208 = [long]$script:LinePrefilterFallbackEvents
        try {
            $requiredOptions208 = [System.Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
                [System.Text.RegularExpressions.RegexOptions]::CultureInvariant -bor
                [System.Text.RegularExpressions.RegexOptions]::ExplicitCapture -bor
                [System.Text.RegularExpressions.RegexOptions]::Compiled
            if ($script:Patterns.Count -ne 37 -or -not $script:LinePrefilterEnabled -or
                $null -eq $script:LinePrefilterRegex -or
                ($script:LinePrefilterRegex.Options -band $requiredOptions208) -ne $requiredOptions208 -or
                $script:LinePrefilterRegex.MatchTimeout -le [TimeSpan]::Zero) {
                $t208 = $false
            }
            if ((Test-LinePrefilterMayMatch -Text '-') -or
                (Test-LinePrefilterMayMatch -Text "`n") -or
                -not (Test-LinePrefilterMayMatch -Text 'token')) {
                $t208 = $false
            }

            $contexts208 = @(
                (New-ScanContext -FilePath 'C:\selftest\prefilter208.txt'),
                (New-ScanContext -FilePath 'C:\selftest\.npmrc'),
                (New-ScanContext -FilePath 'C:\selftest\.netrc'),
                (New-ScanContext -FilePath 'C:\selftest\.vault-token'),
                (New-ScanContext -FilePath 'C:\selftest\WinSCP.ini'),
                (New-ScanContext -FilePath 'C:\selftest\sitemanager.xml'),
                (New-ScanContext -FilePath 'C:\selftest\prefilter208.rdp'),
                (New-ScanContext -FilePath 'C:\selftest\.pgpass')
            )
            if ((Test-RollingPrefilterMayMatch -Text "ordinary telemetry`nordinary heartbeat" -ScanContext $contexts208[0]) -or
                -not (Test-RollingPrefilterMayMatch -Text "- --token`n  - RollingGate208" -ScanContext $contexts208[0])) {
                $t208 = $false
            }
            if ((Test-CompletePrefilterMayMatch -Text 'ordinary telemetry heartbeat' -ScanContext $contexts208[0]) -or
                -not (Test-CompletePrefilterMayMatch -Text 'AKIAABCDEFGHIJKLMNOP' -ScanContext $contexts208[0])) {
                $t208 = $false
            }
            for ($fixturePatternIndex208 = 0; $fixturePatternIndex208 -le 36; $fixturePatternIndex208++) {
                if (-not $t208) { break }
                $fixturePattern208 = $script:Patterns[$fixturePatternIndex208]
                if ([int]$fixturePattern208.PerfIndex -ne $fixturePatternIndex208) { $t208 = $false; break }
                $alternatives208 = @($fixturePattern208.TriggerAny)
                if ($alternatives208.Count -eq 0) { $alternatives208 = @('') }
                foreach ($alternative208 in $alternatives208) {
                    if (-not $t208) { break }
                    $parts208 = New-Object System.Collections.Generic.List[string]
                    foreach ($literal208 in @($fixturePattern208.TriggerAll)) { $parts208.Add([string]$literal208) }
                    if (-not [string]::IsNullOrEmpty([string]$alternative208)) { $parts208.Add([string]$alternative208) }
                    if ([bool]$fixturePattern208.RequireAssignment) { $parts208.Add('=') }
                    if ($parts208.Count -eq 0) { $parts208.Add('VaultOnlyFixture208') }
                    $fixtureText208 = $parts208 -join ' '
                    $caseVariants208 = @($fixtureText208, $fixtureText208.ToLowerInvariant(), $fixtureText208.ToUpperInvariant())

                    foreach ($caseText208 in $caseVariants208) {
                        if (-not $t208) { break }
                        foreach ($context208 in $contexts208) {
                            if (-not $t208) { break }
                            foreach ($forceNpm208 in @($false, $true)) {
                                if (-not $t208) { break }
                                foreach ($rolling208 in @($false, $true)) {
                                    $catalogAdmits208 = $false
                                    for ($gateIndex208 = 0; $gateIndex208 -le 36; $gateIndex208++) {
                                        if (Test-ScanPatternTrigger -Pattern $script:Patterns[$gateIndex208] -Text $caseText208 `
                                            -ScanContext $context208 -ForceNpmrcGrammar $forceNpm208 -RollingOnly $rolling208) {
                                            $catalogAdmits208 = $true
                                            break
                                        }
                                    }
                                    if (-not $catalogAdmits208) { continue }
                                    $explicitBypass208 = ([bool]$context208.IsRdp -or [bool]$context208.IsPgpass -or
                                        [bool]$context208.IsVaultToken)
                                    if (-not $explicitBypass208 -and -not (Test-LinePrefilterMayMatch -Text $caseText208)) {
                                        $t208 = $false
                                        break
                                    }
                                    if ($rolling208 -and -not $explicitBypass208 -and
                                        -not (Test-RollingPrefilterMayMatch -Text $caseText208 -ScanContext $context208)) {
                                        $t208 = $false
                                        break
                                    }
                                    if (-not $rolling208 -and -not $explicitBypass208 -and
                                        -not (Test-CompletePrefilterMayMatch -Text $caseText208 -ScanContext $context208)) {
                                        $t208 = $false
                                        break
                                    }
                                }
                            }
                        }
                    }
                }
            }
            if ([long]$script:LinePrefilterFallbackEvents -ne $savedLineFallbacks208) { $t208 = $false }
        } catch {
            $t208 = $false
        } finally {
            $script:LinePrefilterRegex = $savedLineRegex208
            $script:LinePrefilterEnabled = $savedLineEnabled208
            $script:LinePrefilterFallbackEvents = $savedLineFallbacks208
        }
        Assert-SelfTest -Name 'T208 live-catalog line and rolling prefilters are recall-safe across contexts and case' -Condition $t208

        # T209: verify complete-line/rolling integration boundaries and every
        # required bypass. Unterminated tails and oversized chunks enter the
        # matcher directly. Injected prefilter error and timeout both process
        # the current line in full and leave RegexV1 fail-open.
        $t209 = $true
        $savedFaultEnabled209 = [bool]$script:FaultSeam.Enabled
        $savedLineFault209 = [string]$script:FaultSeam.LinePrefilterFailure
        $savedPerfEnabled209 = [bool]$script:PerfEnabled
        $savedPerfBoundary209 = [bool]$script:PerfTextBoundaryActive
        $savedPerf209 = $script:Perf
        $savedLineRegex209 = $script:LinePrefilterRegex
        $savedLineEnabled209 = [bool]$script:LinePrefilterEnabled
        $savedLineFallbacks209 = [long]$script:LinePrefilterFallbackEvents
        $breakpoint209 = $null
        try {
            $prefilterRoot209 = Join-Path $stFixRoot 'line-prefilter209'
            $benignPath209 = Join-Path $prefilterRoot209 'benign209.log'
            $positivePath209 = Join-Path $prefilterRoot209 'positive209.log'
            $partialPath209 = Join-Path $prefilterRoot209 'partial209.log'
            $rdpPath209 = Join-Path $prefilterRoot209 'special209.rdp'
            $pgpassPath209 = Join-Path $prefilterRoot209 '.pgpass'
            $vaultPath209 = Join-Path $prefilterRoot209 '.vault-token'
            $tailPath209 = Join-Path $prefilterRoot209 'tail209.log'
            $oversizedPath209 = Join-Path $prefilterRoot209 'oversized209.log'
            $rollingBenignPath209 = Join-Path $prefilterRoot209 'rolling-benign209.yaml'
            $rollingPath209 = Join-Path $prefilterRoot209 'rolling209.yaml'
            $rollingFaultPath209 = Join-Path $prefilterRoot209 'rolling-fault209.yaml'
            $faultPath209 = Join-Path $prefilterRoot209 'fault209.log'
            $profilePath209 = Join-Path $prefilterRoot209 'profile209.log'
            $errorPath209 = Join-Path $prefilterRoot209 'error209.log'
            $timeoutPath209 = Join-Path $prefilterRoot209 'timeout209.log'

            Write-StFixtureFile -Path $benignPath209 -Content "ordinary telemetry heartbeat row 209`r`n"
            Write-StFixtureFile -Path $positivePath209 -Content "password=PositiveLineSecret209`r`n"
            Write-StFixtureFile -Path $partialPath209 -Content "xpassword=PartialLineSecret209`r`nordinary complete sample row 209`r`n"
            Write-StFixtureFile -Path $rdpPath209 -Content "password 51:b:0011223344556677`r`n"
            Write-StFixtureFile -Path $pgpassPath209 -Content "db209.example.test:5432:app:deploy:ZebraValue209`r`n"
            Write-StFixtureFile -Path $vaultPath209 -Content "hvs.ABCDEFGHIJKLMNOP209`r`n"
            Write-StFixtureFile -Path $tailPath209 -Content 'password=TailSecret209'
            $oversizedText209 = 'password=OversizedSecret209 ' + ('Z' * ($script:MaxUnitChars + 128)) + "`r`n"
            Write-StFixtureFile -Path $oversizedPath209 -Content $oversizedText209
            Write-StFixtureFile -Path $rollingBenignPath209 -Content "alpha telemetry row 209`r`nbeta heartbeat row 209`r`n"
            Write-StFixtureFile -Path $rollingPath209 -Content "- --token`r`n  - RollingSecret209`r`n"
            Write-StFixtureFile -Path $rollingFaultPath209 -Content "`r`n`r`n"
            Write-StFixtureFile -Path $faultPath209 -Content "ordinary fault bypass row 209`r`n"
            Write-StFixtureFile -Path $profilePath209 -Content "ordinary profiler bypass row 209`r`n"
            Write-StFixtureFile -Path $errorPath209 -Content "password=ErrorFallbackSecret209`r`n"
            Write-StFixtureFile -Path $timeoutPath209 -Content "password=TimeoutFallbackSecret209`r`n"

            $script:t209AddTextCalls = 0
            $breakpoint209 = Set-PSBreakpoint -Command Add-TextFindings -Action {
                $script:t209AddTextCalls = [int]$script:t209AddTextCalls + 1
            }
            $script:FaultSeam.Enabled = $false
            $script:PerfEnabled = $false
            Initialize-LinePrefilter

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $benignScan209 = Invoke-TextScan -Path $benignPath209 -DisplaySource $benignPath209 -Extension '.log' -DoRolling $false
            if ($benignScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 0 -or
                $script:CapturedFindings.Count -ne 0) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $positiveScan209 = Invoke-TextScan -Path $positivePath209 -DisplaySource $positivePath209 -Extension '.log' -DoRolling $false
            if ($positiveScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                -not (Test-CapturedValue -Value 'PositiveLineSecret209')) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $rollingBenignScan209 = Invoke-TextScan -Path $rollingBenignPath209 -DisplaySource $rollingBenignPath209 -Extension '.yaml' -DoRolling $true
            if ($rollingBenignScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 0 -or
                $script:CapturedFindings.Count -ne 0) { $t209 = $false }

            # A real cached Regex that can never match proves these paths do not
            # consult the complete-line prefilter. If any of them did, its
            # matcher call/finding below would disappear without an exception.
            $neverOptions209 = [System.Text.RegularExpressions.RegexOptions]::IgnoreCase -bor
                [System.Text.RegularExpressions.RegexOptions]::CultureInvariant -bor
                [System.Text.RegularExpressions.RegexOptions]::ExplicitCapture -bor
                [System.Text.RegularExpressions.RegexOptions]::Compiled
            $neverRegex209 = New-Object System.Text.RegularExpressions.Regex (
                '(?!)', $neverOptions209, [TimeSpan]::FromMilliseconds(50))
            $script:LinePrefilterRegex = $neverRegex209
            $script:LinePrefilterEnabled = $true

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $partialLength209 = [long](Get-Item -LiteralPath $partialPath209).Length
            $partialScan209 = Invoke-TextScan -Path $partialPath209 -DisplaySource $partialPath209 -Extension '.log' `
                -DoRolling $false -StartOffset 1 -ReadLength ($partialLength209 - 1) -CoverageMode 'Sampled' `
                -SampleOffset 1 -SnapshotLength $partialLength209
            # The matcher must see the first partial line even though the key at
            # its untrusted fragment boundary is correctly ineligible to emit.
            # The following complete benign line is still proven irrelevant.
            if ($partialScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                $script:CapturedFindings.Count -ne 0) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $rdpScan209 = Invoke-TextScan -Path $rdpPath209 -DisplaySource $rdpPath209 -Extension '.rdp' -DoRolling $false
            if ($rdpScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                @($script:CapturedFindings | Where-Object { $_.PatternId -eq 'RDP_PASSWORD_BLOB' }).Count -ne 1) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $pgpassScan209 = Invoke-TextScan -Path $pgpassPath209 -DisplaySource $pgpassPath209 -Extension '' -DoRolling $false
            if ($pgpassScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                -not (Test-CapturedValue -Value 'ZebraValue209')) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $vaultScan209 = Invoke-TextScan -Path $vaultPath209 -DisplaySource $vaultPath209 -Extension '' -DoRolling $false
            if ($vaultScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                -not (Test-CapturedValue -Value 'hvs.ABCDEFGHIJKLMNOP209')) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $tailScan209 = Invoke-TextScan -Path $tailPath209 -DisplaySource $tailPath209 -Extension '.log' -DoRolling $false
            if ($tailScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                -not (Test-CapturedValue -Value 'TailSecret209')) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $oversizedScan209 = Invoke-TextScan -Path $oversizedPath209 -DisplaySource $oversizedPath209 -Extension '.log' -DoRolling $false
            if ($oversizedScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -lt 1 -or
                -not (Test-CapturedValue -Value 'OversizedSecret209')) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $rollingScan209 = Invoke-TextScan -Path $rollingPath209 -DisplaySource $rollingPath209 -Extension '.yaml' -DoRolling $true
            if ($rollingScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                @($script:CapturedFindings | Where-Object { $_.PatternId -eq 'K8S_EXEC_ARG_SPLIT' -and $_.RawValue -eq 'RollingSecret209' }).Count -ne 1) { $t209 = $false }

            $script:FaultSeam.Enabled = $true
            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $faultScan209 = Invoke-TextScan -Path $faultPath209 -DisplaySource $faultPath209 -Extension '.log' -DoRolling $false
            if ($faultScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1) { $t209 = $false }

            $profilePatterns209 = New-Object System.Collections.Generic.List[object]
            foreach ($profilePattern209 in $script:Patterns) {
                $profilePatterns209.Add([pscustomobject][ordered]@{
                    Id=[string]$profilePattern209.Id; Group=[string]$profilePattern209.PerfGroup
                    Calls=[long]0; Matches=[long]0; Timeouts=[long]0; Errors=[long]0; Ticks=[long]0
                    SkippedFileGate=[long]0; SkippedTrigger=[long]0
                })
            }
            $script:Perf = @{
                SchemaVersion=1; Frequency=[long]$script:StopwatchFrequency
                StartTick=[long][System.Diagnostics.Stopwatch]::GetTimestamp(); EndTick=[long]0
                PhysicalBytesPreflight=[long]0; PhysicalBytesEmission=[long]0
                UnitsNormal=[long]0; UnitsRolling=[long]0; PathNormalizations=[long]0; Assessed=[long]0
                StageTicks=@{ Traversal=[long]0; Open=[long]0; Read=[long]0; Decode=[long]0; Matching=[long]0; Semantics=[long]0; Dedupe=[long]0; Redaction=[long]0; Output=[long]0 }
                Patterns=$profilePatterns209.ToArray()
                Outliers=New-Object 'System.Collections.Generic.List[object]'
            }
            $script:FaultSeam.Enabled = $false
            $script:PerfTextBoundaryActive = $false
            $script:PerfEnabled = $true
            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $profileScan209 = Invoke-TextScan -Path $profilePath209 -DisplaySource $profilePath209 -Extension '.log' -DoRolling $false
            if ($profileScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -lt 1 -or
                [long]$script:Perf.UnitsNormal -lt 1) { $t209 = $false }

            $script:PerfEnabled = $false
            $script:FaultSeam.Enabled = $false
            $script:FaultSeam.LinePrefilterFailure = ''
            Initialize-LinePrefilter
            $fallbackBeforeError209 = [long]$script:LinePrefilterFallbackEvents
            $script:FaultSeam.LinePrefilterFailure = 'Error'
            $script:FaultSeam.Enabled = $true
            $script:LinePrefilterEnabled = $true
            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $rollingFaultScan209 = Invoke-TextScan -Path $rollingFaultPath209 -DisplaySource $rollingFaultPath209 -Extension '.yaml' -DoRolling $true
            if ($rollingFaultScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                -not $script:LinePrefilterEnabled -or
                [long]$script:LinePrefilterFallbackEvents -ne $fallbackBeforeError209) { $t209 = $false }

            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $errorScan209 = Invoke-TextScan -Path $errorPath209 -DisplaySource $errorPath209 -Extension '.log' -DoRolling $false
            if ($errorScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                -not (Test-CapturedValue -Value 'ErrorFallbackSecret209') -or $script:LinePrefilterEnabled -or
                [long]$script:LinePrefilterFallbackEvents -ne ($fallbackBeforeError209 + 1)) { $t209 = $false }

            $script:FaultSeam.Enabled = $false
            $script:FaultSeam.LinePrefilterFailure = ''
            Initialize-LinePrefilter
            $fallbackBeforeTimeout209 = [long]$script:LinePrefilterFallbackEvents
            $script:FaultSeam.LinePrefilterFailure = 'Timeout'
            $script:FaultSeam.Enabled = $true
            $script:LinePrefilterEnabled = $true
            Reset-SelfTestCapture; $script:t209AddTextCalls = 0
            $timeoutScan209 = Invoke-TextScan -Path $timeoutPath209 -DisplaySource $timeoutPath209 -Extension '.log' -DoRolling $false
            if ($timeoutScan209.Outcome -ne 'Completed' -or $script:t209AddTextCalls -ne 1 -or
                -not (Test-CapturedValue -Value 'TimeoutFallbackSecret209') -or $script:LinePrefilterEnabled -or
                [long]$script:LinePrefilterFallbackEvents -ne ($fallbackBeforeTimeout209 + 1)) { $t209 = $false }

            $summaryLines209 = @(Get-SummaryLines -Status 'Complete')
            if (-not ($summaryLines209 -ccontains 'LinePrefilter=RegexV1') -or
                -not ($summaryLines209 -ccontains ('LinePrefilterFallbackEvents={0}' -f $script:LinePrefilterFallbackEvents))) {
                $t209 = $false
            }
        } catch {
            $t209 = $false
        } finally {
            if ($null -ne $breakpoint209) { Remove-PSBreakpoint -Breakpoint $breakpoint209 -ErrorAction SilentlyContinue }
            Remove-Variable -Name t209AddTextCalls -Scope Script -ErrorAction SilentlyContinue
            $script:Perf = $savedPerf209
            $script:PerfEnabled = $savedPerfEnabled209
            $script:PerfTextBoundaryActive = $savedPerfBoundary209
            $script:FaultSeam.Enabled = $savedFaultEnabled209
            $script:FaultSeam.LinePrefilterFailure = $savedLineFault209
            $script:LinePrefilterRegex = $savedLineRegex209
            $script:LinePrefilterEnabled = $savedLineEnabled209
            $script:LinePrefilterFallbackEvents = $savedLineFallbacks209
            Reset-RegexFileBudgetState
            Reset-RegexUnitBudgetState
        }
        Assert-SelfTest -Name 'T209 RegexV1 skips only proven benign complete lines and all bypass/fallback paths scan fully' -Condition $t209

        # T210: direct pure-PowerShell byte/character probes cover the strong
        # SQLite signature, even/odd NUL parity, BOM-less UTF-16 LE/BE, C0/DEL
        # controls and implausible private-use/unassigned code points.
        $t210 = $true
        try {
            $sqlite210 = New-Object 'byte[]' 16
            $sqliteHeader210 = [System.Text.Encoding]::ASCII.GetBytes('SQLite format 3')
            [Array]::Copy($sqliteHeader210, 0, $sqlite210, 0, $sqliteHeader210.Length)
            $sqlite210[15] = 0
            if ((Get-BinaryMagicKind -Buffer $sqlite210 -BytesRead $sqlite210.Length) -ne 'SQLITE') { $t210 = $false }

            $utf16Text210 = 'ABCD pure ps parity 210'
            $le210 = (New-Object System.Text.UnicodeEncoding ($false, $false, $true)).GetBytes($utf16Text210)
            $be210 = (New-Object System.Text.UnicodeEncoding ($true, $false, $true)).GetBytes($utf16Text210)
            $leSel210 = Select-ScanEncoding -Buffer $le210 -BytesRead $le210.Length
            $beSel210 = Select-ScanEncoding -Buffer $be210 -BytesRead $be210.Length
            if ($leSel210.IsBinary -or $null -eq $leSel210.Encoding -or $leSel210.Encoding.CodePage -ne 1200 -or
                $beSel210.IsBinary -or $null -eq $beSel210.Encoding -or $beSel210.Encoding.CodePage -ne 1201) { $t210 = $false }

            $c0Bytes210 = New-Object 'byte[]' 32
            for ($c0Index210 = 0; $c0Index210 -lt $c0Bytes210.Length; $c0Index210++) { $c0Bytes210[$c0Index210] = 1 }
            $c0Sel210 = Select-ScanEncoding -Buffer $c0Bytes210 -BytesRead $c0Bytes210.Length
            if (-not $c0Sel210.IsBinary -or $c0Sel210.BinaryKind -ne 'BINARY_CONTROL') { $t210 = $false }

            $delText210 = ([string][char]127) * 16
            $delBytes210 = (New-Object System.Text.UnicodeEncoding ($false, $false, $true)).GetBytes($delText210)
            $delKind210 = Get-InheritedEncodingBinaryKind -Buffer $delBytes210 -BytesRead $delBytes210.Length `
                -Encoding (New-Object System.Text.UnicodeEncoding ($false, $false, $true))
            if ($delKind210 -ne 'BINARY_UNICODE_CONTROL') { $t210 = $false }

            $privateText210 = 'ABCD' + ([string][char]0xE000) + ([string][char]0xE001)
            $privateBytes210 = (New-Object System.Text.UnicodeEncoding ($false, $false, $true)).GetBytes($privateText210)
            $unassignedText210 = 'ABCD' + ([string][char]0x0378) + ([string][char]0x0379)
            $unassignedBytes210 = (New-Object System.Text.UnicodeEncoding ($false, $false, $true)).GetBytes($unassignedText210)
            if ((Test-BomlessUtf16Probe -Buffer $privateBytes210 -BytesRead $privateBytes210.Length -BigEndian $false) -or
                (Test-BomlessUtf16Probe -Buffer $unassignedBytes210 -BytesRead $unassignedBytes210.Length -BigEndian $false)) {
                $t210 = $false
            }
        } catch {
            $t210 = $false
        }
        Assert-SelfTest -Name 'T210 Pure-PS SQLite, NUL parity, UTF-16 and character plausibility probes are exact' -Condition $t210

        # T211: UTF-32 BOM selection remains exact in both byte orders and the
        # stateful strict UTF-16 decoder preserves a surrogate pair split across
        # two bounded decode calls.
        $t211 = $true
        try {
            $utf32Text211 = 'UTF32 probe 211'
            $utf32LeEnc211 = New-Object System.Text.UTF32Encoding ($false, $true, $true)
            $utf32BeEnc211 = New-Object System.Text.UTF32Encoding ($true, $true, $true)
            $utf32Le211 = $utf32LeEnc211.GetPreamble() + $utf32LeEnc211.GetBytes($utf32Text211)
            $utf32Be211 = $utf32BeEnc211.GetPreamble() + $utf32BeEnc211.GetBytes($utf32Text211)
            $utf32LeSel211 = Select-ScanEncoding -Buffer $utf32Le211 -BytesRead $utf32Le211.Length
            $utf32BeSel211 = Select-ScanEncoding -Buffer $utf32Be211 -BytesRead $utf32Be211.Length
            if ($utf32LeSel211.IsBinary -or $utf32LeSel211.PreambleBytes -ne 4 -or $utf32LeSel211.Encoding.CodePage -ne 12000 -or
                $utf32BeSel211.IsBinary -or $utf32BeSel211.PreambleBytes -ne 4 -or $utf32BeSel211.Encoding.CodePage -ne 12001) {
                $t211 = $false
            }
            $utf32LePayload211 = $utf32LeEnc211.GetBytes($utf32Text211)
            $utf32BePayload211 = $utf32BeEnc211.GetBytes($utf32Text211)
            if ((Get-InheritedEncodingBinaryKind -Buffer $utf32LePayload211 -BytesRead $utf32LePayload211.Length -Encoding $utf32LeSel211.Encoding).Length -ne 0 -or
                (Get-InheritedEncodingBinaryKind -Buffer $utf32BePayload211 -BytesRead $utf32BePayload211.Length -Encoding $utf32BeSel211.Encoding).Length -ne 0) {
                $t211 = $false
            }

            $surrogateBytes211 = [byte[]](0x3D,0xD8,0x00,0xDE)
            $surrogateDecoder211 = (New-Object System.Text.UnicodeEncoding ($false, $false, $true)).GetDecoder()
            $surrogateChars211 = New-Object 'char[]' 4
            $surrogateText211 = New-Object System.Text.StringBuilder
            $bytesUsed211 = 0; $charsUsed211 = 0; $done211 = $false
            $surrogateDecoder211.Convert($surrogateBytes211, 0, 2, $surrogateChars211, 0, $surrogateChars211.Length, $false,
                [ref]$bytesUsed211, [ref]$charsUsed211, [ref]$done211)
            if ($charsUsed211 -gt 0) { [void]$surrogateText211.Append($surrogateChars211, 0, $charsUsed211) }
            $bytesUsed211 = 0; $charsUsed211 = 0; $done211 = $false
            $surrogateDecoder211.Convert($surrogateBytes211, 2, 2, $surrogateChars211, 0, $surrogateChars211.Length, $true,
                [ref]$bytesUsed211, [ref]$charsUsed211, [ref]$done211)
            if ($charsUsed211 -gt 0) { [void]$surrogateText211.Append($surrogateChars211, 0, $charsUsed211) }
            $expectedSurrogate211 = [string]([char]0xD83D) + [string]([char]0xDE00)
            if ($surrogateText211.ToString() -cne $expectedSurrogate211) { $t211 = $false }
        } catch {
            $t211 = $false
        }
        Assert-SelfTest -Name 'T211 Pure-PS UTF-32 selection and split-surrogate state are preserved' -Condition $t211

        # T212: binary evidence that begins after the initial block remains
        # authoritative for NUL, non-whitespace C0 and DEL payloads.
        Reset-StCounters; Reset-SelfTestCapture
        $t212 = $true
        try {
            $lateRoot212 = Join-Path $stFixRoot 'pureps-late212'
            [void][System.IO.Directory]::CreateDirectory($lateRoot212)
            $lateLength212 = $script:ReadBlockBytes + 1024
            $lateCases212 = @(
                @{ Name='nul212.log'; Byte=[byte]0; Kind='BINARY_NUL' },
                @{ Name='c0-212.log'; Byte=[byte]1; Kind='BINARY_CONTROL' },
                @{ Name='del212.log'; Byte=[byte]127; Kind='BINARY_CONTROL' }
            )
            foreach ($lateCase212 in $lateCases212) {
                $lateBytes212 = New-Object 'byte[]' $lateLength212
                for ($lateIndex212 = 0; $lateIndex212 -lt $script:ReadBlockBytes; $lateIndex212++) {
                    $lateBytes212[$lateIndex212] = 0x41
                }
                for ($lateIndex212 = $script:ReadBlockBytes; $lateIndex212 -lt $lateBytes212.Length; $lateIndex212++) {
                    $lateBytes212[$lateIndex212] = [byte]$lateCase212.Byte
                }
                $latePath212 = Join-Path $lateRoot212 ([string]$lateCase212.Name)
                [System.IO.File]::WriteAllBytes($latePath212, $lateBytes212)
                $lateResult212 = Invoke-TextScan -Path $latePath212 -DisplaySource $latePath212 -Extension '.log' -DoRolling $false
                if ($lateResult212.Outcome -ne 'Binary' -or $lateResult212.BinaryKind -ne [string]$lateCase212.Kind) {
                    $t212 = $false
                    break
                }
            }

            # Exercise Process-ScanBlock directly so the optimized decoded-char
            # classifier is pinned independently of the raw-byte NUL shortcut.
            # Keep one assertion for T212; these cases do not change the plan.
            $utf8Strict212 = New-Object System.Text.UTF8Encoding ($false, $true)
            $densityCases212 = @(
                @{ Name='c0-exact';  Code=[char]1;   Length=20; Binary=$false },
                @{ Name='c0-above';  Code=[char]1;   Length=19; Binary=$true  },
                @{ Name='del-exact'; Code=[char]127; Length=20; Binary=$false },
                @{ Name='del-above'; Code=[char]127; Length=19; Binary=$true  }
            )
            foreach ($densityCase212 in $densityCases212) {
                $densityText212 = ('A' * ([int]$densityCase212.Length - 1)) + [string][char]$densityCase212.Code
                $densityBytes212 = $utf8Strict212.GetBytes($densityText212)
                $densityCarry212 = 'probe-carry-212'
                $densityCarryBuilder212 = New-Object System.Text.StringBuilder
                [void]$densityCarryBuilder212.Append($densityCarry212)
                $densityState212 = @{
                    Stop = $false; SafetyValidated = $false
                    Result = @{ Outcome='Completed'; BinaryKind=''; EncodingUsed=$utf8Strict212; PrivateKeyHits=0 }
                    PreambleSkipped = $true; PreambleBytes = 0
                    Decoder = $utf8Strict212.GetDecoder(); CharBuf = New-Object 'char[]' 128
                    DecodeFailed = $false; Sb = $densityCarryBuilder212; ScanContext = $null
                }
                Process-ScanBlock -State $densityState212 -Bytes $densityBytes212 `
                    -Count $densityBytes212.Length -Flush $true -ProbeOnly $true
                if ([bool]$densityCase212.Binary) {
                    if ($densityState212.Result.Outcome -ne 'Binary' -or
                        $densityState212.Result.BinaryKind -ne 'BINARY_CONTROL' -or
                        -not $densityState212.Stop) { $t212 = $false }
                } elseif ($densityState212.Result.Outcome -ne 'Completed' -or
                    $densityState212.Result.BinaryKind.Length -ne 0 -or $densityState212.Stop) {
                    $t212 = $false
                }
                if ($densityState212.DecodeFailed -or
                    $densityState212.Sb.ToString() -cne $densityCarry212) { $t212 = $false }
            }

            # UTF-16 bypasses the byte-oriented raw NUL check. Put enough C0
            # characters first to exceed 5%, then a decoded NUL last: NUL must
            # retain priority and ProbeOnly must preserve the carry.
            $utf16Strict212 = New-Object System.Text.UnicodeEncoding ($false, $false, $true)
            $priorityText212 = (([string][char]1) * 2) + ('A' * 17) + [string][char]0
            $priorityBytes212 = $utf16Strict212.GetBytes($priorityText212)
            $priorityCarry212 = 'priority-carry-212'
            $priorityCarryBuilder212 = New-Object System.Text.StringBuilder
            [void]$priorityCarryBuilder212.Append($priorityCarry212)
            $priorityState212 = @{
                Stop = $false; SafetyValidated = $false
                Result = @{ Outcome='Completed'; BinaryKind=''; EncodingUsed=$utf16Strict212; PrivateKeyHits=0 }
                PreambleSkipped = $true; PreambleBytes = 0
                Decoder = $utf16Strict212.GetDecoder(); CharBuf = New-Object 'char[]' 128
                DecodeFailed = $false; Sb = $priorityCarryBuilder212; ScanContext = $null
            }
            Process-ScanBlock -State $priorityState212 -Bytes $priorityBytes212 `
                -Count $priorityBytes212.Length -Flush $true -ProbeOnly $true
            if ($priorityState212.Result.Outcome -ne 'Binary' -or
                $priorityState212.Result.BinaryKind -ne 'BINARY_NUL' -or
                -not $priorityState212.Stop -or $priorityState212.DecodeFailed -or
                $priorityState212.Sb.ToString() -cne $priorityCarry212) { $t212 = $false }

            # The production emission pass receives SafetyValidated=true. It
            # must append the exact decoded slice while retaining prior carry.
            $emissionCarry212 = 'emission-carry-212:'
            $emissionText212 = 'benign-emission-212'
            $emissionBytes212 = $utf8Strict212.GetBytes($emissionText212)
            $emissionCarryBuilder212 = New-Object System.Text.StringBuilder
            [void]$emissionCarryBuilder212.Append($emissionCarry212)
            $emissionState212 = @{
                Stop = $false; SafetyValidated = $true
                Result = @{ Outcome='Completed'; BinaryKind=''; EncodingUsed=$utf8Strict212; PrivateKeyHits=0 }
                PreambleSkipped = $true; PreambleBytes = 0
                Decoder = $utf8Strict212.GetDecoder(); CharBuf = New-Object 'char[]' 128
                DecodeFailed = $false; Sb = $emissionCarryBuilder212; ScanContext = $null
            }
            Process-ScanBlock -State $emissionState212 -Bytes $emissionBytes212 `
                -Count $emissionBytes212.Length -Flush $false -ProbeOnly $false
            if ($emissionState212.Result.Outcome -ne 'Completed' -or
                $emissionState212.Result.BinaryKind.Length -ne 0 -or
                $emissionState212.Stop -or $emissionState212.DecodeFailed -or
                $emissionState212.Sb.ToString() -cne ($emissionCarry212 + $emissionText212)) { $t212 = $false }
        } catch {
            $t212 = $false
        }
        Assert-SelfTest -Name 'T212 Pure-PS late-binary NUL, C0 and DEL detection remains fail-closed' -Condition $t212

        # T213: newline at the byte-block edge, dense mixed-newline extraction,
        # rolling/tail line numbers and a credential whose key spans the
        # oversized-unit cut retain the original cursor/overlap semantics.
        $t213 = $true
        try {
            $boundaryRoot213 = Join-Path $stFixRoot 'pureps-boundary213'
            [void][System.IO.Directory]::CreateDirectory($boundaryRoot213)
            $newlinePath213 = Join-Path $boundaryRoot213 'newline213.log'
            $chunkPath213 = Join-Path $boundaryRoot213 'chunk213.log'
            $cursorPath213 = Join-Path $boundaryRoot213 'cursor213.yaml'
            $newlineText213 = ('A' * ($script:ReadBlockBytes - 1)) + "`npassword=NewlineBoundarySecret213`r`n"
            Write-StFixtureFile -Path $newlinePath213 -Content $newlineText213
            $chunkText213 = ('A' * ($script:MaxUnitChars - 6)) + ' password="ChunkBoundarySecret213"' + ('Z' * 128) + "`r`n"
            Write-StFixtureFile -Path $chunkPath213 -Content $chunkText213

            # More than one decoded block of short lines exercises repeated
            # snapshot cursors; alternating LF/CRLF plus a blank line catches
            # off-by-one consumption without relying on platform newlines.
            $cursorText213 = New-Object System.Text.StringBuilder
            for ($cursorLine213 = 1; $cursorLine213 -le 192; $cursorLine213++) {
                [void]$cursorText213.Append((('ordinary cursor row {0:D3} ' -f $cursorLine213) + ('q' * 96)))
                if (($cursorLine213 % 2) -eq 0) { [void]$cursorText213.Append("`r`n") }
                else { [void]$cursorText213.Append("`n") }
            }
            [void]$cursorText213.Append("password=CursorLineSecret213`r`n") # line 193
            [void]$cursorText213.Append("`n")                              # line 194 (blank)
            [void]$cursorText213.Append("- --token`r`n")                   # line 195
            [void]$cursorText213.Append("  - CursorRollingSecret213`n")    # line 196
            [void]$cursorText213.Append((('A' * ($script:MaxUnitChars - 6)) +
                ' password="CursorChunkSecret213"' + ('Z' * 128) + "`r`n")) # line 197
            [void]$cursorText213.Append('password=CursorTailSecret213')     # line 198, no newline
            Write-StFixtureFile -Path $cursorPath213 -Content $cursorText213.ToString()

            Reset-StCounters; Reset-SelfTestCapture
            $newlineResult213 = Invoke-TextScan -Path $newlinePath213 -DisplaySource $newlinePath213 -Extension '.log' -DoRolling $false
            $newlineFindings213 = @($script:CapturedFindings | Where-Object { $_.RawValue -eq 'NewlineBoundarySecret213' })
            if ($newlineResult213.Outcome -ne 'Completed' -or $newlineFindings213.Count -ne 1) { $t213 = $false }

            Reset-StCounters; Reset-SelfTestCapture
            $chunkResult213 = Invoke-TextScan -Path $chunkPath213 -DisplaySource $chunkPath213 -Extension '.log' -DoRolling $false
            $chunkFindings213 = @($script:CapturedFindings | Where-Object { $_.RawValue -eq 'ChunkBoundarySecret213' })
            if ($chunkResult213.Outcome -ne 'Completed' -or $chunkFindings213.Count -ne 1) { $t213 = $false }

            Reset-StCounters; Reset-SelfTestCapture
            $cursorResult213 = Invoke-TextScan -Path $cursorPath213 -DisplaySource $cursorPath213 -Extension '.yaml' -DoRolling $true
            $cursorLineFindings213 = @($script:CapturedFindings | Where-Object {
                $_.RawValue -eq 'CursorLineSecret213' -and $_.LineNumber -eq 193
            })
