        # This sentinel is reached only after the final planned SelfTest has
        # produced an Assert/Skip outcome. The runner validates its presence
        # and the planned/executed cardinality before it can return success.
        $script:SelfTestReachedEnd = $true

    } finally {
        Close-DedupeHasher
        if ([System.IO.Directory]::Exists($stFixRoot)) {
            try { [System.IO.Directory]::Delete($stFixRoot, $true) } catch { }
        }
    }

    if (-not $script:SelfTestReachedEnd) {
        Register-SelfTestAbort -Reason 'CompletionSentinelNotReached'
    }
    if ($script:SelfTestExecuted -ne $script:SelfTestPlanned) {
        Register-SelfTestAbort -Reason 'PlannedExecutedOutcomeMismatch'
    }
    $script:CaptureMode = $false
    $script:CapturedFindings.Clear()
    $script:DedupeKeys.Clear()

    if ($script:SelfTestFailures -gt 0 -or $script:SelfTestAborted -or
        -not $script:SelfTestReachedEnd -or
        $script:SelfTestExecuted -ne $script:SelfTestPlanned) { return 2 }
    return 0
}

# ---------------------------------------------------------------------------
# Protected lifecycle: begins immediately after successful output
# initialization and encompasses all subsequent discovery, phase execution,
# finalization and cleanup. Exactly one final-summary attempt is guaranteed
# for every initialized output set (Complete-ScanOutputs guard). Interruption
# and fatal output failure transition every still Pending/Running phase and
# root to Cancelled exactly once; recoverable failures use Failed.
# ---------------------------------------------------------------------------
function Invoke-ProtectedLifecycle {
    param([Parameter(Mandatory=$true)]$ScanPlan)
    try {
        # ---- Discovery and exclusions (isolated; failures degrade, never abort)
        try {
            Test-FaultOperation -OperationId 'Preflight.Profiles'
            Get-UserProfiles
        } catch {
            if (Test-StopError -Err $_) { throw }
            $preflightProfileCategory = Get-ItemErrorCategory -ErrorInfo $_
            Register-ItemError -Key ('PROFILE:discovery|' + $preflightProfileCategory) -Category $preflightProfileCategory -CountNow $true
            if ($preflightProfileCategory -ne 'AccessDenied') { $script:CoverageIncomplete = $true }
        }
        try {
            Test-FaultOperation -OperationId 'Preflight.Exclusions'
            Initialize-Exclusions -DriveRoots $script:LifecycleDriveRoots.ToArray()
        } catch {
            if (Test-StopError -Err $_) { throw }
            # Mandatory safety exclusions could not be constructed: traversal
            # with an unsafe/unknown policy is forbidden; the Full phase fails.
            $script:FullScanPlanSafe = $false
            $script:CoverageIncomplete = $true
        }

        # ---- Coverage accounting and persisted coverage boundary --------------
        if (($ScanPlan.Roots.Count + $ScanPlan.Files.Count) -gt 0) {
            $script:CanonicalRootsText = (($ScanPlan.Roots + $ScanPlan.Files) -join '; ')
        } else {
            $script:CanonicalRootsText = '(none)'
        }
        Write-TxtLogLine ('Canonical roots selected: ' + (ConvertTo-SafeText -Text $script:CanonicalRootsText))
        Write-TxtLogLine ('Active directory exclusions ({0} mode):' -f $Mode)
        foreach ($exEntry in $script:ExcludedPrefixes) { Write-TxtLogLine ('  - ' + (ConvertTo-SafeText -Text $exEntry)) }
        if ($script:UserExclusionList.Count -gt 0) {
            Write-TxtLogLine ('Operator -ExcludePath: ' + (ConvertTo-SafeText -Text ($script:UserExclusionList -join '; ')))
        }
        if ($script:IsDeepMode) {
            Write-TxtLogLine 'Deep mode: performance-only cache exclusions disabled; .git\objects remains excluded (Git-history credential coverage is unsupported).'
        }
        Write-TxtLogLine ''
        # An initialization-metadata write failure is OutputFailed, not a
        # harmless preflight skip: stop before scanning.
        if ($script:OutputFailed) { throw (New-Object System.OperationCanceledException) }

        # ---- Phase execution through the production phase runner --------------
        Test-FaultOperation -OperationId 'Lifecycle.Phases'
        Assert-CooperativeRunLimit
        Invoke-Phase -Name 'QuickWins' -Body { Invoke-QuickWins }
        if (-not $script:OutputFailed) { Assert-CooperativeRunLimit; Invoke-Phase -Name 'Environment' -Body { Invoke-EnvironmentChecks } }
        if (-not $script:OutputFailed) { Assert-CooperativeRunLimit; Invoke-Phase -Name 'Registry' -Body { Invoke-RegistryChecks } }
        if (-not $script:IsQuickMode -and -not $script:OutputFailed) {
            Assert-CooperativeRunLimit
            $transitionLine = '[*] Quick Wins complete; continuing with full scan because Mode is {0}' -f $Mode
            Write-ColorLine -Text $transitionLine -Color Cyan
            Write-TxtLogLine $transitionLine
            Invoke-Phase -Name 'FullScan' -Body { Invoke-FullScanPhase -Plan $ScanPlan }
        }
        if ($script:OutputFailed) {
            # Fatal streaming output failure: cancel remaining work exactly once.
            Stop-RemainingPhases
            Stop-RemainingRoots
        }
    } catch {
        if (Test-StopError -Err $_) {
            # Ctrl+C / pipeline stop / injected cancellation / fatal output
            # failure: cancel current and not-yet-attempted phases and roots
            # exactly once.
            if (-not $script:OutputFailed -and -not $script:CooperativeLimitReached) { $script:Interrupted = $true }
            $script:ExitCode = 1
            Stop-RemainingPhases
            Stop-RemainingRoots
            $stopLabel = 'interruption'
            if ($script:OutputFailed) { $stopLabel = 'output failure' }
            elseif ($script:CooperativeLimitReached) { $stopLabel = 'cooperative runtime limit' }
            Write-ColorLine -Text ('[!] Scan stopped ({0}); finalizing partial output.' -f $stopLabel) -Color Yellow
        } else {
            # Unexpected outer failure: sanitized diagnostics only (no raw
            # exception message, which can contain untrusted paths or data).
            # Exactly one summary is still attempted by the finally path below.
            $script:FatalOuterCatchCount++
            $script:CoverageIncomplete = $true
            $script:ExitCode = 1
            Stop-RemainingPhases
            Stop-RemainingRoots
            Write-ColorLine -Text ('[!] ERROR: an unexpected error interrupted the scan ({0}).' -f $_.Exception.GetType().Name) -Color Red
        }
    } finally {
        Complete-ScanProgress
        try {
            Complete-ScanOutputs
        } catch {
            Register-OutputFailure -Detail $_.Exception.GetType().Name
            Write-ColorLine -Text ('[!] ERROR: finalization failed ({0}).' -f $_.Exception.GetType().Name) -Color Red
        }
        Close-OutputFiles
        Close-DedupeHasher
        if ($script:ColorSupported) {
            try { [Console]::ForegroundColor = $script:OriginalColor } catch { }
        }
    }
}

# ---------------------------------------------------------------------------
# MAIN EXECUTION
# ---------------------------------------------------------------------------
if ($SelfTest -and $PerformanceDiagnostics) {
    Write-Host '[!] SelfTest and PerformanceDiagnostics are separate execution modes; run them independently.'
    exit 2
}
if ($SelfTest) {
    $selfTestCode = 2
    try {
        # Pattern initialization is part of the SelfTest execution boundary;
        # an initialization defect must produce the same fail-closed summary
        # and exit code 2 as an unhandled error in a test body.
        Initialize-Patterns
        # Capture the function's success/failure return as data. Any accidental
        # pipeline output makes the contract ambiguous and therefore fails
        # closed instead of being coerced to an unreliable process exit code.
        $selfTestResult = @(Invoke-SelfTest)
        if ($selfTestResult.Count -eq 1 -and
            $selfTestResult[0] -is [int] -and
            ($selfTestResult[0] -eq 0 -or $selfTestResult[0] -eq 2)) {
            $selfTestCode = [int]$selfTestResult[0]
        } else {
            $returnTypes = @($selfTestResult | ForEach-Object {
                if ($null -eq $_) { '<null>' } else { $_.GetType().FullName }
            })
            Write-Host ('[!] SelfTest return contract invalid: count={0}; types={1}' -f $selfTestResult.Count, ($returnTypes -join ','))
            Register-SelfTestAbort -Reason 'InvalidSelfTestReturnContract'
            $selfTestCode = 2
        }
    } catch {
        # Assign the failure code before diagnostics so even a secondary
        # reporting issue cannot turn an unhandled test error into success.
        $selfTestCode = 2
        Register-SelfTestAbort -Reason $_.Exception.GetType().Name
    } finally {
        Close-DedupeHasher
        Write-SelfTestResultSummary
    }
    if ($script:SelfTestFailures -gt 0 -or $script:SelfTestAborted -or
        -not $script:SelfTestReachedEnd -or
        $script:SelfTestExecuted -ne $script:SelfTestPlanned) {
        $selfTestCode = 2
    }
    exit $selfTestCode
}

# Branding is console-only and deliberately below the SelfTest exit boundary.
# These two lines precede every normal scan's operational information.
Write-ColorLine -Text '[ "In the deepest dark, the light." ]' -Color DarkCyan
Write-ColorLine -Text 'Summoned by: An0mal1    Manifested by: The Ghost in The Machine' -Color DarkCyan

# Normal scans initialize the same catalog after the SelfTest-only branch.
Initialize-Patterns

# The fault-injection seam can never survive into a normal scan.
Reset-FaultSeam

$script:IsElevated = Test-IsElevated
try {
    $script:CurrentUserSid = [string][System.Security.Principal.WindowsIdentity]::GetCurrent().User.Value
} catch {
    $script:CurrentUserSid = ''
}
try {
    if (-not [string]::IsNullOrEmpty($PSCommandPath)) {
        $normalizedScript = Get-PathIdentity -PathValue $PSCommandPath
        if ($null -ne $normalizedScript) { $script:ScriptPath = $normalizedScript }
    }
} catch { }

# Resolve the scan plan (roots and directly supplied files) up front so the
# startup banner can display the selected roots. Quick mode plans no full-scan
# phase; a supplied -Path in Quick mode is ignored with one warning (never
# silently planned and failed).
$scanPlan = @{ Roots = @(); Files = @(); Rejected = @(); RejectedRoots = @() }
if ($script:IsQuickMode) {
    if ($Path.Count -gt 0) {
        Write-ColorLine -Text '[!] -Path is ignored in Quick mode: no full-scan phase is planned. Use Standard or Deep for supplied paths.' -Color Yellow
    }
} else {
    try {
        $scanPlan = Get-ScanPlan
    } catch {
        $planCategory = Get-ItemErrorCategory -ErrorInfo $_
        Register-ItemError -Key ('FS:scan-plan|' + $planCategory) -Category $planCategory -CountNow $true
        $script:FullScanPlanSafe = $false
        $script:CoverageIncomplete = $true
        $script:ContentCoverageIncomplete = $true
        $script:Stats.VolumeDiscoveryFailures++
        $scanPlan = @{ Roots = @(); Files = @(); Rejected = @(); RejectedRoots = @() }
        Write-ColorLine -Text ('[!] Scan-plan discovery failed safely ({0}); targeted phases will still run.' -f $_.Exception.GetType().Name) -Color Yellow
    }
}

# Planned root/file state list (Standard/Deep only). Rejected supplied items
# are planned and immediately Failed.
if (-not $script:IsQuickMode) {
    foreach ($r in $scanPlan.Roots) { Add-RootState -Name $r -Kind 'Root' -State 'Pending' }
    foreach ($f in $scanPlan.Files) { Add-RootState -Name $f -Kind 'File' -State 'Pending' }
    foreach ($rej in $scanPlan.Rejected) { Add-RootState -Name $rej -Kind 'File' -State 'Failed' }
    foreach ($rejRoot in $scanPlan.RejectedRoots) { Add-RootState -Name $rejRoot -Kind 'Root' -State 'Failed' }
}

# Phase plan: Quick plans three phases; Standard/Deep plan all four.
Add-PhaseState -Name 'QuickWins'
Add-PhaseState -Name 'Environment'
Add-PhaseState -Name 'Registry'
if (-not $script:IsQuickMode) { Add-PhaseState -Name 'FullScan' }

# All filesystem drive roots seed the built-in exclusions even in Quick mode
# (recycle bin / system metadata directories live per-drive). A discovery
# failure here makes the full-scan plan unsafe (phase Failed, no traversal).
$allDriveRoots = New-Object System.Collections.Generic.List[string]
$exclDrives = $null
if (-not $script:IsQuickMode -and $scanPlan.Roots.Count -gt 0) {
    # Planned local roots (including folder-mounted volumes) are the primary
    # exclusion universe. Do not make a second PSDrive query a new fatal gate.
    $exclDrives = @()
} elseif ($script:FaultSeam.Enabled -and $null -ne $script:FaultSeam.DriveList) {
    $exclDrives = @($script:FaultSeam.DriveList)
} else {
    try { $exclDrives = @(Get-PSDrive -PSProvider FileSystem) }
    catch {
        $exclusionDriveCategory = Get-ItemErrorCategory -ErrorInfo $_
        Register-ItemError -Key ('FS:exclusion-drive-discovery|' + $exclusionDriveCategory) -Category $exclusionDriveCategory -CountNow $true
        $exclDrives = $null
    }
}
if ($null -eq $exclDrives) {
    $script:FullScanPlanSafe = $false
    $script:CoverageIncomplete = $true
} else {
    foreach ($d in $exclDrives) {
        $exclusionDriveRoot = [string](Get-OptionalObjectValue -Object $d -Name 'Root')
        if (-not [string]::IsNullOrEmpty($exclusionDriveRoot) -and -not $exclusionDriveRoot.StartsWith('\\')) {
            $allDriveRoots.Add($exclusionDriveRoot)
        }
    }
}
if (-not $script:IsQuickMode) {
    foreach ($plannedRoot in $scanPlan.Roots) {
        if (-not ([string]$plannedRoot).StartsWith('\\') -and -not $allDriveRoots.Contains([string]$plannedRoot)) {
            $allDriveRoots.Add([string]$plannedRoot)
        }
    }
}

# ---- Startup banner ---------------------------------------------------------
Write-ColorLine -Text ('[*] {0} v{1} started - {2}' -f $script:ToolName, $script:ToolVersion, (Get-Date)) -Color Green
Write-ColorLine -Text ('[*] Mode                : {0}' -f $Mode) -Color Green
Write-ColorLine -Text ('[*] Elevated            : {0}' -f $(if ($script:IsElevated) { 'Yes' } else { 'No' })) -Color Green
Write-ColorLine -Text ('[*] RevealSecrets       : {0}' -f $(if ($script:RevealActive) { 'On' } else { 'Off' })) -Color Green
Write-ColorLine -Text ('[*] Per-file read budget: {0} MB' -f $MaxFileSizeMB) -Color Green
Write-ColorLine -Text ('[*] Large-file mode     : {0}' -f $script:LargeFileModeActive) -Color Green
Write-ColorLine -Text ('[*] Cooperative limit  : {0}' -f $(if ($script:MaxRunMinutesActive -gt 0) { ($script:MaxRunMinutesActive.ToString() + ' minutes') } else { 'Disabled' })) -Color Green
if ($script:LargeFileModeActive -eq 'Full') {
    Write-ColorLine -Text '[!] Full large-file mode keeps memory bounded but I/O and duration are not bounded.' -Color Yellow
}
$rootDescription = ''
if ($script:IsQuickMode) {
    $rootDescription = 'Quick mode: targeted checks only (no drive traversal)'
} elseif ($Path.Count -gt 0) {
    $rootDescription = (($scanPlan.Roots + $scanPlan.Files) -join '; ')
    if ([string]::IsNullOrEmpty($rootDescription)) { $rootDescription = '(no valid supplied paths)' }
} else {
    $rootDescription = ($scanPlan.Roots -join '; ')
    if ([string]::IsNullOrEmpty($rootDescription)) { $rootDescription = '(no eligible local roots found)' }
}
Write-ColorLine -Text ('[*] Selected roots      : {0}' -f (ConvertTo-SafeText -Text $rootDescription)) -Color Green
if ($script:RevealActive) {
    Write-ColorLine -Text '[!] WARNING: -RevealSecrets is active. Output files will contain sensitive plaintext credentials.' -Color Yellow
}

# ---- Output setup (fatal before scanning on failure) ------------------------
if (-not (Initialize-OutputFiles)) {
    $script:ExitCode = 1
    exit 1
}

# ---- Protected lifecycle (begins immediately after successful output init) --
$script:LifecycleDriveRoots.Clear()
foreach ($adr in $allDriveRoots) { $script:LifecycleDriveRoots.Add($adr) }
Invoke-ProtectedLifecycle -ScanPlan $scanPlan

exit $script:ExitCode
